-- Varmak Workshop — the whole database, in one file, for a SQL editor.
--
-- GENERATED by backend/make-supabase-install.sh from schema.sql, auth.sql, api.sql and views.sql.
-- Do not edit this file: edit those and run the script again. There is nothing in here to fill in.
--
-- Paste the whole thing into the SQL editor and press Run, once. It makes the tables, the rules
-- about who may read what, the workflows and the views, and then checks that it worked — if
-- anything is missing you get an error saying which part, not a quiet half-install.
--
-- It does NOT set the server's password and it does not create any person. Both are separate, on
-- purpose: the password is backend/supabase-password.sql, the first administrator is /admin.html.
--
-- It goes into an EMPTY database and refuses any other kind, in its first few lines and before it
-- writes anything. Nothing in here is repeatable — none of the 39 tables or 18 counters is created
-- with IF NOT EXISTS, because a table that already exists is a database somebody is already using
-- and the last thing it needs is this file guessing. A second run is refused, in words.
--
-- If a run fails partway it is undone completely: the editor runs the whole file in one
-- transaction and this file takes care not to end it early. So a failure leaves the database as
-- empty as it was, and pasting it again after fixing what the error said is the right thing to do.
--
-- From a terminal, use backend/install.sh instead. This file has no transaction of its own —
-- it relies on the editor's — so psql would commit it statement by statement.

-- ═══════════════════════════════════════════════════════════════════════════════════════════
-- Is this database empty?
-- ═══════════════════════════════════════════════════════════════════════════════════════════
--
-- Added by backend/make-supabase-install.sh. Without it, a second run stops on "relation
-- seq_customer already exists" — true, unhelpful, and 48 lines into a 7,000-line file. Asked
-- first, so the answer arrives before anything is written and in a sentence that says what to do.

DO $precheck$
BEGIN
  -- invoice_basis is the last thing the last file makes; seq_customer is the first thing the first
  -- file makes. Between them they tell a finished install from one that stopped partway, and those
  -- two cases need opposite advice.
  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
              WHERE n.nspname = 'public' AND p.proname = 'invoice_basis') THEN
    RAISE EXCEPTION E'Nothing was changed: Varmak Workshop is already installed in this database.\n\nIf this is the database you meant, you are finished with this file — next is backend/supabase-password.sql.\nIf you meant to start over, make a new empty database and paste this into that one. Running it here would not clear anything out, and this refuses rather than make a mess of a database somebody may already be working in.';
  END IF;
  IF to_regclass('public.seq_customer') IS NOT NULL THEN
    RAISE EXCEPTION E'Nothing was changed: this database holds part of Varmak Workshop — an install that stopped partway.\n\nThis file only installs into an empty database, so the result is never half of one. Make a new empty database and paste this into that one.';
  END IF;
END
$precheck$;

-- ═══════════════════════════════════════════════════════════════════════════════════════════
-- schema.sql
-- ═══════════════════════════════════════════════════════════════════════════════════════════

-- Varmak Workshop — the database.
--
-- This is step 1 and 2 of the order agreed in BACKEND.md: the schema and its constraints, with
-- the safety rules as triggers from the start, and numbering as sequences before two people ever
-- use it. "Add the constraints later" was ruled out on purpose — later never comes, and by then
-- there is data that violates them.
--
-- The principle that decides what lives here: anything that must be true no matter who is asking.
-- The browser checks the same things to save a round trip and to grey a button out before it is
-- pressed, but the browser is convenience. This file is the floor nothing falls through.
--
-- Written for PostgreSQL 16 and run against it. Every constraint and every trigger in here has a
-- test in backend/test-schema.js that hands it the thing it exists to refuse and asserts both the
-- refusal and its wording: 110 refusals across 68 checks, plus 58 things the schema must still
-- allow — because a gate that says no to everything passes every refusal test and is useless.
-- Three of the checks start a second session, because the failures that matter most (two people
-- taking one document number, two people adding to one item group, two people issuing the last of
-- something) cannot be reproduced with one.
--
-- backend/mutation-check.js then asks the question passing tests cannot: it puts each rule's bug
-- back, one at a time, and fails if the suite sleeps through it. Four of the bugs it now guards
-- against were really in this file, and three of those survived a careful reading of it:
--
--   • The hold gates only ran on UPDATE, so a jobcard created already 'completed' walked straight
--     past them — the status never transitioned, so the trigger never looked.
--   • The hours roll-up only recomputed the operation named on the row it was handed, so an entry
--     booked to the wrong operation and corrected left the hours on both. The same three hours,
--     counted twice, in a figure work is priced from.
--   • Nothing stopped an hours entry naming one jobcard and an operation belonging to another.
--   • The expired-certification refusal read "Fixture MIG 400s certification expired": %s in a
--     RAISE is the placeholder followed by a literal s, not a possessive.
--
-- And one thing the mutation check found that reading could not: the test for "stock can never go
-- below zero" was standing on the wrong constraint, and passed with its own rule deleted.

-- BEGIN; (removed: the SQL editor opens the transaction that covers all four files)

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Numbering
--
-- Document numbers came from a counter in the browser. Two people creating a customer at the same
-- moment both got C-001, and neither knew. Measured, not supposed. A sequence is the one place
-- that cannot happen: Postgres hands out each value once, even to concurrent transactions, and
-- even if the transaction that took it rolls back — a gap in the numbering is not a problem, two
-- documents with one number is.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE SEQUENCE seq_customer;
CREATE SEQUENCE seq_project;
CREATE SEQUENCE seq_jobcard;
CREATE SEQUENCE seq_hold;
CREATE SEQUENCE seq_inspection;
CREATE SEQUENCE seq_movement;
CREATE SEQUENCE seq_supplier;
CREATE SEQUENCE seq_lead;
CREATE SEQUENCE seq_opportunity;
CREATE SEQUENCE seq_tender;
CREATE SEQUENCE seq_estimate;
CREATE SEQUENCE seq_purchase_order;
CREATE SEQUENCE seq_ncr;
CREATE SEQUENCE seq_offcut;
CREATE SEQUENCE seq_document;

-- Human-readable references, built from the sequence rather than from a count of existing rows.
-- Counting rows is what breaks the moment anything is deleted or two writers race.
CREATE FUNCTION next_ref(prefix text, seq regclass, digits int DEFAULT 4) RETURNS text
LANGUAGE sql VOLATILE AS $$
  SELECT prefix || lpad(nextval(seq)::text, digits, '0');
$$;

CREATE FUNCTION next_dated_ref(prefix text, seq regclass, digits int DEFAULT 4) RETURNS text
LANGUAGE sql VOLATILE AS $$
  SELECT prefix || '-' || to_char(now(), 'YYYY') || '-' || lpad(nextval(seq)::text, digits, '0');
$$;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Who is asking
--
-- Two roles are in use, as decided in BACKEND.md §1b for a workshop of two to four people: an
-- admin who runs the place, and the workshop, who book hours, start and pause operations, issue
-- material and record inspection results, and see no prices at all. `office` is in the enum from the start
-- but nobody holds it — the day somebody is hired to do the quoting it is a role change, not a
-- migration. The role lives on the row rather than in application code, because the API is not
-- the only thing that will ever connect to this database.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE TYPE user_role AS ENUM ('admin', 'office', 'workshop');

CREATE TABLE app_user (
  id            bigserial PRIMARY KEY,
  email         text NOT NULL UNIQUE CHECK (email = lower(btrim(email)) AND email <> ''),
  display_name  text NOT NULL CHECK (btrim(display_name) <> ''),
  role          user_role NOT NULL DEFAULT 'workshop',
  -- The password is never stored, only what it hashes to.
  --
  -- The first version of this table had password_hash beside a password_salt column, with a
  -- constraint that the two were set together. That was wrong: bcrypt's output already carries its
  -- algorithm, cost and salt, so a separate salt column is at best redundant and at worst a place
  -- to put a salt that is not the one the hash was made with. What the constraint was reaching for
  -- is written directly instead — the column has to LOOK like a bcrypt hash, which is what makes
  -- storing a plain-text password impossible rather than merely discouraged.
  password_hash text CONSTRAINT password_is_hashed
                CHECK (password_hash IS NULL OR password_hash ~ '^\$2[aby]\$\d{2}\$'),
  is_active     boolean NOT NULL DEFAULT true,
  created_at    timestamptz NOT NULL DEFAULT now()
);

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Customers, projects, jobcards
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE customer (
  id          bigserial PRIMARY KEY,
  ref         text NOT NULL UNIQUE DEFAULT next_ref('C-', 'seq_customer'::regclass, 3),
  name        text NOT NULL CHECK (btrim(name) <> ''),
  org_no      text,
  vat_no      text,
  email       text,
  phone       text,
  city        text,
  country     text,
  status      text NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive','prospect')),
  credit_limit numeric(12,2) CHECK (credit_limit IS NULL OR credit_limit >= 0),
  -- Everything below was added in step 5, from backend/coverage.js: these are fields the customer
  -- screens already read and the first version of this table could not hold. The schema was built
  -- from the twenty-five-table plan in BACKEND.md §2, which trimmed the collections but not the
  -- fields inside them, so pointing the frontend at it would have left these blank.
  website     text,
  industry    text,
  customer_since date,
  payment_terms_days int CHECK (payment_terms_days IS NULL OR payment_terms_days >= 0),
  currency    char(3) NOT NULL DEFAULT 'SEK' CHECK (currency = upper(currency)),
  customer_type text CHECK (customer_type IS NULL OR customer_type IN ('direct','reseller','oem','public')),
  is_preferred boolean NOT NULL DEFAULT false,
  -- How this customer wants to be contacted — 'Email', 'Phone', 'Post'. A different fact from
  -- is_preferred above, and the two were conflated: the customer screen's field is called
  -- `preferred` and means the contact method, the snapshot was handing it is_preferred, and the page
  -- would have shown "true" where it says Preferred Contact. Two facts, two columns, and the names
  -- are now far enough apart to stop happening again.
  preferred_contact text,
  price_list  text,
  delivery_terms text,
  discount_agreement text,
  billing_address text,
  -- Where the steel goes, which is not always where the invoice goes. The customer screen has always
  -- shown the two addresses side by side and had one column between them, so the shipping card was
  -- showing the billing address under a heading that said otherwise.
  shipping_address text,
  notes       text,
  created_at  timestamptz NOT NULL DEFAULT now()
);

-- The people at the customer, which the customer screen has always held as a list on the record and
-- which therefore has never been able to have a rule about it. Two of them matter.
--
-- One main contact, not several. The screen marks the first in its array as primary, so a list with
-- two of them is not something the page can even show — and "ring the main contact" is an instruction
-- somebody follows at four in the afternoon when a drawing is wrong. The partial unique index is the
-- guarantee; set_customer_contacts() refuses first so the person reads a sentence rather than the
-- name of an index.
CREATE TABLE customer_contact (
  id          bigserial PRIMARY KEY,
  customer_id bigint NOT NULL REFERENCES customer(id) ON DELETE CASCADE,
  name        text NOT NULL CHECK (btrim(name) <> ''),
  role        text,
  email       text,
  phone       text,
  is_primary  boolean NOT NULL DEFAULT false,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX customer_has_one_main_contact
  ON customer_contact (customer_id) WHERE is_primary;

-- And a contact anybody is expected to reach has to be reachable. A row with a name and no way to
-- get hold of them is a row that looks like a contact and is not one.
ALTER TABLE customer_contact ADD CONSTRAINT contact_can_be_reached
  CHECK (coalesce(btrim(email), '') <> '' OR coalesce(btrim(phone), '') <> '');

-- One spelling per state. The frontend carries two names for one of them — `active` in the
-- Estimations page's vocabulary, `production` from the estimate-conversion path, aliased to each
-- other in project-rules.js — and `draft` as a retired alias of `quotation`. A database that
-- accepted all of them would mean every query had to know the aliases, so the canonical spelling
-- is fixed here and the API translates on the way in. `approved` is a real step in the quoting
-- chain and is included; it was missing from the first draft of this file.
CREATE TYPE project_status AS ENUM
  ('quotation','approved','planned','production','hold','completed','closed','cancelled');

CREATE TABLE project (
  id            bigserial PRIMARY KEY,
  ref           text NOT NULL UNIQUE DEFAULT next_dated_ref('P', 'seq_project'::regclass, 3),
  name          text NOT NULL CHECK (btrim(name) <> ''),
  -- A project cannot belong to a customer who does not exist. Restricting the delete rather than
  -- cascading is deliberate: losing a customer must never silently take their jobs with them.
  customer_id   bigint NOT NULL REFERENCES customer(id) ON DELETE RESTRICT,
  status        project_status NOT NULL DEFAULT 'quotation',
  planned_hours numeric(10,2) NOT NULL DEFAULT 0 CHECK (planned_hours >= 0),
  progress      int NOT NULL DEFAULT 0 CHECK (progress BETWEEN 0 AND 100),
  deadline      date,
  -- Where the job came from and what it is. estimate_id is the quotation this became; the trail
  -- back to the tender and the enquiry hangs off that.
  description   text,
  phase         text,
  work_types    text,
  po_number     text,
  workshop      text,
  responsible   text,
  material_status text CHECK (material_status IS NULL OR
                  material_status IN ('not-ordered','ordered','part-arrived','arrived','issued')),
  notes         text,
  -- Planned against actual. Four dates rather than two, because "when did it really start" is the
  -- question every late job is argued about and it cannot be recovered from a status.
  planned_start date,
  actual_start  date,
  planned_completion date,
  expected_completion date,
  actual_completion date,
  closed_on     date,
  -- Hours actually worked, maintained from the entries by trigger below — never typed, for the
  -- same reason an operation's logged hours are not.
  used_hours    numeric(10,2) NOT NULL DEFAULT 0 CHECK (used_hours >= 0),
  quoted_value  numeric(12,2) CHECK (quoted_value IS NULL OR quoted_value >= 0),
  -- Why it stopped, and why it was cancelled. A project on hold with no reason written down is a
  -- project nobody can restart without asking three people.
  hold_reason   text,
  hold_comment  text,
  expected_resume date,
  cancel_reason text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  CHECK (actual_completion IS NULL OR actual_start IS NULL OR actual_completion >= actual_start),
  -- A project cannot be on hold for no reason, or cancelled for none. Both statuses are decisions
  -- somebody made, and the record has to say what the decision was.
  CONSTRAINT held_project_says_why CHECK (status <> 'hold' OR btrim(coalesce(hold_reason,'')) <> ''),
  CONSTRAINT cancelled_project_says_why
    CHECK (status <> 'cancelled' OR btrim(coalesce(cancel_reason,'')) <> '')
);

CREATE TYPE jobcard_status AS ENUM
  ('draft','released','ready','in-progress','inspection','completed','closed',
   'paused','blocked','cancelled');

CREATE TABLE jobcard (
  id            bigserial PRIMARY KEY,
  ref           text NOT NULL UNIQUE DEFAULT next_dated_ref('JC', 'seq_jobcard'::regclass, 4),
  project_id    bigint NOT NULL REFERENCES project(id) ON DELETE RESTRICT,
  title         text NOT NULL CHECK (btrim(title) <> ''),
  item          text,
  quantity      int NOT NULL DEFAULT 1 CHECK (quantity > 0),
  drawing_no    text,
  status        jobcard_status NOT NULL DEFAULT 'draft',
  planned_hours numeric(10,2) NOT NULL DEFAULT 0 CHECK (planned_hours >= 0),
  planned_start date,
  planned_completion date,
  archived      boolean NOT NULL DEFAULT false,
  -- Kept from day one on the decision in BACKEND.md §2: no certification subsystem is being
  -- built, but which material went into which job is a fact that cannot be recovered later.
  heat_no       text,
  material_cert_ref text,
  -- Which customer, kept beside the project rather than only reached through it: a jobcard is what
  -- the floor holds, and whose job it is is the first thing anybody asks about one.
  customer_id   bigint REFERENCES customer(id) ON DELETE RESTRICT,
  revision      text,
  work_type     text,
  location      text,
  -- low, medium, high — the three the jobcard screen offers in its dropdown. 'normal' and 'urgent'
  -- came from the table plan and are in nobody's vocabulary: the screen has never written either, and
  -- the value it does write for the middle one, 'medium', this column refused. One spelling per state,
  -- and the spelling is the screen's.
  priority      text CHECK (priority IS NULL OR priority IN ('low','medium','high')),
  responsible   text,
  created_by    text,
  notes         text,
  -- Is the steel there yet. A job released to the floor without its material is the most common
  -- reason work stops after it has started.
  -- The four words the jobcard screen actually uses, rather than the three this column was invented
  -- with. BACKEND.md's rule is one spelling per state, and when the two disagree the screen wins:
  -- 'not-checked', 'shortage', 'partial' and 'available' are what somebody picks from a dropdown and
  -- what the whole page is written around. 'none'/'partial'/'ready' came from the table plan and were
  -- never anybody's words — and translating between them would have had to fold 'shortage' and
  -- 'partial' onto one value, losing the difference between "some is missing" and "some is here".
  material_readiness text CHECK (material_readiness IS NULL OR
                       material_readiness IN ('not-checked','shortage','partial','available')),
  -- Whether this job needs signing off before it leaves. Read by the jobcard screen, the quality
  -- screen and equipment-gates.js, and it had nowhere to live: coverage.js reported it as width
  -- nobody misses, because the test for "is this field read anywhere" missed every read written as
  -- `j.inspectionRequired ? a : b`. Distinct from operation.inspection_checkpoint, which marks one
  -- step; this is the job as a whole.
  inspection_required boolean NOT NULL DEFAULT false,
  delivery_target date,
  actual_start  date,
  actual_completion date,
  progress      int NOT NULL DEFAULT 0 CHECK (progress BETWEEN 0 AND 100),
  created_at    timestamptz NOT NULL DEFAULT now(),
  CHECK (planned_completion IS NULL OR planned_start IS NULL OR planned_completion >= planned_start),
  CHECK (actual_completion IS NULL OR actual_start IS NULL OR actual_completion >= actual_start)
);

CREATE INDEX jobcard_project_idx ON jobcard(project_id);

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Which status may follow which
--
-- A table rather than a CASE statement, because this is the part of the workflow most likely to be
-- argued about and changed, and a row is something the argument can be settled by editing. The
-- pairs below are lifted from ALLOWED_TRANSITIONS in jobcard-desktop.html and from the can* rules
-- in project-rules.js — the existing suite is the specification, so the database agrees with it
-- rather than with a graph invented here.
--
-- Two things the frontend map does implicitly are written out: a job resumes from paused or blocked
-- to one of the four statuses it could have been paused from (VALID_RESUME_TARGETS in
-- jobcard-rules.js), and a status may always be set to itself, so an update that touches other
-- columns is not refused for a status it never changed.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE allowed_transition (
  entity      text NOT NULL CHECK (entity IN ('jobcard','project')),
  from_status text NOT NULL,
  to_status   text NOT NULL,
  PRIMARY KEY (entity, from_status, to_status),
  CHECK (from_status <> to_status),
  -- The statuses are held as text because two different enums share this table, which leaves room
  -- for a typo — and a typo here is not an error, it is a rule that quietly does nothing, or a
  -- missing rule that quietly refuses real work. The cast is what closes that: an enum cast on a
  -- label that does not exist raises, so the bad row never lands.
  CONSTRAINT statuses_are_real CHECK (
    CASE entity
      WHEN 'jobcard' THEN from_status::jobcard_status IS NOT NULL AND to_status::jobcard_status IS NOT NULL
      WHEN 'project' THEN from_status::project_status IS NOT NULL AND to_status::project_status IS NOT NULL
    END
  )
);

INSERT INTO allowed_transition (entity, from_status, to_status) VALUES
  ('jobcard','draft','released'),        ('jobcard','draft','cancelled'),
  ('jobcard','released','ready'),        ('jobcard','released','draft'),
  ('jobcard','released','paused'),       ('jobcard','released','blocked'),
  ('jobcard','released','cancelled'),
  ('jobcard','ready','in-progress'),     ('jobcard','ready','released'),
  ('jobcard','ready','paused'),          ('jobcard','ready','blocked'),
  ('jobcard','ready','cancelled'),
  ('jobcard','in-progress','inspection'),('jobcard','in-progress','paused'),
  ('jobcard','in-progress','blocked'),
  ('jobcard','inspection','completed'),  ('jobcard','inspection','in-progress'),
  ('jobcard','inspection','paused'),     ('jobcard','inspection','blocked'),
  ('jobcard','completed','closed'),
  -- Resuming: back to whichever of these it was paused from.
  ('jobcard','paused','released'),       ('jobcard','paused','ready'),
  ('jobcard','paused','in-progress'),    ('jobcard','paused','inspection'),
  ('jobcard','blocked','released'),      ('jobcard','blocked','ready'),
  ('jobcard','blocked','in-progress'),   ('jobcard','blocked','inspection'),

  ('project','quotation','approved'),    ('project','quotation','cancelled'),
  ('project','approved','planned'),      ('project','approved','cancelled'),
  ('project','planned','production'),    ('project','planned','hold'),
  ('project','planned','cancelled'),
  ('project','production','hold'),       ('project','production','completed'),
  ('project','production','cancelled'),
  ('project','hold','production'),       ('project','hold','planned'),
  ('project','hold','cancelled'),
  ('project','completed','closed'),
  -- Reopening a closed project, to either of the two states the screen offers.
  ('project','closed','production'),     ('project','closed','completed');

-- `closed` on a jobcard and `cancelled` on both are deliberately absent as a from_status: they are
-- the end. Anything else is a new document, which is the point — a cancelled job that can be
-- quietly un-cancelled is a job whose history says something that did not happen.

CREATE FUNCTION status_flow_gate() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  entity_name text := TG_ARGV[0];
BEGIN
  IF NEW.status::text = OLD.status::text THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM allowed_transition
     WHERE entity = entity_name
       AND from_status = OLD.status::text
       AND to_status = NEW.status::text
  ) THEN
    RAISE EXCEPTION '% % cannot go from % to %; from % it may only become %',
      entity_name, NEW.ref, OLD.status, NEW.status, OLD.status,
      COALESCE((SELECT string_agg(to_status, ', ' ORDER BY to_status) FROM allowed_transition
                 WHERE entity = entity_name AND from_status = OLD.status::text), 'nothing — it is finished')
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Equipment
-- ─────────────────────────────────────────────────────────────────────────────────────────────

-- The words the screen uses, and they look like screen labels because they are.
--
-- This is the rule from `material_readiness` and the jobcard priority applied a third time: one spelling
-- per state, and when the schema and the screen disagree the screen wins, because those are the words
-- somebody picks from a dropdown. Here it was not a preference. The equipment screen compares
-- `item.status === 'Out of Service'` exactly, in seven places, and equipment-gates.js holds its
-- vocabulary as 'out of service' — with spaces — and **fails closed on a status it does not recognise**.
-- So a hyphenated 'out-of-service' arriving from the snapshot was not merely ugly: it was unrecognised,
-- which the gate treats as unsafe. 'in-use' was worse, because a machine on a bench is perfectly
-- runnable and the gate had no way to know it.
--
-- That was live. `equipment` has been in the snapshot since step 5 and the jobcard screen is wired, so
-- attaching any machine to a jobcard there was refused by a gate that could not read the status of any
-- machine in the workshop. Nothing threw; the gate did exactly what it says it does.
--
-- 'Inspection Required' is new here as well: the screen offers it, the gate blocks on it, and the enum
-- did not have it at all, so the one state a workshop uses for "fine, but it must be looked at first"
-- could not be recorded.
CREATE TYPE equipment_status AS ENUM
  ('Available', 'In Use', 'Maintenance Due', 'Under Maintenance', 'Inspection Required',
   'Out of Service', 'Quarantined', 'Retired');

CREATE TABLE equipment (
  id          bigserial PRIMARY KEY,
  ref         text NOT NULL UNIQUE,
  name        text NOT NULL CHECK (btrim(name) <> ''),
  category    text NOT NULL,
  status      equipment_status NOT NULL DEFAULT 'Available',
  certification_expiry date,
  -- What the machine is. A serial number and an asset number are how a machine is identified to an
  -- insurer and to an auditor, and neither can be recovered later from a name.
  manufacturer text,
  model       text,
  serial_no   text,
  asset_no    text UNIQUE,
  year_of_manufacture int CHECK (year_of_manufacture IS NULL OR year_of_manufacture BETWEEN 1900 AND 2100),
  description text,
  -- Where it is and whose it is. current_location is where it is now, home_location where it lives.
  current_location text,
  home_location text,
  department  text,
  responsible_person text,
  operator    text,
  -- How much it matters and what state it is in, which is what decides whether a breakdown stops
  -- the shop or is dealt with next week.
  -- The same rule as the status above, two columns further down: these are the words the register
  -- offers, and the register is where somebody picks them. The criticality dropdown has offered
  -- 'Low'/'Medium'/'High'/'Critical' since it was written, so a lower-case check refused every value the
  -- screen could send — which is how the first machine saved from that form was turned away.
  condition   text CHECK (condition IS NULL OR condition IN ('New', 'Good', 'Fair', 'Poor', 'Unserviceable')),
  criticality text CHECK (criticality IS NULL OR criticality IN ('Low', 'Medium', 'High', 'Critical')),
  safety_warnings text,
  -- What it cost and what is still covered.
  purchase_date date,
  purchase_supplier text,
  purchase_price numeric(12,2) CHECK (purchase_price IS NULL OR purchase_price >= 0),
  warranty_expiry date,
  -- Servicing. The meter is what interval-based maintenance is counted against, so it is a number
  -- rather than a note.
  operating_hours numeric(10,1) NOT NULL DEFAULT 0 CHECK (operating_hours >= 0),
  service_interval_hours int CHECK (service_interval_hours IS NULL OR service_interval_hours > 0),
  last_service_date date,
  last_inspection_date date,
  last_calibration_date date,
  qr_code     text UNIQUE,
  -- Whether a welder has to sign a check before running this machine. A flag rather than a rule
  -- applied to everything, because it is true of a crane and a press and false of a bench grinder, and
  -- a system that demanded a signed check for the grinder would teach people to sign without looking.
  -- equipment-gates.js has read this through a `requirements` object since it was written; nothing has
  -- ever been able to set it, so the answer was always "not required".
  pre_use_check_required boolean NOT NULL DEFAULT false,
  -- What it is on right now. Restricted rather than cascading: losing a project must not quietly
  -- detach every machine that was working on it.
  assigned_project_id bigint REFERENCES project(id) ON DELETE SET NULL,
  notes       text,
  created_at  timestamptz NOT NULL DEFAULT now(),
  CHECK (warranty_expiry IS NULL OR purchase_date IS NULL OR warranty_expiry >= purchase_date)
);

-- A machine assigned to one jobcard cannot be assigned to another at the same time. Expressed as
-- a partial unique index rather than checked in code: the database refuses the second assignment
-- even if two requests arrive together, which application code cannot promise.
CREATE TABLE equipment_assignment (
  id            bigserial PRIMARY KEY,
  equipment_id  bigint NOT NULL REFERENCES equipment(id) ON DELETE RESTRICT,
  jobcard_id    bigint NOT NULL REFERENCES jobcard(id) ON DELETE CASCADE,
  assigned_at   timestamptz NOT NULL DEFAULT now(),
  released_at   timestamptz,
  CHECK (released_at IS NULL OR released_at >= assigned_at)
);

CREATE UNIQUE INDEX equipment_one_live_assignment
  ON equipment_assignment(equipment_id) WHERE released_at IS NULL;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Operations
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE TYPE operation_status AS ENUM
  ('pending','in-progress','paused','completed','skipped');

CREATE TABLE operation (
  id            bigserial PRIMARY KEY,
  jobcard_id    bigint NOT NULL REFERENCES jobcard(id) ON DELETE CASCADE,
  seq           int NOT NULL CHECK (seq > 0),
  description   text NOT NULL CHECK (btrim(description) <> ''),
  instructions  text,
  -- The welder's name and the filler used. Same reason as the heat number above: if certification
  -- is pursued in two years this history is the difference between starting from a record and
  -- starting from nothing, and it cannot be back-filled then.
  worker        text,
  filler        text,
  equipment_id  bigint REFERENCES equipment(id) ON DELETE SET NULL,
  planned_hours numeric(8,2) NOT NULL DEFAULT 0 CHECK (planned_hours >= 0),
  -- Logged hours are a running total written by the hours entries below, never typed in directly.
  logged_hours  numeric(8,2) NOT NULL DEFAULT 0 CHECK (logged_hours >= 0),
  status        operation_status NOT NULL DEFAULT 'pending',
  depends_on    bigint REFERENCES operation(id) ON DELETE SET NULL,
  planned_start date,
  actual_start  date,
  actual_completion date,
  -- A step that has to be signed off before the next one may begin. Distinct from an inspection
  -- record: this is the flag on the plan that says one is required here.
  inspection_checkpoint boolean NOT NULL DEFAULT false,
  notes         text,
  CHECK (actual_completion IS NULL OR actual_start IS NULL OR actual_completion >= actual_start),
  -- Deferrable, and that is the whole reason it is named. Re-ordering the steps on a jobcard means
  -- writing seq 1 where seq 2 was while 1 is still 1, and an immediately-checked unique index refuses
  -- the halfway state even though the finished list is fine. Deferred, it is checked once at the end
  -- of the transaction — the rule is identical, the intermediate collision is not. The alternative was
  -- renumbering through negative numbers, which CHECK (seq > 0) refuses and rightly.
  CONSTRAINT operation_one_step_per_place UNIQUE (jobcard_id, seq) DEFERRABLE INITIALLY IMMEDIATE,
  -- An operation cannot depend on itself. A longer cycle is caught by the trigger below.
  CHECK (depends_on IS DISTINCT FROM id)
);

CREATE INDEX operation_jobcard_idx ON operation(jobcard_id);

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Hours
--
-- One row per entry, per person, per day. The operation's running total is maintained by trigger
-- rather than by whoever happens to be writing, so the total and the entries can never disagree.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE hours_entry (
  id            bigserial PRIMARY KEY,
  jobcard_id    bigint NOT NULL REFERENCES jobcard(id) ON DELETE RESTRICT,
  operation_id  bigint REFERENCES operation(id) ON DELETE SET NULL,
  worker        text NOT NULL CHECK (btrim(worker) <> ''),
  hours         numeric(6,2) NOT NULL CHECK (hours > 0 AND hours <= 24),
  worked_on     date NOT NULL DEFAULT current_date,
  note          text,
  created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX hours_jobcard_idx ON hours_entry(jobcard_id);
CREATE INDEX hours_worked_on_idx ON hours_entry(worked_on);

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Store
-- ─────────────────────────────────────────────────────────────────────────────────────────────

-- Groups and locations are both trees exactly one level deep in practice (a group with subgroups,
-- a warehouse with sublocations) but modelled as a self-reference, because "one level" is the kind
-- of assumption that gets expensive. A group cannot be its own parent.
CREATE TABLE item_group (
  id          bigserial PRIMARY KEY,
  code        text NOT NULL UNIQUE CHECK (btrim(code) <> ''),
  name        text NOT NULL CHECK (btrim(name) <> ''),
  parent_id   bigint REFERENCES item_group(id) ON DELETE RESTRICT,
  -- Item numbering runs per group — every group starts at 1 — so a global sequence cannot do it
  -- and the counter has to live on the row. That is the same shape as the browser counter that
  -- handed two people one number, and it is only safe if it is incremented the way
  -- next_item_number() below does it. Nothing else may read this column to decide a number.
  next_number int NOT NULL DEFAULT 1 CHECK (next_number > 0),
  CHECK (parent_id IS DISTINCT FROM id)
);

-- Per-group item numbers, taken safely. The UPDATE ... RETURNING is one statement, so it takes the
-- row lock and hands back the number it wrote: two callers arriving together are serialised by the
-- lock and get different numbers. Reading the counter and writing it back separately is what
-- cannot be done, and is why this exists as a function rather than as a note in a document.
CREATE FUNCTION next_item_number(p_group_id bigint) RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  taken int;
  prefix text;
BEGIN
  UPDATE item_group SET next_number = next_number + 1
   WHERE id = p_group_id
   RETURNING next_number - 1, code INTO taken, prefix;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such item group' USING ERRCODE = 'foreign_key_violation';
  END IF;
  RETURN prefix || '-' || lpad(taken::text, 4, '0');
END;
$$;

CREATE TABLE location (
  id          bigserial PRIMARY KEY,
  code        text NOT NULL UNIQUE CHECK (btrim(code) <> ''),
  name        text NOT NULL CHECK (btrim(name) <> ''),
  parent_id   bigint REFERENCES location(id) ON DELETE RESTRICT,
  CHECK (parent_id IS DISTINCT FROM id)
);

CREATE TABLE stock_item (
  id          bigserial PRIMARY KEY,
  code        text NOT NULL UNIQUE CHECK (btrim(code) <> ''),
  description text NOT NULL CHECK (btrim(description) <> ''),
  unit        text NOT NULL DEFAULT 'EA',
  -- Stock can never go below zero. Enforced here as well as in the issue function, because a
  -- CHECK holds against every path in and the function only holds against the one that calls it.
  --
  -- This one is deliberately redundant: reserved >= 0 together with reserved <= stock below
  -- already makes a negative stock impossible, so a refusal will normally name that pair instead.
  -- It stays as the floor, because "reserved may exceed stock" is a rule somebody could plausibly
  -- relax one day for backorders, and the day that happens this is what still holds.
  stock       numeric(12,3) NOT NULL DEFAULT 0 CONSTRAINT stock_never_negative CHECK (stock >= 0),
  reserved    numeric(12,3) NOT NULL DEFAULT 0 CONSTRAINT reserved_never_negative CHECK (reserved >= 0),
  min_stock   numeric(12,3) NOT NULL DEFAULT 0 CHECK (min_stock >= 0),
  avg_cost    numeric(12,2) CHECK (avg_cost IS NULL OR avg_cost >= 0),
  group_id    bigint REFERENCES item_group(id) ON DELETE RESTRICT,
  -- Restricted, not set to null. A rack cannot be removed from the system while steel is sitting
  -- on it: the alternative is physical material whose location the record has quietly forgotten,
  -- which is worse than being told to move it first.
  location_id bigint REFERENCES location(id) ON DELETE RESTRICT,
  heat_no     text,
  -- Weight is computed from the material reference and the dimensions, never typed in. Stored
  -- because it is read far more often than it changes; the API is the only thing that writes it.
  unit_weight numeric(12,3) CHECK (unit_weight IS NULL OR unit_weight >= 0),
  -- How the store actually counts this item. A plate is bought by the sheet and issued by the
  -- kilo, so the base unit and the size of one unit are both needed or every issue is a guess.
  base_unit   text,
  size_per_unit numeric(12,3) CHECK (size_per_unit IS NULL OR size_per_unit > 0),
  weight_per_base numeric(12,3) CHECK (weight_per_base IS NULL OR weight_per_base >= 0),
  -- What it is made of and what shape it is in. Grade and dimensions are what a welder matches a
  -- drawing against, and the certificate is what an auditor asks for.
  category    text,
  grade       text,
  dimensions  text,
  material_cert_ref text,
  -- The bin the steel is actually in — 'A1-01-02'. A different thing from location_id (the warehouse)
  -- and sublocation_id (the rack): those say which building and which shelf unit, this says which
  -- pigeonhole, and the store screen has always shown all three. It had no column, so the one the
  -- storeman reads off the label was the one that could not be stored.
  bin_code    text,
  status      text NOT NULL DEFAULT 'active' CHECK (status IN ('active','obsolete','blocked')),
  -- Buying. reorder_quantity is how much to order when it drops below min_stock, which is not the
  -- same number and was being conflated.
  reorder_quantity numeric(12,3) CHECK (reorder_quantity IS NULL OR reorder_quantity > 0),
  last_price  numeric(12,2) CHECK (last_price IS NULL OR last_price >= 0),
  -- The group and the shelf as the store writes them. group_id and location_id above are the real
  -- links; these are the sub-level within each, which the tree in item_group and location already
  -- models — so they are the id of the child, not a second copy of its name.
  subgroup_id bigint REFERENCES item_group(id) ON DELETE RESTRICT,
  sublocation_id bigint REFERENCES location(id) ON DELETE RESTRICT,
  created_at  timestamptz NOT NULL DEFAULT now(),
  -- More reserved than exists is not a state a store can be in.
  CONSTRAINT reserved_within_stock CHECK (reserved <= stock)
);

CREATE TYPE movement_kind AS ENUM ('receipt','issue','return','scrap','adjustment');

CREATE TABLE stock_movement (
  id            bigserial PRIMARY KEY,
  ref           text NOT NULL UNIQUE DEFAULT next_dated_ref('MV', 'seq_movement'::regclass, 5),
  stock_item_id bigint NOT NULL REFERENCES stock_item(id) ON DELETE RESTRICT,
  kind          movement_kind NOT NULL,
  quantity      numeric(12,3) NOT NULL CHECK (quantity > 0),
  jobcard_id    bigint REFERENCES jobcard(id) ON DELETE SET NULL,
  moved_by      text NOT NULL CHECK (btrim(moved_by) <> ''),
  moved_at      timestamptz NOT NULL DEFAULT now(),
  -- Where it came from and where it went. Free text rather than a location id on purpose: half the
  -- movements in a workshop are to or from somewhere that is not a shelf — a supplier's lorry, a
  -- subcontractor, a skip — and a foreign key to `location` cannot say any of those.
  moved_from    text,
  moved_to      text,
  unit          text,
  note          text
);

CREATE INDEX movement_item_idx ON stock_movement(stock_item_id);

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Quality
--
-- A hold is the only thing in this system that physically stops work leaving the building.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE TYPE hold_scope AS ENUM ('project','jobcard');
CREATE TYPE hold_status AS ENUM ('active','released');
CREATE TYPE severity AS ENUM ('minor','major','critical');

CREATE TABLE quality_hold (
  id            bigserial PRIMARY KEY,
  ref           text NOT NULL UNIQUE DEFAULT next_dated_ref('HOLD', 'seq_hold'::regclass, 3),
  scope         hold_scope NOT NULL,
  project_id    bigint REFERENCES project(id) ON DELETE CASCADE,
  jobcard_id    bigint REFERENCES jobcard(id) ON DELETE CASCADE,
  reason        text NOT NULL CHECK (btrim(reason) <> ''),
  severity      severity NOT NULL DEFAULT 'major',
  applied_by    text NOT NULL CHECK (btrim(applied_by) <> ''),
  applied_at    timestamptz NOT NULL DEFAULT now(),
  -- What has to happen before this hold can come off, written when it goes on. A hold whose reason is
  -- recorded but whose remedy is not is a hold nobody can clear without asking the person who applied
  -- it, and that person is on holiday.
  required_action text,
  -- The inspection or NCR this hold came out of. A reference rather than a foreign key because it is
  -- one column naming a row in either of two tables, and the screen looks a hold up by it: the NCR
  -- detail panel finds its own hold this way. Held as the ref people read, not an id.
  related_ref   text,
  status        hold_status NOT NULL DEFAULT 'active',
  -- Releasing a hold demands a named authority and written evidence. Not a convention somebody
  -- can forget: the columns are required the moment the status says released.
  release_authority text,
  release_reason    text,
  released_at       timestamptz,
  -- A hold names exactly one thing, and it names the thing its scope says it does.
  CONSTRAINT hold_names_one_thing CHECK (
    (scope = 'project' AND project_id IS NOT NULL AND jobcard_id IS NULL) OR
    (scope = 'jobcard' AND jobcard_id IS NOT NULL AND project_id IS NULL)
  ),
  CONSTRAINT release_needs_evidence CHECK (
    status = 'active' OR (
      btrim(coalesce(release_authority,'')) <> '' AND
      btrim(coalesce(release_reason,'')) <> '' AND
      released_at IS NOT NULL
    )
  )
);

CREATE INDEX hold_active_jobcard_idx ON quality_hold(jobcard_id) WHERE status = 'active';
CREATE INDEX hold_active_project_idx ON quality_hold(project_id) WHERE status = 'active';

-- 'not-applicable' is the fifth answer and it is a real one: an inspection is raised, and then the
-- thing it was raised against is cancelled, re-scoped or absorbed into another check. Without it the
-- inspector's only options are to leave it pending forever or to pass something nobody looked at.
CREATE TYPE inspection_result AS ENUM
  ('pending','passed','passed-observations','failed','not-applicable');

CREATE TABLE inspection (
  id            bigserial PRIMARY KEY,
  ref           text NOT NULL UNIQUE DEFAULT next_dated_ref('INS', 'seq_inspection'::regclass, 3),
  jobcard_id    bigint REFERENCES jobcard(id) ON DELETE CASCADE,
  project_id    bigint REFERENCES project(id) ON DELETE CASCADE,
  kind          text NOT NULL CHECK (btrim(kind) <> ''),
  component     text,
  inspector     text,
  result        inspection_result NOT NULL DEFAULT 'pending',
  findings      text,
  planned_date  date,
  actual_date   date,
  -- What was inspected, and against which drawing at which revision. An inspection that does not name
  -- the drawing it was measured against is not evidence of anything, and one that names the drawing
  -- but not the revision is evidence against the wrong drawing.
  --
  -- `operation` is free text, and it replaced a foreign key to `operation` that nothing ever wrote.
  -- The reason is the one stock_movement.moved_from already gives: half the inspections in a workshop
  -- are of something that is not a routing step — a weld seam, a batch of incoming plate, a painted
  -- surface, a pressure test — and a foreign key to the routing cannot say any of those. The screen's
  -- field is a text box, so the column is text.
  operation     text,
  drawing_no    text,
  drawing_rev   text,
  method        text,
  -- What the inspection is measured against. Recorded when it is requested, because an acceptance
  -- criterion agreed after the measurement is not a criterion.
  acceptance_criteria text,
  -- Two facts about the check itself rather than its result. A witnessed inspection cannot be done
  -- without telling the customer; material traceability confirmed says the heat numbers were checked
  -- against the certificates before anybody measured anything.
  customer_witness boolean NOT NULL DEFAULT false,
  material_traceability_ok boolean NOT NULL DEFAULT false,
  -- A critical failure is the one that puts a hold on. Kept on the inspection rather than inferred
  -- from the hold, because the hold can be released and the inspection stays the record of how bad it
  -- was.
  critical      boolean NOT NULL DEFAULT false,
  -- The screen's six, in the screen's spelling. The four this CHECK used to allow — requested,
  -- scheduled, done, cancelled — were not what any screen writes: a request opens at 'requested', an
  -- inspector moves it to 'in-progress', a reinspection is created 'planned', and a finished one is
  -- 'completed'. Three of the six would have been refused on arrival.
  status        text NOT NULL DEFAULT 'requested'
                CHECK (status IN ('draft','planned','requested','in-progress','completed','cancelled')),
  -- A re-inspection after a failure points back at the one it is repeating, so the history of a
  -- weld that was rejected and re-run reads as one story.
  reinspection_of bigint REFERENCES inspection(id) ON DELETE SET NULL,
  notes         text,
  CHECK (reinspection_of IS DISTINCT FROM id),
  -- A decided inspection has a date it happened on; one still pending, or one written off as not
  -- applicable, does not pretend to. Adding 'not-applicable' to the result enum without adding it here
  -- would have demanded a date for an inspection that never took place.
  CONSTRAINT decided_inspection_has_a_date
    CHECK (result IN ('pending','not-applicable') OR actual_date IS NOT NULL),
  -- Passed with observations means there is something to say. An empty findings box with that result
  -- is the observation nobody wrote down, which is the whole value of the category.
  CONSTRAINT observations_say_what_was_observed CHECK (
    result <> 'passed-observations' OR btrim(coalesce(findings,'')) <> ''
  ),
  created_at    timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT inspection_names_something CHECK (jobcard_id IS NOT NULL OR project_id IS NOT NULL)
);

-- What was actually checked, line by line, and what each line measured.
--
-- This is the evidence. The inspection row says an inspection passed; these rows say what was looked
-- at and what the tape read, and without them a passed final inspection on a pressure vessel is one
-- word in a database. The screen renders exactly this: a text line with pass/fail/na, or a measured
-- line with a nominal, a tolerance band and an actual, where it works the verdict out itself.
--
-- A NULL result is a line nobody has answered yet, not a line that passed. The screen sends an empty
-- string for that and it arrives here as NULL, because '' and 'unanswered' are the same fact and two
-- spellings of it is how a blank line gets counted as a pass.
CREATE TABLE inspection_check (
  id            bigserial PRIMARY KEY,
  inspection_id bigint NOT NULL REFERENCES inspection(id) ON DELETE CASCADE,
  line_no       int NOT NULL CHECK (line_no > 0),
  item          text NOT NULL CHECK (btrim(item) <> ''),
  result        text CHECK (result IS NULL OR result IN ('pass','fail','na')),
  nominal       numeric(12,3),
  tol_lower     numeric(12,3),
  tol_upper     numeric(12,3),
  actual        numeric(12,3),
  note          text,
  -- A nominal with no tolerance band is not a measurement anybody can judge. The screen prints "N/A"
  -- in the verdict column for such a line, which looks like a considered answer and is not one.
  CONSTRAINT a_nominal_needs_a_tolerance CHECK (
    nominal IS NULL OR (tol_lower IS NOT NULL AND tol_upper IS NOT NULL)
  ),
  -- Upper below lower is a band nothing can fall inside, so every measurement against it fails and
  -- the failure is the typist's.
  CONSTRAINT tolerance_band_is_the_right_way_up CHECK (
    tol_lower IS NULL OR tol_upper IS NULL OR tol_upper >= tol_lower
  ),
  UNIQUE (inspection_id, line_no)
);

CREATE INDEX inspection_check_idx ON inspection_check(inspection_id, line_no);

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Suppliers, and what they sell
--
-- supplier_item closes a real gap: today an item holds one price, so buying the same plate from
-- two merchants loses one of them. Item ↔ supplier ↔ their article number ↔ price ↔ pack size ↔
-- lead time, one row each, and the pair is unique so the same item cannot be listed twice against
-- one supplier. This is also where a supplier catalogue import lands later.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE supplier (
  id          bigserial PRIMARY KEY,
  ref         text NOT NULL UNIQUE DEFAULT next_ref('S-', 'seq_supplier'::regclass, 3),
  name        text NOT NULL CHECK (btrim(name) <> ''),
  org_no      text,
  vat_no      text,
  email       text,
  phone       text,
  website     text,
  -- The whole address, not only the town. A supplier's address is where a lorry goes and where a
  -- complaint is posted; the town alone is neither.
  address     text,
  city        text,
  country     text,
  -- What they sell, which is what the register is read and filtered by. Free text rather than an enum:
  -- a workshop's suppliers are steel merchants, gas suppliers, platers, hauliers, calibration houses
  -- and the man who sharpens the blades, and a fixed list gets a sixth one wrong.
  category    text,
  -- A company, a sole trader, a subcontractor. Affects who is invoiced and how, and it is on the screen.
  supplier_type text,
  established text,
  payment_terms_days int CHECK (payment_terms_days IS NULL OR payment_terms_days >= 0),
  -- Incoterms, and the smallest order they will take. Both are commitments with the merchant and both
  -- sat on the screen with nowhere to go, so they were being made up at the moment somebody typed a
  -- name: every supplier the form created got 30 days and DAP written onto them.
  delivery_terms text,
  minimum_order text,
  currency    char(3) NOT NULL DEFAULT 'SEK' CHECK (currency = upper(currency)),
  -- What this workshop thinks of them, out of five, when somebody has actually decided. NULL is "nobody
  -- has rated them", and it has to stay distinguishable from a rating of zero — the screen showed four
  -- stars beside every supplier's name because absence was being filled in with 4.
  rating      numeric(2,1) CHECK (rating IS NULL OR (rating >= 0 AND rating <= 5)),
  -- 'preferred' is the third state the screen offers and the column refused: the merchant this workshop
  -- buys from first. Fifth time a screen's vocabulary and a column's disagreed.
  status      text NOT NULL DEFAULT 'active'
              CHECK (status IN ('active','preferred','inactive')),
  notes       text,
  created_at  timestamptz NOT NULL DEFAULT now()
);

-- Who to ring at the supplier. The same shape as customer_contact, and for the same reasons: one main
-- contact rather than two, and a contact nobody can reach is not a contact.
--
-- A separate table rather than a column on supplier, because a merchant has an order desk, somebody in
-- accounts and a technical contact, and the one you need depends on why you are ringing.
CREATE TABLE supplier_contact (
  id          bigserial PRIMARY KEY,
  supplier_id bigint NOT NULL REFERENCES supplier(id) ON DELETE CASCADE,
  name        text NOT NULL CHECK (btrim(name) <> ''),
  role        text,
  email       text,
  phone       text,
  is_primary  boolean NOT NULL DEFAULT false,
  created_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT supplier_contact_can_be_reached
    CHECK (coalesce(btrim(email), '') <> '' OR coalesce(btrim(phone), '') <> '')
);

CREATE UNIQUE INDEX supplier_has_one_main_contact
  ON supplier_contact (supplier_id) WHERE is_primary;

CREATE TABLE supplier_item (
  id            bigserial PRIMARY KEY,
  supplier_id   bigint NOT NULL REFERENCES supplier(id) ON DELETE CASCADE,
  stock_item_id bigint NOT NULL REFERENCES stock_item(id) ON DELETE CASCADE,
  article_no    text,
  price         numeric(12,2) NOT NULL CHECK (price >= 0),
  currency      char(3) NOT NULL DEFAULT 'SEK' CHECK (currency = upper(currency)),
  pack_size     numeric(12,3) NOT NULL DEFAULT 1 CHECK (pack_size > 0),
  lead_time_days int CHECK (lead_time_days IS NULL OR lead_time_days >= 0),
  is_preferred  boolean NOT NULL DEFAULT false,
  updated_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (supplier_id, stock_item_id)
);

-- One preferred supplier per item, not two. Without this the question "who do we buy this from"
-- has more than one answer and whichever the screen happens to show wins.
CREATE UNIQUE INDEX supplier_item_one_preferred
  ON supplier_item(stock_item_id) WHERE is_preferred;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Buying
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE TYPE purchase_order_status AS ENUM
  ('draft','sent','confirmed','part-received','received','cancelled');

CREATE TABLE purchase_order (
  id            bigserial PRIMARY KEY,
  ref           text NOT NULL UNIQUE DEFAULT next_dated_ref('PO', 'seq_purchase_order'::regclass, 4),
  supplier_id   bigint NOT NULL REFERENCES supplier(id) ON DELETE RESTRICT,
  project_id    bigint REFERENCES project(id) ON DELETE SET NULL,
  status        purchase_order_status NOT NULL DEFAULT 'draft',
  ordered_by    text NOT NULL CHECK (btrim(ordered_by) <> ''),
  ordered_on    date NOT NULL DEFAULT current_date,
  expected_on   date,
  currency      char(3) NOT NULL DEFAULT 'SEK' CHECK (currency = upper(currency)),
  note          text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  CHECK (expected_on IS NULL OR expected_on >= ordered_on)
);

CREATE TABLE purchase_order_line (
  id                bigserial PRIMARY KEY,
  purchase_order_id bigint NOT NULL REFERENCES purchase_order(id) ON DELETE CASCADE,
  stock_item_id     bigint REFERENCES stock_item(id) ON DELETE RESTRICT,
  description       text NOT NULL CHECK (btrim(description) <> ''),
  quantity          numeric(12,3) NOT NULL CHECK (quantity > 0),
  unit_price        numeric(12,2) NOT NULL CHECK (unit_price >= 0),
  received_quantity numeric(12,3) NOT NULL DEFAULT 0 CHECK (received_quantity >= 0),
  -- More received than was ordered is a real event, but it is a decision somebody has to make
  -- rather than something that quietly happens, so the API raises the ordered quantity first.
  CONSTRAINT not_more_received_than_ordered CHECK (received_quantity <= quantity),
  UNIQUE (purchase_order_id, id)
);

CREATE INDEX po_line_order_idx ON purchase_order_line(purchase_order_id);

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Offcuts and barcodes
--
-- An offcut is what is left of a length after a job. Tracking them is the difference between
-- buying a new plate and using the half of one already on the rack.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE offcut (
  id            bigserial PRIMARY KEY,
  ref           text NOT NULL UNIQUE DEFAULT next_ref('OFF-', 'seq_offcut'::regclass, 4),
  stock_item_id bigint NOT NULL REFERENCES stock_item(id) ON DELETE RESTRICT,
  location_id   bigint REFERENCES location(id) ON DELETE RESTRICT,
  length_mm     numeric(10,1) CHECK (length_mm IS NULL OR length_mm > 0),
  width_mm      numeric(10,1) CHECK (width_mm IS NULL OR width_mm > 0),
  thickness_mm  numeric(10,1) CHECK (thickness_mm IS NULL OR thickness_mm > 0),
  quantity      numeric(12,3) NOT NULL DEFAULT 1 CHECK (quantity > 0),
  unit          text,
  -- Its own code and description, because an offcut is looked for by what it is rather than by
  -- which item it was cut from: somebody wants a piece of 10mm S355 about a metre long.
  code          text,
  description   text,
  grade         text,
  status        text NOT NULL DEFAULT 'available'
                CHECK (status IN ('available','reserved','consumed','scrapped')),
  heat_no       text,
  from_jobcard_id bigint REFERENCES jobcard(id) ON DELETE SET NULL,
  consumed_at   timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now(),
  -- An offcut with no size is not an offcut, it is a note.
  CONSTRAINT offcut_has_a_size CHECK (length_mm IS NOT NULL OR width_mm IS NOT NULL),
  -- A piece marked consumed with no date, or dated but still listed as available, is a rack that
  -- says two things at once — and the one thing an offcut register has to get right is whether the
  -- piece is still there.
  CONSTRAINT consumed_offcut_says_when CHECK ((status = 'consumed') = (consumed_at IS NOT NULL))
);

CREATE INDEX offcut_available_idx ON offcut(stock_item_id) WHERE consumed_at IS NULL;

CREATE TABLE barcode (
  id            bigserial PRIMARY KEY,
  -- A barcode scans to exactly one thing. This is the whole point of the table.
  code          text NOT NULL UNIQUE CHECK (btrim(code) <> ''),
  stock_item_id bigint REFERENCES stock_item(id) ON DELETE CASCADE,
  offcut_id     bigint REFERENCES offcut(id) ON DELETE CASCADE,
  created_at    timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT barcode_names_one_thing CHECK (
    (stock_item_id IS NOT NULL AND offcut_id IS NULL) OR
    (stock_item_id IS NULL AND offcut_id IS NOT NULL)
  )
);

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Before it is a project
--
-- A lead becomes an opportunity becomes a tender becomes a project. Each step keeps a link back,
-- so "where did this job come from" is answerable two years later.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

-- The screen's five. `lost` was the schema's word and `disqualified` is the screen's, and they are not
-- quite the same thing either: a lead is disqualified because it was never going to be work — wrong
-- trade, wrong country, no budget — whereas an opportunity is lost, to somebody. Both are here, with
-- `disqualified` added because the filter offers it and the column refused it. Sixth time a screen's
-- vocabulary and a column's were found disagreeing.
CREATE TYPE lead_status AS ENUM
  ('new','contacted','qualified','disqualified','converted','lost');

CREATE TABLE lead (
  id          bigserial PRIMARY KEY,
  ref         text NOT NULL UNIQUE DEFAULT next_ref('L-', 'seq_lead'::regclass, 4),
  company     text NOT NULL CHECK (btrim(company) <> ''),
  contact     text,
  email       text,
  phone       text,
  city        text,
  source      text,
  country     text,
  industry    text,
  company_size text,
  service_wanted text,
  estimated_value numeric(12,2) CHECK (estimated_value IS NULL OR estimated_value >= 0),
  priority    text CHECK (priority IS NULL OR priority IN ('low','normal','high')),
  owner       text,
  notes       text,
  -- When somebody last spoke to them and when they are due to be spoken to again. A lead with no
  -- next step is a lead nobody is working, which is the thing a pipeline exists to make visible.
  last_contact_on date,
  next_follow_up_on date,
  -- How they may be contacted, and whether they have asked not to be. Do-not-contact is a legal
  -- obligation in Sweden as everywhere else, so it is a column the system cannot forget rather than
  -- a note somebody might not read.
  -- Capitalised, because that is what the dropdown offers and what the customer register already stores
  -- ('Email' in `customer.preferred_contact`). Lower case here meant every lead the form saved was
  -- refused outright: `lead_contact_preference_check`, on a field nobody typed. Eighth time a screen's
  -- vocabulary and a column's were found disagreeing, and the eighth time the screen won.
  contact_preference text CHECK (contact_preference IS NULL OR
                       contact_preference IN ('Email','Phone','Post','None')),
  do_not_contact boolean NOT NULL DEFAULT false,
  status      lead_status NOT NULL DEFAULT 'new',
  -- Set when the lead becomes a customer. A converted lead that names nobody is a dead end in the
  -- record, so the two are tied together.
  customer_id bigint REFERENCES customer(id) ON DELETE SET NULL,
  created_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT converted_lead_names_the_customer CHECK (status <> 'converted' OR customer_id IS NOT NULL),
  -- Somebody who has asked not to be contacted cannot have a follow-up booked. Written here rather
  -- than left to whoever builds the screen, because the screen is not the only thing that will ever
  -- write to this table and the obligation does not depend on which one did.
  CONSTRAINT do_not_contact_means_no_follow_up
    CHECK (NOT do_not_contact OR next_follow_up_on IS NULL)
);

CREATE TABLE prospect_finding (
  id          bigserial PRIMARY KEY,
  lead_id     bigint NOT NULL REFERENCES lead(id) ON DELETE CASCADE,
  finding     text NOT NULL CHECK (btrim(finding) <> ''),
  source      text,
  found_by    text NOT NULL DEFAULT 'system',
  found_at    timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX prospect_finding_lead_idx ON prospect_finding(lead_id);

-- The screen's eight, which is the pipeline board's own set of columns: a card is dragged between them.
-- The six here before were a different shape of the same idea — 'enquiry' where the board says
-- 'discovery', 'estimating' where it says 'preparing', 'quoted' where it says 'quotesent' — and two of
-- the board's columns, 'rfq' and 'qualified', had no value at all. So dragging a card into either of them
-- would have been refused, which on a board is the one action there is.
CREATE TYPE opportunity_stage AS ENUM
  ('discovery','qualified','rfq','preparing','quotesent','negotiation','won','lost');

CREATE TABLE opportunity (
  id          bigserial PRIMARY KEY,
  ref         text NOT NULL UNIQUE DEFAULT next_dated_ref('OPP', 'seq_opportunity'::regclass, 3),
  title       text NOT NULL CHECK (btrim(title) <> ''),
  customer_id bigint REFERENCES customer(id) ON DELETE RESTRICT,
  lead_id     bigint REFERENCES lead(id) ON DELETE SET NULL,
  stage       opportunity_stage NOT NULL DEFAULT 'discovery',
  value       numeric(12,2) CHECK (value IS NULL OR value >= 0),
  currency    char(3) NOT NULL DEFAULT 'SEK' CHECK (currency = upper(currency)),
  probability int CHECK (probability IS NULL OR probability BETWEEN 0 AND 100),
  expected_close date,
  contact     text,
  industry    text,
  services    text,
  scope       text,
  owner       text,
  expected_decision_on date,
  required_delivery_on date,
  competitor  text,
  -- Why it was won or lost. The most useful field in the whole pipeline and the one most often left
  -- empty, so the constraint below asks for it once the answer is known.
  decision_reason text,
  next_action text,
  follow_up_on date,
  created_at  timestamptz NOT NULL DEFAULT now(),
  -- An opportunity belongs to somebody, whether they are a customer yet or not.
  CONSTRAINT opportunity_names_somebody CHECK (customer_id IS NOT NULL OR lead_id IS NOT NULL),
  -- A lost enquiry with no reason recorded teaches the workshop nothing, and the reason cannot be
  -- reconstructed six months later. Asked for at the moment it is known.
  CONSTRAINT lost_opportunity_says_why
    CHECK (stage <> 'lost' OR btrim(coalesce(decision_reason,'')) <> '')
  -- A do-not-contact lead cannot have a follow-up booked against its opportunity either, and that is NOT
  -- written here: a CHECK constraint that reads another table is only evaluated when this row changes, so
  -- it would hold until the moment somebody set do_not_contact on the lead and then quietly stop being
  -- true. The obligation lives on `lead`, where the flag is, and save_opportunity asks the question at the
  -- point somebody books the follow-up. A half-checked legal obligation is worse than an unchecked one,
  -- because it reads as enforced.
);

-- The screen's five. 'awarded' and 'declined' are what a tender actually comes back as — the customer
-- awards it or declines it, which is not the same voice as winning or losing — and 'in-progress' and
-- 'reviewing' are the two states a tender sits in while it is being put together. Seventh vocabulary
-- mismatch, and the same resolution as the other six.
CREATE TYPE tender_status AS ENUM
  ('in-progress','reviewing','submitted','awarded','declined');

CREATE TABLE tender (
  id             bigserial PRIMARY KEY,
  ref            text NOT NULL UNIQUE DEFAULT next_dated_ref('T', 'seq_tender'::regclass, 3),
  title          text NOT NULL CHECK (btrim(title) <> ''),
  opportunity_id bigint REFERENCES opportunity(id) ON DELETE SET NULL,
  customer_id    bigint REFERENCES customer(id) ON DELETE RESTRICT,
  -- Who is asking, and under what number. A tender arrives from a company this workshop may have no
  -- customer record for — that is the point of tendering — so the name is a column rather than only a
  -- foreign key, and `customer_ref` is THEIR reference for it, which is what every email about it will
  -- quote. Neither is our own `ref`, which the database allocates.
  company        text,
  customer_ref   text,
  source         text,
  industry       text,
  description    text,
  requirements   text,
  responsible    text,
  -- Whether this workshop is going to bid at all. The decision that comes before any of the work, and
  -- the screen has had a control for it since it was written.
  bid_decision   text NOT NULL DEFAULT 'pending'
                 CHECK (bid_decision IN ('bid', 'pending', 'no-bid')),
  -- When to be reminded, which is not the same date as when it is due: a tender due on the 30th needs
  -- somebody looking at it on the 20th.
  reminder_on    date,
  status         tender_status NOT NULL DEFAULT 'in-progress',
  submitted_on   date,
  due_on         date,
  value          numeric(12,2) CHECK (value IS NULL OR value >= 0),
  -- Set when the tender is won and the work starts. This is the link that answers "where did this
  -- project come from".
  project_id     bigint REFERENCES project(id) ON DELETE SET NULL,
  created_at     timestamptz NOT NULL DEFAULT now(),
  -- A tender that has gone in has a date it went in on. It is the date every chase and every deadline is
  -- counted from, and it cannot be reconstructed afterwards. Awarded and declined both imply it went in,
  -- so they are held to it too — the first version asked only of 'submitted', which meant a tender could
  -- be recorded as awarded having apparently never been sent.
  CONSTRAINT submitted_tender_has_a_date
    CHECK (status NOT IN ('submitted', 'awarded', 'declined') OR submitted_on IS NOT NULL),
  -- A tender has to be from somebody: a customer, an enquiry, or a company named outright. One that
  -- names nobody is a row nobody can act on and nobody can find again.
  CONSTRAINT tender_is_from_somebody CHECK (
    customer_id IS NOT NULL OR opportunity_id IS NOT NULL OR btrim(coalesce(company,'')) <> ''
  ),
  -- Deciding not to bid is a decision; submitting one anyway is a contradiction the register should not
  -- be able to hold.
  CONSTRAINT no_bid_means_no_tender CHECK (
    bid_decision <> 'no-bid' OR status NOT IN ('submitted', 'awarded')
  )
);

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Estimating
--
-- An estimate is lines. The total is the sum of the lines and is computed, never typed — the same
-- rule as logged hours, for the same reason: a figure somebody can type is a figure that can
-- disagree with what it is made of, and this is the figure the job is priced from.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE TYPE estimate_status AS ENUM ('draft','sent','accepted','rejected','expired');

CREATE TABLE estimate (
  id          bigserial PRIMARY KEY,
  ref         text NOT NULL UNIQUE DEFAULT next_dated_ref('EST', 'seq_estimate'::regclass, 4),
  title       text NOT NULL CHECK (btrim(title) <> ''),
  customer_id bigint NOT NULL REFERENCES customer(id) ON DELETE RESTRICT,
  opportunity_id bigint REFERENCES opportunity(id) ON DELETE SET NULL,
  project_id  bigint REFERENCES project(id) ON DELETE SET NULL,
  status      estimate_status NOT NULL DEFAULT 'draft',
  currency    char(3) NOT NULL DEFAULT 'SEK' CHECK (currency = upper(currency)),
  margin_pct  numeric(5,2) NOT NULL DEFAULT 0 CHECK (margin_pct > -100 AND margin_pct <= 1000),
  -- Maintained by trigger from the lines below.
  total       numeric(12,2) NOT NULL DEFAULT 0 CHECK (total >= 0),
  valid_until date,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TYPE estimate_line_kind AS ENUM ('material','labour','subcontract','other');

CREATE TABLE estimate_line (
  id            bigserial PRIMARY KEY,
  estimate_id   bigint NOT NULL REFERENCES estimate(id) ON DELETE CASCADE,
  kind          estimate_line_kind NOT NULL,
  description   text NOT NULL CHECK (btrim(description) <> ''),
  stock_item_id bigint REFERENCES stock_item(id) ON DELETE SET NULL,
  quantity      numeric(12,3) NOT NULL CHECK (quantity > 0),
  unit          text NOT NULL DEFAULT 'EA',
  unit_price    numeric(12,2) NOT NULL CHECK (unit_price >= 0),
  -- A generated column rather than a trigger: the line total is arithmetic on its own row, and a
  -- stored generated column cannot be written to at all, by anybody.
  line_total    numeric(14,2) GENERATED ALWAYS AS (quantity * unit_price) STORED,
  -- A line is locked when the estimate has gone to the customer. After that the price can still be
  -- changed — a mistake is a mistake — but not silently: the reason and the name are columns, not
  -- a convention somebody remembers. The trigger below is what makes them required.
  locked        boolean NOT NULL DEFAULT false,
  reprice_reason text,
  repriced_by   text,
  repriced_at   timestamptz,
  sort_order    int NOT NULL DEFAULT 0
);

CREATE INDEX estimate_line_estimate_idx ON estimate_line(estimate_id);

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- What happened to a machine
--
-- One event table replaces twelve tabs. An inspection, a service, a calibration, a breakdown and a
-- pre-use check are the same shape: a thing that happened to a machine on a date, with a result.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE TYPE equipment_event_kind AS ENUM
  ('service','calibration','inspection','breakdown','pre-use-check','repair');

CREATE TABLE equipment_event (
  id            bigserial PRIMARY KEY,
  equipment_id  bigint NOT NULL REFERENCES equipment(id) ON DELETE CASCADE,
  kind          equipment_event_kind NOT NULL,
  happened_on   date NOT NULL DEFAULT current_date,
  performed_by  text NOT NULL CHECK (btrim(performed_by) <> ''),
  result        text NOT NULL CHECK (result IN ('pass','fail','done','observations')),
  next_due_on   date,
  cost          numeric(12,2) CHECK (cost IS NULL OR cost >= 0),
  note          text,
  -- Which job the check was signed for. A pre-use check is signed for a particular piece of work on a
  -- particular day, and equipment-gates.js matches on exactly that: a check passed this morning for
  -- another jobcard is not a check for this one. Without the link the gate can only ask "was anything
  -- checked today", which is the question that lets a machine onto the wrong job.
  jobcard_id    bigint REFERENCES jobcard(id) ON DELETE SET NULL,
  -- A failed check stops the machine until somebody deals with it, and "dealt with" has to be a record
  -- rather than a flag somebody flips: `resolves_event_id` is the later event that answers this one.
  -- Setting `resolved` on the failure itself is what that later event does, so both exist — one is the
  -- state the gate reads, the other is the evidence for it.
  resolved      boolean NOT NULL DEFAULT false,
  resolves_event_id bigint REFERENCES equipment_event(id) ON DELETE SET NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  CHECK (next_due_on IS NULL OR next_due_on >= happened_on),
  -- A failed check cannot resolve anything: the thing that clears a failure is a later check that
  -- passed, or a repair. Allowing it would let one broken machine clear another's failure.
  CHECK (resolves_event_id IS NULL OR result <> 'fail')
);

-- An event cannot resolve itself, which a self-reference makes expressible and therefore worth
-- refusing. It would make a failed check its own answer.
CREATE FUNCTION equipment_event_cannot_answer_itself() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.resolves_event_id IS NOT NULL AND NEW.resolves_event_id = NEW.id THEN
    RAISE EXCEPTION 'an equipment event cannot resolve itself' USING ERRCODE = 'check_violation';
  END IF;
  -- And it can only answer an event about the same machine. A pre-use check on the plasma cutter
  -- clearing a failure on the press is the kind of thing that is obvious when written down and
  -- invisible in a list of ids.
  IF NEW.resolves_event_id IS NOT NULL
     AND (SELECT equipment_id FROM equipment_event WHERE id = NEW.resolves_event_id)
         IS DISTINCT FROM NEW.equipment_id THEN
    RAISE EXCEPTION 'an equipment event can only resolve one about the same machine'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER equipment_event_answers_itself_trg BEFORE INSERT OR UPDATE ON equipment_event
  FOR EACH ROW EXECUTE FUNCTION equipment_event_cannot_answer_itself();

CREATE INDEX equipment_event_machine_idx ON equipment_event(equipment_id, happened_on DESC);

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Non-conformances
-- ─────────────────────────────────────────────────────────────────────────────────────────────

-- The screen's ten, in the screen's spelling. The six this enum used to hold were a different set of
-- words for the same machine — 'investigating' where the screen says 'under-investigation',
-- 'verification' where it says 'waiting-verification' — and four of the screen's states had no value
-- here at all, so a containment recorded on the floor and an NCR reopened after closure would both
-- have been refused. Third time in this project that the schema and a screen were found to be naming
-- one state two ways, and the third time the screen won: it is what somebody is looking at.
CREATE TYPE ncr_status AS ENUM
  ('draft','open','containment-required','under-investigation','disposition-required',
   'corrective-action','waiting-verification','closed','rejected','reopened');

CREATE TABLE ncr (
  id            bigserial PRIMARY KEY,
  ref           text NOT NULL UNIQUE DEFAULT next_dated_ref('NCR', 'seq_ncr'::regclass, 3),
  title         text NOT NULL CHECK (btrim(title) <> ''),
  project_id    bigint REFERENCES project(id) ON DELETE CASCADE,
  jobcard_id    bigint REFERENCES jobcard(id) ON DELETE CASCADE,
  category      text NOT NULL CHECK (btrim(category) <> ''),
  severity      severity NOT NULL DEFAULT 'major',
  description   text NOT NULL CHECK (btrim(description) <> ''),
  responsible   text NOT NULL CHECK (btrim(responsible) <> ''),
  status        ncr_status NOT NULL DEFAULT 'open',
  due_on        date,
  -- Who found it and when, which is not the same as who is responsible for fixing it and not the same
  -- as when the record was typed. An NCR raised on Friday and entered on Monday is dated Friday, or
  -- the interval between finding a fault and recording it can never be measured.
  detected_by   text NOT NULL CHECK (btrim(detected_by) <> ''),
  detected_on   date NOT NULL DEFAULT current_date,
  -- Free text, for the reason inspection.operation gives: what a non-conformance is against is often
  -- not a routing step. This replaced a foreign key to `operation` that nothing ever wrote.
  operation     text,
  component     text,
  material      text,
  supplier_id   bigint REFERENCES supplier(id) ON DELETE SET NULL,
  -- Containment is what was done about it immediately — the parts quarantined, the machine stopped —
  -- as distinct from the corrective action that stops it happening again. Conflating the two is how
  -- an NCR gets closed on the containment alone.
  containment   text,
  -- The screen's eight. 'replace', 'reclassify' and 'pending' were missing, and 'pending' is the one
  -- that matters: it is what the screen offers while the decision is still being argued about, so
  -- without it the only way to save the record was to decide.
  disposition   text CHECK (disposition IS NULL OR
                  disposition IN ('rework','repair','use-as-is','return-to-supplier','scrap',
                                  'replace','reclassify','pending')),
  -- Who approved the disposition, and what was verified afterwards by whom. Three separate facts that
  -- were all being written into `notes` because there was nowhere else: the approval that let a part
  -- be used as-is, the evidence that the fix worked, and the name against that evidence.
  disposition_approval_ref text,
  verification_result text,
  verified_by   text,
  -- The corrective action this NCR was answered by, as a CAPA reference. The root-cause analysis lives
  -- on the CAPA — five whys, fishbone — not here; this column is the pointer to it.
  corrective_action_ref text,
  closure_approval text,
  notes         text,
  root_cause    text,
  corrective_action text,
  closed_on     date,
  created_at    timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ncr_names_something CHECK (project_id IS NOT NULL OR jobcard_id IS NOT NULL),
  -- A non-conformance closed with nothing written down is a record of nothing; the point of the
  -- register is that the same fault does not come back. What "written down" means, though, had to
  -- change, and the change is worth explaining because the old version could not have been satisfied.
  --
  -- This constraint used to demand root_cause and corrective_action. No screen in the system can fill
  -- either: in this application the root-cause analysis belongs to the CAPA record — where the five
  -- whys and the fishbone actually live — and the NCR points at it. What the closure screen collects
  -- is the verification evidence, the name against it, and the closure approval reference. So the
  -- constraint demanded two columns nothing writes and ignored the three that are, which means every
  -- close from the Quality screen would have been refused with a message about a root cause the
  -- screen has no box for. A rule that cannot be obeyed is not enforcement, it is a locked door.
  --
  -- Both columns stay, for an NCR closed without a full CAPA, and root_cause is no longer the gate.
  CONSTRAINT closed_ncr_says_what_was_done CHECK (
    status <> 'closed' OR (
      btrim(coalesce(verification_result,'')) <> '' AND
      btrim(coalesce(closure_approval,'')) <> '' AND
      closed_on IS NOT NULL
    )
  ),
  -- Using a non-conforming part as it is, is a decision somebody signs for. It is the one disposition
  -- that leaves the fault in the delivered work, so the approval reference is a condition of recording
  -- it rather than a field somebody means to come back and fill in.
  CONSTRAINT use_as_is_is_signed_for CHECK (
    disposition IS DISTINCT FROM 'use-as-is' OR
    btrim(coalesce(disposition_approval_ref,'')) <> ''
  ),
  -- Major and critical get a date by which they are answered. A minor may sit on the list; a critical
  -- with no due date is how one sits there for eight months.
  CONSTRAINT serious_ncrs_have_a_date CHECK (severity = 'minor' OR due_on IS NOT NULL)
);

CREATE INDEX ncr_open_idx ON ncr(status) WHERE status NOT IN ('closed','rejected');

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Documents
--
-- The register of what the workshop holds on paper: certificates, drawings, reports, templates. A
-- certificate that has run out is the single most common document problem in a metal shop, which is why
-- the expiry date is a column and not a line in the notes.
--
-- Two halves of this are optional, and both were NOT NULL in the first version, which is what kept this
-- table unused for four passes:
--
--   * The FILE. There is no object storage yet, so `storage_key` had nothing to hold and a register entry
--     could not be made at all. But a workshop knows it holds a material certificate expiring on the 12th
--     long before anybody scans it, and that expiry is the part worth tracking. So the file half —
--     filename, storage_key, mime_type, size_bytes — is either all there or none of it, and a record with
--     none of it is a register entry waiting for its scan.
--   * The LINK. The screen has an explicit "Unlinked" state and a "Link to Record" action, so a document
--     that belongs to nothing yet is a state somebody chose, not a mistake. entity and entity_id are
--     either both set or both null; half a link points nowhere and reads as though it points somewhere.
--
-- The entity/entity_id pair cannot be a foreign key, so the entity name is restricted to the tables it may
-- actually refer to — a spelling mistake there is a document nothing can find. save_document() resolves
-- the screen's word for a module into one of these and looks the reference up, so a link to a record that
-- does not exist is refused rather than stored.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

-- The states somebody sets. 'Review Soon' and 'Expired' are NOT here and that is the point: both are
-- answers to "what is the date today", and a status column holding either is a fact that was true when it
-- was written and silently stops being true. The Documents screen offers "Review Soon" in its status
-- dropdown, which is the one place its vocabulary is not just a different spelling but a different kind of
-- thing. The view computes both from expires_on, so they cannot go stale.
CREATE TYPE document_status AS ENUM ('draft', 'valid', 'approved', 'superseded');

CREATE TABLE document (
  id          bigserial PRIMARY KEY,
  ref         text NOT NULL UNIQUE DEFAULT next_ref('DOC-', 'seq_document'::regclass, 5),
  -- What people call it. The screen has one name field and this is it; `filename` below is what the file
  -- was actually saved under, which is a different string and often an uglier one.
  title       text NOT NULL CHECK (btrim(title) <> ''),
  kind        text NOT NULL CHECK (kind IN
                ('Document', 'Certificate', 'Drawing', 'Report', 'Template', 'Image')),
  category    text,
  revision    text,
  status      document_status NOT NULL DEFAULT 'draft',
  expires_on  date,

  -- The record it belongs to, or nothing yet.
  entity      text CHECK (entity IS NULL OR entity IN
                ('customer','project','jobcard','operation','equipment','stock_item',
                 'quality_hold','inspection','ncr','supplier','purchase_order','estimate','tender')),
  entity_id   bigint,

  -- The file, when there is one.
  filename    text CHECK (filename IS NULL OR btrim(filename) <> ''),
  storage_key text UNIQUE CHECK (storage_key IS NULL OR btrim(storage_key) <> ''),
  mime_type   text,
  size_bytes  bigint CHECK (size_bytes IS NULL OR size_bytes > 0),

  author      text,
  notes       text,
  uploaded_by text NOT NULL CHECK (btrim(uploaded_by) <> ''),
  uploaded_at timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT a_link_names_both_halves CHECK ((entity IS NULL) = (entity_id IS NULL)),
  -- A stored file needs somewhere to be stored and a name to be found by. Either both or neither: a
  -- storage key with no filename is a file nobody can offer to download, and a filename with no key is a
  -- download button that leads nowhere.
  CONSTRAINT a_stored_file_has_a_key CHECK ((storage_key IS NULL) = (filename IS NULL)),
  -- Only a certificate, a drawing or a report has a life. A template does not expire.
  CONSTRAINT only_a_dated_document_expires CHECK (
    expires_on IS NULL OR kind IN ('Certificate', 'Drawing', 'Report', 'Document'))
);

CREATE INDEX document_entity_idx ON document(entity, entity_id);
-- The question the register is opened to answer: what is running out.
CREATE INDEX document_expiry_idx ON document(expires_on) WHERE expires_on IS NOT NULL;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- The welding registers
--
-- BACKEND.md argued for four passes that these were "paperwork for nobody": build them before there is an
-- auditor and you have built paperwork nobody reads. That argument was right and its premise has changed —
-- the firm is certified or on the way, so there is an auditor. What was kept against exactly this day is
-- what these are built on: the heat number and the material certificate reference on the jobcard, which
-- could not have been back-filled.
--
-- Everything here is a register except one sentence, and that sentence is why it is in a database:
--
--     A weld is made by a welder qualified for that process, to a procedure that was valid on the day.
--
-- That is what an auditor checks and what a delivery is signed off against. It is four triggers below, and
-- each refuses in words a welder can read with the date in the message — the same shape as the equipment
-- certification gate, which has refused to start a job on an out-of-certification machine since step 2.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE SEQUENCE seq_weld;
CREATE SEQUENCE seq_ndt;
CREATE SEQUENCE seq_wps;

-- The two statuses somebody sets on a procedure, and on a qualification. `expiring-soon` and `expired`
-- are in NEITHER list, and that is deliberate: both are answers to what the date is today, and a column
-- holding either is a fact that was true the morning somebody typed it. The demonstration records carry
-- `expiring-soon` as a stored status on a welder qualification, which is the register whose whole job is
-- to say who may weld — so it is computed in workspace_snapshot() on every read, beside the settable
-- value, exactly as `document` does since yesterday.
CREATE TYPE wps_status AS ENUM ('draft', 'awaiting-approval', 'approved', 'withdrawn');
CREATE TYPE welder_qual_status AS ENUM ('valid', 'suspended', 'withdrawn');
CREATE TYPE weld_status AS ENUM
  ('planned', 'welded', 'repair-required', 'repaired', 'accepted', 'rejected');
CREATE TYPE weld_result AS ENUM ('pending', 'accepted', 'rejected');
CREATE TYPE ndt_result AS ENUM ('pending', 'accepted', 'rejected');

-- ── The procedure a weld is made to ──────────────────────────────────────────────────────────
CREATE TABLE wps (
  id                bigserial PRIMARY KEY,
  -- Not unique on its own. A procedure is revised — WPS-304-02 rev 1 is superseded by rev 2 and both stay
  -- on file, because the welds made to rev 1 were made to rev 1 and a register that overwrote it cannot
  -- say what they were made to. `ref UNIQUE` here would have forbidden the second revision outright and
  -- left the revision column meaning nothing; the uniqueness that is wanted is one row per revision, and
  -- it is the index below.
  ref               text NOT NULL CHECK (btrim(ref) <> ''),
  revision          int NOT NULL DEFAULT 1 CHECK (revision >= 0),
  process           text NOT NULL CHECK (btrim(process) <> ''),
  material_group    text,
  thickness_range   text,
  diameter_range    text,
  joint_type        text,
  position          text,
  filler_material   text,
  shielding_gas     text,
  preheat_interpass text,
  -- The qualification record the procedure rests on. A WPS with no WPQR behind it is a procedure nobody
  -- has proved, which an auditor asks for first.
  supporting_wpqr   text,
  status            wps_status NOT NULL DEFAULT 'draft',
  -- The document itself lives in the register that holds documents, wired yesterday. A filename here
  -- would be a second place for the same file to go stale.
  document_id       bigint REFERENCES document(id) ON DELETE SET NULL,
  approved_on       date,
  approved_by       text,
  notes             text,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  -- An approved procedure says who approved it and when. Approval is the whole difference between a draft
  -- and something a weld may be made to, so it cannot be a status somebody sets and nothing else.
  CONSTRAINT an_approved_wps_says_who CHECK (
    status <> 'approved' OR (approved_on IS NOT NULL AND btrim(coalesce(approved_by, '')) <> ''))
);
-- One revision of one procedure. A second WPS-304-02 rev 1 is a second answer to the same question.
CREATE UNIQUE INDEX wps_one_revision ON wps(ref, revision);

-- ── Which welder is qualified to what ────────────────────────────────────────────────────────
CREATE TABLE welder_qual (
  id              bigserial PRIMARY KEY,
  -- The person, not their name. A qualification naming a string cannot be joined to whoever holds it, and
  -- the staff list has been in the snapshot since yesterday — so the demonstration data's `welder: 'Elena
  -- N.'` becomes a real reference. Two Elenas, or one Elena whose name is corrected in Access, and a text
  -- column is a qualification belonging to nobody.
  welder_id       bigint NOT NULL REFERENCES app_user(id) ON DELETE RESTRICT,
  qual_no         text NOT NULL CHECK (btrim(qual_no) <> ''),
  process         text NOT NULL CHECK (btrim(process) <> ''),
  material_group  text,
  thickness_range text,
  position        text,
  issued_by       text NOT NULL CHECK (btrim(issued_by) <> ''),
  issued_on       date NOT NULL,
  expires_on      date NOT NULL,
  status          welder_qual_status NOT NULL DEFAULT 'valid',
  document_id     bigint REFERENCES document(id) ON DELETE SET NULL,
  notes           text,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT a_qualification_runs_forwards CHECK (expires_on > issued_on),
  -- A welder holds one of each qualification number. They hold several qualifications — one per process —
  -- so the register is per qualification and not per welder.
  CONSTRAINT one_qualification_per_number UNIQUE (welder_id, qual_no)
);
CREATE INDEX welder_qual_expiry_idx ON welder_qual(expires_on);
CREATE INDEX welder_qual_welder_idx ON welder_qual(welder_id, process);

-- ── The weld log ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE weld (
  id                bigserial PRIMARY KEY,
  ref               text NOT NULL UNIQUE DEFAULT next_ref('WLD-', 'seq_weld'::regclass, 4),
  project_id        bigint REFERENCES project(id) ON DELETE SET NULL,
  jobcard_id        bigint NOT NULL REFERENCES jobcard(id) ON DELETE RESTRICT,
  operation_id      bigint REFERENCES operation(id) ON DELETE SET NULL,
  component         text,
  drawing_no        text,
  -- Where on the drawing. Without it a weld log says a weld was made and not which one.
  weld_map_position text,
  joint_type        text,
  base_material     text,
  material_grade    text,
  thickness         numeric(8,2) CHECK (thickness IS NULL OR thickness > 0),
  process           text NOT NULL CHECK (btrim(process) <> ''),
  wps_id            bigint REFERENCES wps(id) ON DELETE RESTRICT,
  wpqr_ref          text,
  welder_id         bigint NOT NULL REFERENCES app_user(id) ON DELETE RESTRICT,
  welder_qual_id    bigint REFERENCES welder_qual(id) ON DELETE RESTRICT,
  filler_material   text,
  -- The batch of consumable. This is the field that answers "what went into this weld" when a filler
  -- batch is later recalled, and it is the reason a weld log exists at all.
  consumable_batch  text,
  shielding_gas     text,
  preheat_required  boolean NOT NULL DEFAULT false,
  interpass_temp_req text,
  welded_on         date NOT NULL DEFAULT current_date,
  visual_required   boolean NOT NULL DEFAULT true,
  ndt_required      boolean NOT NULL DEFAULT false,
  ndt_method        text,
  final_result      weld_result NOT NULL DEFAULT 'pending',
  status            weld_status NOT NULL DEFAULT 'welded',
  notes             text,
  recorded_by       text NOT NULL CHECK (btrim(recorded_by) <> ''),
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT a_weld_is_not_made_tomorrow CHECK (welded_on <= current_date),
  -- If NDT is called for, the method has to be named. "Something should be tested" is not an instruction
  -- anybody can carry out.
  CONSTRAINT ndt_that_is_required_says_how CHECK (
    NOT ndt_required OR btrim(coalesce(ndt_method, '')) <> '')
);
CREATE INDEX weld_jobcard_idx ON weld(jobcard_id);
CREATE INDEX weld_welder_idx ON weld(welder_id, welded_on);

-- A repair is a row and not a rewrite. A weld that was repaired is not a weld that was always right, and
-- which is which is the question an auditor asks when a joint fails in service.
CREATE TABLE weld_repair (
  id          bigserial PRIMARY KEY,
  weld_id     bigint NOT NULL REFERENCES weld(id) ON DELETE CASCADE,
  repaired_on date NOT NULL DEFAULT current_date,
  reason      text NOT NULL CHECK (btrim(reason) <> ''),
  repaired_by text NOT NULL CHECK (btrim(repaired_by) <> ''),
  notes       text,
  recorded_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX weld_repair_weld_idx ON weld_repair(weld_id);

-- ── The NDT against a weld ───────────────────────────────────────────────────────────────────
CREATE TABLE ndt_report (
  id                    bigserial PRIMARY KEY,
  ref                   text NOT NULL UNIQUE DEFAULT next_ref('NDT-', 'seq_ndt'::regclass, 4),
  weld_id               bigint NOT NULL REFERENCES weld(id) ON DELETE RESTRICT,
  drawing_no            text,
  method                text NOT NULL CHECK (btrim(method) <> ''),
  procedure_ref         text,
  inspection_percent    numeric(5,2) CHECK (inspection_percent IS NULL
                          OR (inspection_percent > 0 AND inspection_percent <= 100)),
  inspection_area       text,
  -- Either somebody here or a firm outside, and one of the two has to be named: an NDT report nobody
  -- signed is not evidence of anything.
  technician            text,
  external_company      text,
  technician_cert_ref   text,
  inspected_on          date NOT NULL DEFAULT current_date,
  acceptance_criteria   text,
  result                ndt_result NOT NULL DEFAULT 'pending',
  findings              text,
  repair_required       boolean NOT NULL DEFAULT false,
  reinspection_required boolean NOT NULL DEFAULT false,
  ncr_id                bigint REFERENCES ncr(id) ON DELETE SET NULL,
  notes                 text,
  recorded_by           text NOT NULL CHECK (btrim(recorded_by) <> ''),
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ndt_is_signed_by_somebody CHECK (
    btrim(coalesce(technician, '')) <> '' OR btrim(coalesce(external_company, '')) <> ''),
  CONSTRAINT ndt_is_not_done_tomorrow CHECK (inspected_on <= current_date),
  -- A rejected report says what was found. "Rejected" with no findings is a decision nobody can check or
  -- argue with, and the weld it rejects cannot be repaired without knowing what to repair.
  CONSTRAINT a_rejected_report_says_what_was_found CHECK (
    result <> 'rejected' OR btrim(coalesce(findings, '')) <> '')
);
CREATE INDEX ndt_weld_idx ON ndt_report(weld_id);

-- ── The four rules that are the reason this is in a database ──────────────────────────────────
--
-- A screen can ask all four of these and a screen is not where they can live: a welder reaching the same
-- jobcard through another page, an import, or a console walks straight past a check written in a browser.
-- The same argument the equipment gate makes, and it was proved there — equipment-gates.js had refused an
-- out-of-certification machine for months while the database would accept one.

CREATE FUNCTION weld_is_properly_qualified() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  procedure record;
  held record;
  who text;
BEGIN
  SELECT display_name INTO who FROM app_user WHERE id = NEW.welder_id;

  -- 1. The procedure has to be one somebody approved. A draft WPS is a proposal.
  IF NEW.wps_id IS NOT NULL THEN
    SELECT ref, revision, status, process INTO procedure FROM wps WHERE id = NEW.wps_id;
    IF procedure.status <> 'approved' THEN
      RAISE EXCEPTION 'weld cannot be recorded to % rev %: that procedure is %, not approved',
        procedure.ref, procedure.revision, procedure.status USING ERRCODE = 'check_violation';
    END IF;
    IF lower(btrim(procedure.process)) <> lower(btrim(NEW.process)) THEN
      RAISE EXCEPTION 'weld cannot be recorded as % against %, which is a % procedure',
        NEW.process, procedure.ref, procedure.process USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  -- 2, 3. The qualification has to be the welder's own, cover the process, and not have run out on the
  -- day the weld was made. Three refusals rather than one, because "not qualified" tells somebody nothing
  -- about what to do next, and the third is the one an auditor is actually asking about.
  IF NEW.welder_qual_id IS NOT NULL THEN
    SELECT wq.id, wq.welder_id, wq.qual_no, wq.process, wq.expires_on, wq.status
      INTO held FROM welder_qual wq WHERE wq.id = NEW.welder_qual_id;

    IF held.welder_id <> NEW.welder_id THEN
      RAISE EXCEPTION 'qualification % does not belong to % — a qualification cannot be borrowed',
        held.qual_no, coalesce(who, 'that welder') USING ERRCODE = 'check_violation';
    END IF;
    IF lower(btrim(held.process)) <> lower(btrim(NEW.process)) THEN
      RAISE EXCEPTION '% is qualified to % under %, and this weld is %',
        coalesce(who, 'that welder'), held.process, held.qual_no, NEW.process
        USING ERRCODE = 'check_violation';
    END IF;
    IF held.status <> 'valid' THEN
      RAISE EXCEPTION 'the qualification % held by % is %, so it cannot be cited for a weld',
        held.qual_no, coalesce(who, 'that welder'), held.status USING ERRCODE = 'check_violation';
    END IF;
    -- The one that matters, with the date in it, like the equipment gate.
    IF held.expires_on < NEW.welded_on THEN
      RAISE EXCEPTION 'the qualification % held by % expired on %, and this weld was made on %',
        held.qual_no, coalesce(who, 'that welder'), held.expires_on, NEW.welded_on
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER weld_qualification_gate_trg BEFORE INSERT OR UPDATE ON weld
  FOR EACH ROW EXECUTE FUNCTION weld_is_properly_qualified();

-- 4. A weld that calls for NDT cannot be accepted until an NDT report accepts it.
--
-- This is the rule that stops a delivery being signed off against work nobody tested. It is separate from
-- the gate above because it is asked at a different moment: the gate asks when the weld is recorded, and
-- this asks when somebody tries to call it good.
CREATE FUNCTION weld_accepted_only_on_evidence() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.final_result = 'accepted' AND NEW.ndt_required THEN
    IF NOT EXISTS (SELECT 1 FROM ndt_report r
                    WHERE r.weld_id = NEW.id AND r.result = 'accepted') THEN
      RAISE EXCEPTION 'weld % requires % and no report has accepted it — a weld cannot be accepted on '
        'evidence that does not exist', NEW.ref, coalesce(NEW.ndt_method, 'NDT')
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  -- And a weld cannot be accepted while a report against it is calling for a repair. Two rows disagreeing
  -- about whether a joint is sound is worse than either answer on its own.
  IF NEW.final_result = 'accepted' AND EXISTS (
       SELECT 1 FROM ndt_report r WHERE r.weld_id = NEW.id
         AND (r.result = 'rejected' OR r.repair_required)) THEN
    RAISE EXCEPTION 'weld % cannot be accepted while a report against it calls for a repair', NEW.ref
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER weld_evidence_gate_trg BEFORE UPDATE OF final_result ON weld
  FOR EACH ROW EXECUTE FUNCTION weld_accepted_only_on_evidence();

-- And the other direction: a report that rejects a weld puts the weld into repair-required, rather than
-- leaving a rejected report beside an accepted weld for somebody to notice.
CREATE FUNCTION ndt_result_reaches_the_weld() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.result = 'rejected' OR NEW.repair_required THEN
    UPDATE weld SET status = 'repair-required', final_result = 'rejected', updated_at = now()
     WHERE id = NEW.weld_id AND status <> 'repair-required';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER ndt_reaches_the_weld_trg AFTER INSERT OR UPDATE OF result ON ndt_report
  FOR EACH ROW EXECUTE FUNCTION ndt_result_reaches_the_weld();


-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- The audit trail
--
-- Append-only by trigger. A history somebody can quietly edit is not a history.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE activity_log (
  id          bigserial PRIMARY KEY,
  entity      text NOT NULL,
  entity_id   bigint NOT NULL,
  action      text NOT NULL CHECK (btrim(action) <> ''),
  actor       text NOT NULL DEFAULT 'system',
  detail      text,
  happened_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX activity_entity_idx ON activity_log(entity, entity_id);

CREATE FUNCTION activity_is_append_only() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'the activity log is append-only: a history that can be edited is not a history';
END;
$$;

CREATE TRIGGER activity_no_update BEFORE UPDATE OR DELETE ON activity_log
  FOR EACH ROW EXECUTE FUNCTION activity_is_append_only();

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- The safety rules, as triggers
-- ─────────────────────────────────────────────────────────────────────────────────────────────

-- 1. An active quality hold blocks completing a jobcard or its project.
--
-- The statuses listed are the ones that mean "this work is finished and may leave" — which is
-- exactly what a hold exists to prevent. Pausing, blocking or cancelling a held jobcard is
-- allowed: a hold stops work going out, not the truth about where the work stands.
--
-- Fires on INSERT as well as UPDATE. A gate on the transition alone is walked straight past by
-- creating the work already completed, which is not a hypothetical — it is how a row arrives from
-- an import or from any caller that writes the finished state in one go.
CREATE FUNCTION jobcard_hold_gate() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  blocking text;
BEGIN
  IF NEW.status IN ('completed','closed')
     AND (TG_OP = 'INSERT' OR NEW.status IS DISTINCT FROM OLD.status) THEN
    SELECT string_agg(ref, ', ') INTO blocking
    FROM quality_hold
    WHERE status = 'active'
      AND (jobcard_id = NEW.id OR project_id = NEW.project_id);
    IF blocking IS NOT NULL THEN
      RAISE EXCEPTION 'jobcard % cannot be % while quality hold(s) % are active',
        NEW.ref, NEW.status, blocking USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER jobcard_hold_gate_trg BEFORE INSERT OR UPDATE ON jobcard
  FOR EACH ROW EXECUTE FUNCTION jobcard_hold_gate();

-- Postgres fires BEFORE row triggers in name order, so the hold gate above speaks first. Where a
-- move is both illegal and held, both answers are true and the hold is the more useful one.
CREATE TRIGGER jobcard_status_flow_trg BEFORE UPDATE OF status ON jobcard
  FOR EACH ROW EXECUTE FUNCTION status_flow_gate('jobcard');

CREATE FUNCTION project_hold_gate() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  blocking text;
BEGIN
  IF NEW.status IN ('completed','closed')
     AND (TG_OP = 'INSERT' OR NEW.status IS DISTINCT FROM OLD.status) THEN
    SELECT string_agg(h.ref, ', ') INTO blocking
    FROM quality_hold h
    LEFT JOIN jobcard j ON j.id = h.jobcard_id
    WHERE h.status = 'active'
      AND (h.project_id = NEW.id OR j.project_id = NEW.id);
    IF blocking IS NOT NULL THEN
      RAISE EXCEPTION 'project % cannot be % while quality hold(s) % are active',
        NEW.ref, NEW.status, blocking USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER project_hold_gate_trg BEFORE INSERT OR UPDATE ON project
  FOR EACH ROW EXECUTE FUNCTION project_hold_gate();

CREATE TRIGGER project_status_flow_trg BEFORE UPDATE OF status ON project
  FOR EACH ROW EXECUTE FUNCTION status_flow_gate('project');

-- 2. An operation cannot start on a machine that must not be run.
--
-- Out of service, under maintenance, quarantined and retired all mean the same thing to the person
-- about to press start: not today. The check is on the transition into in-progress, because that
-- is the moment somebody walks up to the machine.
CREATE FUNCTION operation_equipment_gate() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  -- Three named columns rather than SELECT *. This trigger runs with the privileges of whoever is
  -- pressing start, and the workshop is granted equipment column by column because the table holds
  -- a purchase price — so SELECT * is refused for exactly the people this gate exists to protect.
  -- It read `machine equipment%ROWTYPE` until the price column was added, at which point every
  -- welder starting a job got "permission denied for table equipment" instead of a gate. The same
  -- property that keeps a price away from the floor breaks any query that asks for more than it
  -- needs, which is a reason to ask for less.
  machine_status equipment_status;
  machine_name text;
  machine_cert date;
BEGIN
  IF NEW.status = 'in-progress' AND NEW.status IS DISTINCT FROM OLD.status
     AND NEW.equipment_id IS NOT NULL THEN
    SELECT status, name, certification_expiry
      INTO machine_status, machine_name, machine_cert
      FROM equipment WHERE id = NEW.equipment_id;
    -- The same six equipment-gates.js blocks on, rather than four of them. The database was the more
    -- permissive of the two, which means the rule the screen enforced was not the system's rule: a
    -- machine whose service interval has passed could be started by anything that did not go through
    -- that screen.
    IF machine_status IN ('Out of Service', 'Under Maintenance', 'Maintenance Due',
                          'Inspection Required', 'Quarantined', 'Retired') THEN
      RAISE EXCEPTION 'operation % cannot start: % is %',
        NEW.description, machine_name, machine_status USING ERRCODE = 'check_violation';
    END IF;
    IF machine_cert IS NOT NULL AND machine_cert < current_date THEN
      RAISE EXCEPTION 'operation % cannot start: the certification for % expired on %',
        NEW.description, machine_name, machine_cert USING ERRCODE = 'check_violation';
    END IF;
    -- A pre-use check that failed and has not been answered stops the machine. equipment-gates.js has
    -- refused this in the browser since it was written, and the browser is not where a safety rule can
    -- live: a welder who reaches the same jobcard through another screen, or an import, or a console,
    -- walks straight past it. The rule is the same one and it is stated here as well.
    IF EXISTS (SELECT 1 FROM equipment_event
                WHERE equipment_id = NEW.equipment_id
                  AND kind = 'pre-use-check' AND result = 'fail' AND NOT resolved) THEN
      RAISE EXCEPTION 'operation % cannot start: a pre-use check on % failed and has not been answered',
        NEW.description, machine_name USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER operation_equipment_gate_trg BEFORE UPDATE ON operation
  FOR EACH ROW EXECUTE FUNCTION operation_equipment_gate();

-- 3. An operation cannot start before what it depends on is finished, and the chain of
--    dependencies cannot loop back on itself.
CREATE FUNCTION operation_dependency_gate() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  parent operation%ROWTYPE;
  walker bigint;
  hops int := 0;
BEGIN
  -- A cycle would make "what must finish first" unanswerable, so it is refused on the way in.
  IF NEW.depends_on IS NOT NULL THEN
    walker := NEW.depends_on;
    WHILE walker IS NOT NULL AND hops < 100 LOOP
      IF walker = NEW.id THEN
        RAISE EXCEPTION 'operation % would depend on itself through a chain of dependencies',
          NEW.description USING ERRCODE = 'check_violation';
      END IF;
      SELECT depends_on INTO walker FROM operation WHERE id = walker;
      hops := hops + 1;
    END LOOP;
  END IF;

  IF NEW.status = 'in-progress' AND NEW.status IS DISTINCT FROM OLD.status
     AND NEW.depends_on IS NOT NULL THEN
    SELECT * INTO parent FROM operation WHERE id = NEW.depends_on;
    IF parent.status NOT IN ('completed','skipped') THEN
      RAISE EXCEPTION 'operation % cannot start before % is finished',
        NEW.description, parent.description USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER operation_dependency_insert_trg BEFORE INSERT ON operation
  FOR EACH ROW EXECUTE FUNCTION operation_dependency_gate();
CREATE TRIGGER operation_dependency_update_trg BEFORE UPDATE ON operation
  FOR EACH ROW EXECUTE FUNCTION operation_dependency_gate();

-- A step somebody has worked on is a record of what happened, not a line on a plan.
--
-- hours_entry.operation_id is ON DELETE SET NULL, which is right — hours must outlive a step being
-- reorganised — but it means deleting a step succeeds silently and leaves every hour ever booked on
-- it pointing at nothing. What is lost is the answer to "how long did the weld-out actually take",
-- which is the only number that makes the next estimate better than a guess, and nothing would show
-- on any screen. So the delete is refused instead, here rather than only in the workflow that edits
-- the list, because the office holds DELETE on this table and could otherwise do it in one statement.
CREATE FUNCTION operation_keeps_the_work_done_on_it() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.logged_hours > 0 THEN
    RAISE EXCEPTION 'step % (%) has % hours booked on it and cannot be removed',
      OLD.seq, OLD.description, OLD.logged_hours
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF OLD.status <> 'pending' THEN
    RAISE EXCEPTION 'step % (%) is % and cannot be removed', OLD.seq, OLD.description, OLD.status
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  RETURN OLD;
END;
$$;

CREATE TRIGGER operation_keeps_the_work_done_on_it_trg BEFORE DELETE ON operation
  FOR EACH ROW EXECUTE FUNCTION operation_keeps_the_work_done_on_it();

-- 4. Logged hours are the sum of the entries, maintained here so the two can never disagree.
--
-- Both the operation the entry went to and the one it came from are recomputed. An entry booked
-- to the wrong operation and then corrected is the ordinary case, and a roll-up that only looks
-- at the new row leaves the first operation still holding hours that have moved away — the same
-- three hours counted twice, in a figure somebody prices work from.
CREATE FUNCTION hours_roll_up() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  target bigint;
BEGIN
  -- coalesce to an empty array, not just for tidiness: array_agg over no rows is NULL, and FOREACH
  -- over a NULL array raises "FOREACH expression must not be null". An hours entry that names no
  -- operation at all — which is exactly what the phone screen books when a welder picks a job
  -- rather than a step — leaves both sides NULL and took this whole trigger down with it.
  FOREACH target IN ARRAY coalesce((
    SELECT array_agg(DISTINCT id) FROM unnest(ARRAY[
      CASE WHEN TG_OP <> 'INSERT' THEN OLD.operation_id END,
      CASE WHEN TG_OP <> 'DELETE' THEN NEW.operation_id END
    ]) AS id WHERE id IS NOT NULL
  ), ARRAY[]::bigint[]) LOOP
    UPDATE operation SET logged_hours = (
      SELECT COALESCE(SUM(hours), 0) FROM hours_entry WHERE operation_id = target
    ) WHERE id = target;
  END LOOP;
  RETURN COALESCE(NEW, OLD);
END;
$$;

CREATE TRIGGER hours_roll_up_trg AFTER INSERT OR UPDATE OR DELETE ON hours_entry
  FOR EACH ROW EXECUTE FUNCTION hours_roll_up();

-- 5. A project's used hours are the sum of the hours booked to its jobcards.
--
-- Same rule as the operation's logged hours and the estimate's total, and for the same reason: the
-- figure a job is judged late or over by cannot be one somebody types. Both the project an entry
-- left and the one it joined are recomputed, because an entry booked to the wrong jobcard and
-- corrected is the ordinary case — the hours roll-up got that wrong the first time and it is not a
-- mistake worth making twice.
CREATE FUNCTION project_hours_roll_up() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  target bigint;
BEGIN
  FOREACH target IN ARRAY coalesce((
    SELECT array_agg(DISTINCT p) FROM unnest(ARRAY[
      CASE WHEN TG_OP <> 'INSERT' THEN (SELECT project_id FROM jobcard WHERE id = OLD.jobcard_id) END,
      CASE WHEN TG_OP <> 'DELETE' THEN (SELECT project_id FROM jobcard WHERE id = NEW.jobcard_id) END
    ]) AS p WHERE p IS NOT NULL
  ), ARRAY[]::bigint[]) LOOP
    UPDATE project SET used_hours = (
      SELECT COALESCE(SUM(h.hours), 0) FROM hours_entry h
        JOIN jobcard j ON j.id = h.jobcard_id WHERE j.project_id = target
    ) WHERE id = target;
  END LOOP;
  RETURN COALESCE(NEW, OLD);
END;
$$;

CREATE TRIGGER project_hours_roll_up_trg AFTER INSERT OR UPDATE OR DELETE ON hours_entry
  FOR EACH ROW EXECUTE FUNCTION project_hours_roll_up();

-- 6. An hours entry names one job.
--
-- The entry carries both the jobcard and the operation because both are asked for downstream.
-- Nothing stopped the two disagreeing, and an entry that names one job and an operation belonging
-- to another is counted under both — hours on the wrong job is exactly the figure a time system
-- exists to get right.
CREATE FUNCTION hours_entry_names_one_job() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  owner_jobcard bigint;
BEGIN
  IF NEW.operation_id IS NOT NULL THEN
    SELECT jobcard_id INTO owner_jobcard FROM operation WHERE id = NEW.operation_id;
    IF owner_jobcard IS DISTINCT FROM NEW.jobcard_id THEN
      RAISE EXCEPTION 'the operation on this entry belongs to jobcard %, not jobcard %',
        (SELECT ref FROM jobcard WHERE id = owner_jobcard),
        (SELECT ref FROM jobcard WHERE id = NEW.jobcard_id) USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER hours_entry_one_job_trg BEFORE INSERT OR UPDATE ON hours_entry
  FOR EACH ROW EXECUTE FUNCTION hours_entry_names_one_job();

-- 6. An estimate's total is the sum of its lines, plus the margin.
--
-- Same rule as logged hours and for the same reason: a figure somebody can type is a figure that
-- can disagree with what it is made of. This is the figure a job is priced from, so it is computed
-- from the lines on every change to any of them — including a line moved to another estimate, the
-- case the hours roll-up originally got wrong.
CREATE FUNCTION estimate_total_roll_up() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  target bigint;
BEGIN
  FOREACH target IN ARRAY coalesce((
    SELECT array_agg(DISTINCT id) FROM unnest(ARRAY[
      CASE WHEN TG_OP <> 'INSERT' THEN OLD.estimate_id END,
      CASE WHEN TG_OP <> 'DELETE' THEN NEW.estimate_id END
    ]) AS id WHERE id IS NOT NULL
  ), ARRAY[]::bigint[]) LOOP
    UPDATE estimate e SET total = round(
      COALESCE((SELECT SUM(line_total) FROM estimate_line WHERE estimate_id = target), 0)
      * (1 + e.margin_pct / 100), 2)
    WHERE e.id = target;
  END LOOP;
  RETURN COALESCE(NEW, OLD);
END;
$$;

CREATE TRIGGER estimate_total_roll_up_trg AFTER INSERT OR UPDATE OR DELETE ON estimate_line
  FOR EACH ROW EXECUTE FUNCTION estimate_total_roll_up();

-- Changing the margin changes the total too, which is easy to forget when only the lines have a
-- trigger on them.
CREATE FUNCTION estimate_margin_roll_up() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.total := round(
    COALESCE((SELECT SUM(line_total) FROM estimate_line WHERE estimate_id = NEW.id), 0)
    * (1 + NEW.margin_pct / 100), 2);
  RETURN NEW;
END;
$$;

CREATE TRIGGER estimate_margin_roll_up_trg BEFORE UPDATE OF margin_pct ON estimate
  FOR EACH ROW EXECUTE FUNCTION estimate_margin_roll_up();

-- 8. A locked estimate line cannot be repriced without a reason and a name.
--
-- The reason must also be a *new* reason. Requiring only that the column is non-empty means a
-- caller who leaves the previous justification sitting there can reprice as often as it likes, and
-- the column stops recording anything — which is the failure this rule exists to prevent rather
-- than a hypothetical, because it is the cheapest path for whoever writes the caller.
CREATE FUNCTION estimate_line_reprice_gate() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.locked AND (NEW.unit_price IS DISTINCT FROM OLD.unit_price
                     OR NEW.quantity IS DISTINCT FROM OLD.quantity) THEN
    IF btrim(coalesce(NEW.reprice_reason, '')) = '' OR btrim(coalesce(NEW.repriced_by, '')) = '' THEN
      RAISE EXCEPTION 'line "%" has gone to the customer: repricing it needs a reason and a name',
        NEW.description USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.reprice_reason IS NOT DISTINCT FROM OLD.reprice_reason THEN
      RAISE EXCEPTION 'line "%" was already repriced for that reason: this change needs its own',
        NEW.description USING ERRCODE = 'check_violation';
    END IF;
    NEW.repriced_at := now();
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER estimate_line_reprice_gate_trg BEFORE UPDATE ON estimate_line
  FOR EACH ROW EXECUTE FUNCTION estimate_line_reprice_gate();

-- 9. Stock moves through one door.
--
-- Issuing more than exists is refused with a message that names the shortfall, rather than letting
-- the CHECK fire with something nobody can act on. The CHECK stays as the floor beneath it: this
-- function holds against the callers that use it, the CHECK holds against every other path.
CREATE FUNCTION issue_stock(
  p_item_id bigint, p_quantity numeric, p_jobcard_id bigint, p_by text, p_note text DEFAULT NULL
) RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE
  item stock_item%ROWTYPE;
  movement_id bigint;
BEGIN
  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    RAISE EXCEPTION 'a stock issue must be for more than nothing' USING ERRCODE = 'check_violation';
  END IF;
  -- Locked, so two people issuing the last of something cannot both succeed.
  SELECT * INTO item FROM stock_item WHERE id = p_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such stock item' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF item.stock < p_quantity THEN
    RAISE EXCEPTION 'cannot issue % % of %: only % in stock',
      p_quantity, item.unit, item.code, item.stock USING ERRCODE = 'check_violation';
  END IF;

  UPDATE stock_item
     SET stock = stock - p_quantity,
         reserved = GREATEST(0, reserved - p_quantity)
   WHERE id = p_item_id;

  INSERT INTO stock_movement (stock_item_id, kind, quantity, jobcard_id, moved_by, note)
  VALUES (p_item_id, 'issue', p_quantity, p_jobcard_id, p_by, p_note)
  RETURNING id INTO movement_id;

  -- trim_scale so the line reads the same however the caller typed the number: 30, 30.0 and
  -- 30.000 are the same amount of steel and should not read as three different records.
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('stock_item', p_item_id, 'issued', p_by,
          trim_scale(p_quantity) || ' ' || item.unit || ' of ' || item.code);

  RETURN movement_id;
END;
$$;

-- COMMIT; (removed: ending it here would commit a part of the install on its own)

-- ═══════════════════════════════════════════════════════════════════════════════════════════
-- auth.sql
-- ═══════════════════════════════════════════════════════════════════════════════════════════

-- Varmak Workshop — who is asking, and what that lets them see.
--
-- Step 3 of BACKEND.md: auth and the two roles, with row-level security written alongside the
-- tables. Run after schema.sql.
--
-- The sentence this file exists to make true is in BACKEND.md §1b:
--
--     "A welder's session must be unable to read the customer's agreed price even by asking the
--      API directly."
--
-- Hiding a button does not do that. Checking a role in application code does not do that either —
-- it holds until somebody adds a second caller, an export, a report, a debugging endpoint. The
-- only place it holds against every one of those is the database, which is why the limit is a
-- GRANT and a policy here rather than an `if` somewhere in the API.
--
-- Two doors, as decided, because they guard different things:
--
--   • Office and site — email and password. Anything touching prices, approvals or deletion.
--   • Shop floor — a shared tablet and a personal PIN. A welder in gloves will not type a password
--     forty times a day; if you make them, they share one login and the hours data becomes
--     worthless. A PIN answers "who booked these hours", and the cost of a wrong answer there is a
--     corrected timesheet. So a PIN opens a `workshop` session and nothing more, and the limit is
--     enforced here — it holds even if somebody works out the PIN.
--
-- On Supabase this is the same shape: the JWT's role claim selects the Postgres role, and the
-- verified user id is put into a session setting. `app.user_id` is that setting. Nothing in this
-- file trusts anything the client sends; the API sets it only after verifying a credential.

-- BEGIN; (removed: the SQL editor opens the transaction that covers all four files)

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- And then: where did it actually go?
--
-- A managed Postgres — Supabase among them — installs extensions into a schema of their own rather
-- than into `public`, and then two different things break. The first breaks the install, three tables
-- below: `app_session.token` has `DEFAULT encode(gen_random_bytes(32), 'hex')`, a column default is
-- parsed while the table is being created, and the install stops dead on "function
-- gen_random_bytes(integer) does not exist". The second breaks later and much more quietly: every PIN
-- and every password in this system is hashed by `crypt()` inside a function body, which is resolved
-- when it runs rather than when it was written — so a deployment that installed perfectly can still
-- be one where nobody can sign in, discovered by a workshop on the morning it meant to start.
--
-- Three paths therefore have to be right, and they are set in three places: this session's, for the
-- rest of this file; the database's, for every session opened afterwards; and the connecting role's,
-- further down, which is the one the server's own sessions get.
DO $$
DECLARE
  home text := (SELECT n.nspname FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace
                 WHERE e.extname = 'pgcrypto');
BEGIN
  IF home IS NULL THEN
    RAISE EXCEPTION 'pgcrypto is not installed in this database, and every password in this system needs it';
  END IF;
  IF home = 'public' THEN
    RETURN;
  END IF;
  PERFORM set_config('search_path', format('public, %I', home), false);
  BEGIN
    EXECUTE format('ALTER DATABASE %I SET search_path = public, %I', current_database(), home);
  EXCEPTION WHEN insufficient_privilege THEN
    -- Not fatal: the role-level path below is what the server's sessions use. Said out loud, because
    -- it means a psql session opened by hand will not find crypt() and that is confusing on its own.
    RAISE NOTICE 'not the owner of this database, so its search_path is unchanged — the role''s is still set';
  END;
  RAISE NOTICE 'pgcrypto is in schema %, so the search_path includes it', home;
END;
$$;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Who the database thinks is asking
--
-- Fails closed. A connection that has not said who it is gets NULL, and every policy below treats
-- NULL as "no". The failure mode of a mistake here must be that nobody can see anything, never
-- that everybody can.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE FUNCTION current_app_user() RETURNS bigint
LANGUAGE sql STABLE AS $$
  SELECT NULLIF(current_setting('app.user_id', true), '')::bigint;
$$;

-- SECURITY DEFINER, and owned further down by the one role that may step around row security.
-- Not for convenience: app_user has a policy of its own, and that policy asks what role you are,
-- which asks app_user, which evaluates the policy. Postgres answers that with "stack depth limit
-- exceeded" on the first query any welder runs — found exactly that way. A function that reads one
-- row to answer "who am I" cannot be subject to a policy that needs the answer first.
CREATE FUNCTION current_app_role() RETURNS user_role
LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
DECLARE
  claimed text := NULLIF(current_setting('app.user_role', true), '');
  actual  user_role;
BEGIN
  -- The role is read from the row, not from the setting. The setting is a convenience for the API
  -- and a client could put anything in it; the row is the record. If the two disagree the row wins,
  -- which is the whole reason this is a function and not a `current_setting` call inline.
  SELECT role INTO actual FROM app_user WHERE id = current_app_user() AND is_active;
  IF actual IS NULL THEN
    RETURN NULL;
  END IF;
  IF claimed IS NOT NULL AND claimed <> actual::text THEN
    RAISE EXCEPTION 'session claims the role % but % is %',
      claimed, (SELECT email FROM app_user WHERE id = current_app_user()), actual
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN actual;
END;
$$;

-- Your own name, for the policies that record who did something. Same reasoning as above: a policy
-- on hours_entry that reads app_user directly drags app_user's policy into every insert.
CREATE FUNCTION current_app_name() RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER AS $$
  SELECT display_name FROM app_user WHERE id = current_app_user() AND is_active;
$$;

-- coalesce, and it is not tidiness. current_app_role() is NULL when nobody is signed in, so
-- `current_app_role() = 'admin'` is NULL rather than false — and `IF NOT is_admin() THEN RAISE` in
-- plpgsql does nothing at all when the condition is NULL. Every authorisation guard written that
-- way was therefore skipped entirely for exactly the case it exists to refuse: no session.
--
-- Row-level policies were never affected, because RLS treats NULL as "not true" — which is why this
-- survived until a workflow with a plpgsql guard was written and a test called it with no session.
CREATE FUNCTION is_admin() RETURNS boolean
LANGUAGE sql STABLE AS $$ SELECT coalesce(current_app_role() = 'admin', false); $$;

-- "Can see money" rather than "is office": the question asked at every price column, named for what
-- it decides rather than for who happens to satisfy it today.
CREATE FUNCTION may_see_money() RETURNS boolean
LANGUAGE sql STABLE AS $$ SELECT coalesce(current_app_role() IN ('admin', 'office'), false); $$;

CREATE FUNCTION is_signed_in() RETURNS boolean
LANGUAGE sql STABLE AS $$ SELECT current_app_role() IS NOT NULL; $$;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Passwords and PINs
--
-- Neither is ever stored. Both are hashed with bcrypt through pgcrypto, and the hashing happens
-- here rather than in the API so that there is exactly one implementation of it — an API that
-- hashes passwords itself is an API that can be given a second one that does not.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

ALTER TABLE app_user
  ADD COLUMN pin_hash text CONSTRAINT pin_is_hashed
             CHECK (pin_hash IS NULL OR pin_hash ~ '^\$2[aby]\$\d{2}\$'),
  ADD COLUMN pin_set_at timestamptz,
  -- Beside pin_set_at, and for the same reason. add_person deliberately creates somebody with no
  -- way in at all, so the screen that adds people has to be able to say so — and a screen that
  -- cannot tell "password set" from "no password yet" tells an admin they have given somebody
  -- access when they have not. The hash stays unreadable to everybody; this column says only that
  -- one exists, which is the part anybody needs.
  ADD COLUMN password_set_at timestamptz,
  -- A four-digit PIN is ten thousand guesses. Without a lockout that is not a credential, it is a
  -- formality, and the lockout has to live where the checking lives or it can be skipped.
  ADD COLUMN failed_attempts int NOT NULL DEFAULT 0 CHECK (failed_attempts >= 0),
  ADD COLUMN locked_until timestamptz,
  ADD COLUMN last_seen_at timestamptz;

-- The PINs people actually choose when nobody stops them. A PIN guards whose name goes on a
-- timesheet, so it may be short — it may not be guessable on the first try.
CREATE FUNCTION pin_is_too_obvious(p_pin text) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT p_pin IN ('0000','1111','2222','3333','4444','5555','6666','7777','8888','9999',
                   '1234','4321','0123','2580','1212','6969','1004','2000','1010','1122')
      OR p_pin ~ '^(.)\1+$';
$$;

CREATE FUNCTION set_pin(p_user_id bigint, p_pin text) RETURNS void
LANGUAGE plpgsql AS $$
BEGIN
  IF p_pin !~ '^\d{4,8}$' THEN
    RAISE EXCEPTION 'a PIN is four to eight digits' USING ERRCODE = 'check_violation';
  END IF;
  IF pin_is_too_obvious(p_pin) THEN
    RAISE EXCEPTION 'that PIN is one of the first a stranger would try' USING ERRCODE = 'check_violation';
  END IF;
  UPDATE app_user
     SET pin_hash = crypt(p_pin, gen_salt('bf', 8)), pin_set_at = now(),
         failed_attempts = 0, locked_until = NULL
   WHERE id = p_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such person' USING ERRCODE = 'foreign_key_violation';
  END IF;
END;
$$;

CREATE FUNCTION set_password(p_user_id bigint, p_password text) RETURNS void
LANGUAGE plpgsql AS $$
BEGIN
  -- Length rather than a character-class rule. A rule demanding a capital and a symbol produces
  -- Passw0rd! on every account in the building; length is the thing that actually costs a guesser.
  IF p_password IS NULL OR length(p_password) < 12 THEN
    RAISE EXCEPTION 'a password needs at least twelve characters' USING ERRCODE = 'check_violation';
  END IF;
  IF lower(p_password) IN ('password1234','varmakvarmak','123456789012','qwertyuiopas') THEN
    RAISE EXCEPTION 'that password is on every list a guesser starts from' USING ERRCODE = 'check_violation';
  END IF;
  UPDATE app_user
     SET password_hash = crypt(p_password, gen_salt('bf', 10)), password_set_at = now(),
         failed_attempts = 0, locked_until = NULL
   WHERE id = p_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such person' USING ERRCODE = 'foreign_key_violation';
  END IF;
END;
$$;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Sessions
--
-- A row per session, so one can be ended from the office when a tablet goes missing — which is the
-- thing a stateless token cannot do. Shop-floor sessions end with the shift rather than in thirty
-- days: a tablet left logged in overnight is the whole hall logged in as one welder.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE TYPE session_door AS ENUM ('password', 'pin');

CREATE TABLE app_session (
  token       text PRIMARY KEY DEFAULT encode(gen_random_bytes(32), 'hex'),
  user_id     bigint NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
  door        session_door NOT NULL,
  device      text,
  started_at  timestamptz NOT NULL DEFAULT now(),
  expires_at  timestamptz NOT NULL,
  ended_at    timestamptz,
  CHECK (expires_at > started_at)
);

CREATE INDEX session_user_idx ON app_session(user_id) WHERE ended_at IS NULL;

-- End of shift, not thirty days. 18:00 local if that is still ahead, otherwise 18:00 tomorrow —
-- a late shift starting at 22:00 gets the following evening rather than four minutes.
CREATE FUNCTION end_of_shift() RETURNS timestamptz
LANGUAGE sql STABLE AS $$
  SELECT CASE WHEN now() < date_trunc('day', now()) + interval '18 hours'
              THEN date_trunc('day', now()) + interval '18 hours'
              ELSE date_trunc('day', now()) + interval '42 hours'
         END;
$$;

-- One place that decides whether a credential was right, so that "too many tries" cannot be
-- true at one door and false at the other.
CREATE FUNCTION register_failure(p_user_id bigint) RETURNS void
LANGUAGE plpgsql AS $$
DECLARE
  attempts int;
BEGIN
  UPDATE app_user SET failed_attempts = failed_attempts + 1 WHERE id = p_user_id
  RETURNING failed_attempts INTO attempts;
  -- Five tries, then fifteen minutes. Long enough to make ten thousand guesses take weeks, short
  -- enough that a welder who fumbled it is not sent home.
  IF attempts >= 5 THEN
    UPDATE app_user SET locked_until = now() + interval '15 minutes', failed_attempts = 0
     WHERE id = p_user_id;
  END IF;
END;
$$;

-- Returns a result rather than raising, and that is not a style preference — it is the only way
-- this can work.
--
-- The first version raised an exception on a wrong secret, after calling register_failure to count
-- it. The RAISE aborted the transaction and rolled back the count, so failed_attempts never moved,
-- locked_until was never set, and the lockout did nothing whatsoever. A four-digit PIN with no
-- working lockout is ten thousand free guesses, which is to say it is not a credential at all. The
-- tests caught it on the sixth guess.
--
-- So: a function that has to record something cannot also abort. Refusals come back as text in the
-- `refused` field, the transaction commits, and the count sticks. The API turns a non-null
-- `refused` into a 401 and shows the text.
CREATE TYPE sign_in_result AS (token text, refused text);

CREATE FUNCTION sign_in(p_email text, p_secret text, p_door session_door, p_device text DEFAULT NULL)
RETURNS sign_in_result
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  person app_user%ROWTYPE;
  stored text;
  result sign_in_result;
BEGIN
  SELECT * INTO person FROM app_user WHERE email = lower(btrim(p_email));

  -- The same words whether the address is unknown, the account is switched off, or the secret is
  -- wrong. Three different answers would tell a stranger which addresses are real, and the sleep
  -- keeps an unknown address from being the fast one to ask about.
  IF person.id IS NULL OR NOT person.is_active THEN
    PERFORM pg_sleep(0.1);
    RETURN (NULL, 'that is not a login we recognise')::sign_in_result;
  END IF;

  IF person.locked_until IS NOT NULL AND person.locked_until > now() THEN
    -- No further counting while locked: the lock is already doing its job, and extending it on
    -- every attempt would let a stranger keep a colleague locked out indefinitely.
    RETURN (NULL, 'too many tries — this login is locked until '
                  || to_char(person.locked_until, 'HH24:MI'))::sign_in_result;
  END IF;

  -- The PIN door only ever opens a workshop session. An admin standing at the shared tablet gets
  -- the tablet's authority, not their own — otherwise the strength of the door stops matching what
  -- is behind it, which is the entire argument for having two doors.
  IF p_door = 'pin' AND person.role <> 'workshop' THEN
    RETURN (NULL, 'the shop tablet opens a workshop session; ' || person.email
                  || ' needs the office door for their own')::sign_in_result;
  END IF;

  stored := CASE p_door WHEN 'pin' THEN person.pin_hash ELSE person.password_hash END;
  IF stored IS NULL OR crypt(p_secret, stored) <> stored THEN
    PERFORM register_failure(person.id);
    RETURN (NULL, 'that is not a login we recognise')::sign_in_result;
  END IF;

  UPDATE app_user SET failed_attempts = 0, locked_until = NULL, last_seen_at = now()
   WHERE id = person.id;

  INSERT INTO app_session (user_id, door, device, expires_at)
  VALUES (person.id, p_door, p_device,
          CASE p_door WHEN 'pin' THEN end_of_shift() ELSE now() + interval '12 hours' END)
  RETURNING token INTO result.token;

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('app_user', person.id, 'signed in', person.email, p_door::text);

  RETURN result;
END;
$$;

-- Hands back the person a token belongs to, or nothing. The API calls this and then sets
-- app.user_id from the answer; it never takes a user id from the client.
CREATE FUNCTION session_owner(p_token text) RETURNS bigint
LANGUAGE sql STABLE SECURITY DEFINER AS $$
  SELECT user_id FROM app_session
   WHERE token = p_token AND ended_at IS NULL AND expires_at > now();
$$;

CREATE FUNCTION sign_out(p_token text) RETURNS void
LANGUAGE sql SECURITY DEFINER AS $$
  UPDATE app_session SET ended_at = now() WHERE token = p_token AND ended_at IS NULL;
$$;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- The roles, as real database roles
--
-- Not strings in a column that application code compares. A GRANT is checked by the server on
-- every statement, including the ones nobody has written yet: an export, a report, a console
-- somebody opens at midnight to "just check something".
--
-- varmak_api is what the connection pool logs in as. It can become any of the three and can do
-- nothing itself, so a bug that forgets to pick a role ends with a session that cannot read a
-- single row — which is the direction a mistake here has to fail.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'varmak_admin') THEN
    CREATE ROLE varmak_admin NOLOGIN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'varmak_office') THEN
    CREATE ROLE varmak_office NOLOGIN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'varmak_workshop') THEN
    CREATE ROLE varmak_workshop NOLOGIN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'varmak_api') THEN
    -- LOGIN, because this is the one role that actually connects. NOINHERIT is the important half:
    -- it holds membership of the three roles but none of their privileges until it explicitly
    -- becomes one, so a connection that has not chosen a role can do nothing at all.
    --
    -- No password is set here. On this machine the server trusts a local socket; anywhere else the
    -- password is set outside this file and kept out of the repository, which is why there is no
    -- line here to forget to change.
    CREATE ROLE varmak_api LOGIN NOINHERIT;
  END IF;
END;
$$;

-- Roles live in the cluster, not in the database, so they survive dropping and rebuilding this one
-- and the guards above skip them on the second run. That means a role created with the wrong
-- attributes once stays wrong forever, which is exactly what happened: varmak_api was created
-- without LOGIN, and creating it correctly afterwards changed nothing because it already existed.
-- Setting the attributes unconditionally is the only version of this that is safe to run twice.
ALTER ROLE varmak_api LOGIN NOINHERIT;
ALTER ROLE varmak_admin NOLOGIN NOBYPASSRLS;
ALTER ROLE varmak_office NOLOGIN NOBYPASSRLS;
ALTER ROLE varmak_workshop NOLOGIN NOBYPASSRLS;
ALTER ROLE varmak_api NOBYPASSRLS;

-- NOSUPERUSER was on those four lines and cannot be. Postgres refuses any mention of the SUPERUSER
-- attribute from a role that is not a superuser itself — even when the mention changes nothing — and
-- on a managed database the most privileged role you are given is never a superuser. So the install
-- stopped here, four lines into the roles, on every hosted Postgres there is.
--
-- The intent was worth keeping, so it is asserted rather than set: a superuser among these roles would
-- sit outside every policy in this file, and the system would look exactly as it does when it works.
-- Asserting it is also strictly better than setting it, because it catches the case where somebody
-- granted it by hand afterwards.
DO $$
DECLARE
  wrong text := (SELECT string_agg(rolname, ', ' ORDER BY rolname) FROM pg_roles
                  WHERE rolname IN ('varmak_admin', 'varmak_office', 'varmak_workshop', 'varmak_api')
                    AND rolsuper);
BEGIN
  IF wrong IS NOT NULL THEN
    RAISE EXCEPTION '% is a superuser, which puts it outside every row-level policy in this file', wrong;
  END IF;
END;
$$;

GRANT varmak_admin, varmak_office, varmak_workshop TO varmak_api;
GRANT USAGE ON SCHEMA public TO varmak_admin, varmak_office, varmak_workshop, varmak_api;

-- Where pgcrypto actually is, which on a managed database is not where this file assumes.
--
-- Every PIN and every password in this system is hashed by crypt() and gen_salt(), and both come from
-- pgcrypto. On a machine where this was developed the extension goes into `public` and is found
-- without anybody thinking about it. A hosted Postgres — Supabase among them — installs its
-- extensions into a schema of their own, and then the connecting role's search_path cannot see those
-- two functions: `sign_in` raises "function crypt(text, text) does not exist" and NOBODY CAN GET IN.
--
-- That failure arrives at the first sign-in on a new deployment, which is the worst possible place to
-- find it — the install said nothing, every table is there, and the only symptom is a workshop locked
-- out of its own system on the morning it was meant to start using it.
--
-- So the path is set here from where this database actually put the extension, rather than assumed.
-- Only varmak_api needs it: a role's settings are applied when it logs in, and SET LOCAL ROLE does
-- not re-apply them, so the one role that connects is the one that carries the path for the three it
-- becomes. The functions that hash are SECURITY DEFINER but do not set a path of their own, so they
-- run with the session's — which is this one.
DO $$
DECLARE
  home text := (SELECT n.nspname FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace
                 WHERE e.extname = 'pgcrypto');
BEGIN
  IF home IS NULL THEN
    RAISE EXCEPTION 'pgcrypto is not installed in this database, and every password in this system needs it';
  END IF;
  IF home <> 'public' THEN
    EXECUTE format('ALTER ROLE varmak_api SET search_path = public, %I', home);
    EXECUTE format('GRANT USAGE ON SCHEMA %I TO varmak_api', home);
    RAISE NOTICE 'pgcrypto is in schema %, so varmak_api searches there too', home;
  END IF;
END;
$$;

-- Sequences are needed by anyone who may insert; without this an insert fails on the id.
GRANT USAGE ON ALL SEQUENCES IN SCHEMA public TO varmak_admin, varmak_office, varmak_workshop;

-- ── What each role may touch at all ───────────────────────────────────────────────────────

GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO varmak_admin;

-- Office runs the commercial side. No deleting: a quote that was sent and a job that was run are
-- the record of what happened, and removing one is not a correction, it is a different past.
GRANT SELECT, INSERT, UPDATE ON ALL TABLES IN SCHEMA public TO varmak_office;

-- The workshop. Everything it is listed as being able to do in BACKEND.md §1b, and nothing else:
-- book hours, start and pause operations, issue material, record an inspection result.
-- Whole tables, because none of these holds a figure in kronor — and that sentence has now been
-- wrong four times. stock_item, equipment_event, equipment and project each sat in this list and
-- each quietly acquired a money column later, at which point every welder could read it. A
-- table-wide GRANT SELECT includes every column, and a narrower column grant written afterwards
-- adds nothing to it, so auth.sql looked like it said otherwise while a welder read avg_cost
-- straight out of the store. The privilege check in test-auth.js asserts the privilege tables
-- directly rather than trusting this list, and caught all four — but the pattern is the point: a
-- table in this list is one bet that it will never hold money, and that bet keeps losing.
--
-- So the rule to apply when adding to this list: if the table could ever carry a price, a cost, a
-- value or a rate, it does not go here. It is granted column by column below, where adding a money
-- column later is safe by default because new columns are not granted at all.
GRANT SELECT ON
  jobcard, operation, equipment_assignment,
  item_group, location, offcut, barcode, allowed_transition,
  quality_hold, inspection, ncr, hours_entry, stock_movement, document,
  -- A name, a role, an email and a telephone number. Nothing on this table could ever be a price,
  -- which is the test the comment above sets for being in this list — and a welder holding a drawing
  -- that is wrong needs to be able to ring somebody.
  customer_contact
TO varmak_workshop;

-- project holds what the job was quoted at.
GRANT SELECT (id, ref, name, customer_id, status, planned_hours, progress, deadline, description,
              phase, work_types, po_number, workshop, responsible, material_status, notes,
              planned_start, actual_start, planned_completion, expected_completion,
              actual_completion, closed_on, used_hours, hold_reason, hold_comment, expected_resume,
              cancel_reason, created_at)
ON project TO varmak_workshop;

GRANT INSERT ON hours_entry, stock_movement, equipment_event, inspection, equipment_assignment
TO varmak_workshop;
GRANT UPDATE ON operation, jobcard, hours_entry, equipment_assignment TO varmak_workshop;

-- What a welder writes when they record an inspection result, column by column. Everything that says
-- what was asked for — the drawing, the revision, the acceptance criteria, whether the customer is
-- coming to witness it — stays out of this list, because a result recorded alongside a quietly
-- changed acceptance criterion is a pass against a standard nobody agreed to.
GRANT UPDATE (result, findings, critical, actual_date, inspector, status)
ON inspection TO varmak_workshop;
-- The checklist is the evidence, so the floor writes it and can clear it while the inspection is
-- still open — complete_inspection replaces the lines wholesale rather than patching them.
GRANT SELECT, INSERT, DELETE ON inspection_check TO varmak_workshop;

-- The merchant a non-conforming plate came from, by name. payment_terms_days is what this supplier is
-- paid on, which is a commercial term and stays out by the same §1b line that withholds a customer's
-- price list — so this is a column grant and not the table. The name is in because a welder who has
-- just rejected a batch of steel needs to be able to say whose steel it was, and the NCR register
-- shows exactly that column.
-- payment_terms_days is what this workshop is paid on, and supplier_item holds what each merchant
-- charges — both are prices in the sense §1b means, so both stay with the money. Everything else about
-- a merchant is here: what they sell, where they are, who to ring, and what this workshop thinks of
-- them, because a welder who has just rejected a batch of steel needs to say whose steel it was.
GRANT SELECT (id, ref, name, org_no, vat_no, email, phone, website, address, city, country,
              category, supplier_type, established, delivery_terms, minimum_order, currency,
              rating, status, notes, created_at)
ON supplier TO varmak_workshop;
GRANT SELECT ON supplier_contact TO varmak_workshop;

-- The customer is visible because a welder needs to know whose job is on the bench: who they are,
-- where they are, how to reach them if a drawing is wrong.
--
-- What is withheld is not just the credit limit. price_list, discount_agreement and
-- payment_terms_days are pricing information even though none of them is a number in kronor — they
-- say what this customer is charged — and billing_address and currency belong to invoicing rather
-- than to the bench. §1b says the floor sees no prices; a price list is a price.
GRANT SELECT (id, ref, name, org_no, vat_no, email, phone, city, country, status, website,
              industry, customer_since, customer_type, is_preferred, preferred_contact, notes,
              created_at)
ON customer TO varmak_workshop;

-- ── Money, column by column ───────────────────────────────────────────────────────────────
--
-- This is the sentence from §1b, made literal. The workshop has no SELECT privilege on these
-- columns at all, so `SELECT avg_cost FROM stock_item` is refused by the server — not filtered,
-- not blanked, refused. It cannot be reached through a view the workshop is granted either,
-- because the view would have to be owned by somebody who can read the column and that is exactly
-- the mistake this makes visible.
--
-- The cost of this is real and worth stating: the workshop's queries must name their columns.
-- `SELECT *` on stock_item fails for them. That is the right trade — a SELECT * that silently
-- started returning a price column would be the failure this file exists to prevent.

GRANT SELECT (id, code, description, unit, stock, reserved, min_stock, group_id, location_id,
              subgroup_id, sublocation_id, bin_code, heat_no, unit_weight, base_unit, size_per_unit,
              weight_per_base, category, grade, dimensions, material_cert_ref, status,
              reorder_quantity, created_at)
ON stock_item TO varmak_workshop;

-- equipment was in the whole-table list above until it gained a purchase price in step 5, at which
-- point a welder could read what every machine in the building cost. The privilege check in
-- test-auth.js caught it the same minute the column was added, which is the third time that exact
-- pattern has appeared in this file: a table in a broad grant quietly acquiring a column that does
-- not belong in it. A table with money in it is granted column by column, always.
GRANT SELECT (id, ref, name, category, status, certification_expiry, manufacturer, model, serial_no,
              asset_no, year_of_manufacture, description, current_location, home_location,
              department, responsible_person, operator, condition, criticality, safety_warnings,
              warranty_expiry,
              -- When it was bought and from whom, which the register shows and neither of which is a
              -- figure in kronor. purchase_price is, and is deliberately not here — the whole reason
              -- this grant is written column by column.
              purchase_date, purchase_supplier,
              operating_hours, service_interval_hours, last_service_date,
              last_inspection_date, last_calibration_date, qr_code, assigned_project_id, notes,
              -- Whether this machine needs a check before it is run. The floor is the only place that
              -- can answer it, so the floor has to be able to see that it is being asked.
              pre_use_check_required,
              created_at)
ON equipment TO varmak_workshop;

-- The three added with the pre-use check are here rather than left out, and each is needed by name:
-- `jobcard_id` because a check is signed for a particular job and the gate matches on that, `resolved`
-- because it is the flag the gate reads to decide whether a failure still stops the machine, and
-- `resolves_event_id` because a passing check has to be able to say which failure it answers. `cost`
-- stays out: what a repair cost is money, and this list is column by column for exactly that reason.
--
-- Left out, the gate in schema.sql read `resolved` on the welder's behalf and Postgres answered
-- "permission denied for table equipment_event" — so every welder starting a job got a privilege error
-- instead of a safety check. That is the fifth time a new column has done this, and it is the column
-- grant working: a column nobody has thought about is a column nobody can read.
GRANT SELECT (id, equipment_id, kind, happened_on, performed_by, result, next_due_on, note,
              jobcard_id, resolved, resolves_event_id, created_at)
ON equipment_event TO varmak_workshop;
GRANT INSERT (equipment_id, kind, happened_on, performed_by, result, next_due_on, note,
              jobcard_id, resolves_event_id)
ON equipment_event TO varmak_workshop;
-- And UPDATE on the one flag, because record_equipment_event marks a failure answered when the check
-- that answers it is signed — by the welder standing in front of the machine. Only that column: a
-- floor that could rewrite the result of a check it made yesterday is not a record.
GRANT UPDATE (resolved) ON equipment_event TO varmak_workshop;

-- The commercial tables are not granted to the workshop at all, so there is nothing to revoke a
-- column from: estimate, estimate_line, supplier, supplier_item, purchase_order,
-- purchase_order_line, lead, prospect_finding, opportunity, tender. A welder asking any of them
-- gets "permission denied for table", which is the honest answer.

-- app_user, taken back and given out again column by column.
--
-- The REVOKE is the important line. GRANT ... ON ALL TABLES above included app_user, which handed
-- admin and office every column of it — the password hash and the PIN hash among them. A narrower
-- GRANT written afterwards would have added nothing, exactly as it did not for stock_item. So the
-- table-wide privilege is removed first and then only the columns anybody has a reason to see are
-- given back.
--
-- Nobody gets password_hash or pin_hash. Not office, not admin. There is no operation in this
-- system that needs to read them: signing in compares inside the database, and setting a new one
-- overwrites. A hash that cannot be selected cannot be carried out of the building in a CSV.
REVOKE ALL ON app_user FROM varmak_admin, varmak_office, varmak_workshop;
GRANT SELECT (id, email, display_name, role, is_active, last_seen_at, pin_set_at,
              password_set_at, failed_attempts, locked_until, created_at)
ON app_user TO varmak_admin, varmak_office, varmak_workshop;

-- The one place the office may delete, and it is a considered exception to the rule above rather
-- than an oversight. That rule is about the record of what happened: a quote that was sent and a job
-- that was run cannot be removed, because removing one is not a correction, it is a different past.
-- A contact at a customer is not that. Somebody who has left the company is not a record of
-- anything, and taking their name off the list is exactly a correction — while leaving it there
-- means somebody rings a number that has been reassigned and believes what they are told.
-- Both contact lists are replaced wholesale by their save functions, which delete and re-insert, so the
-- office needs DELETE on them. It is the one place in the system where deleting a row is the right shape
-- for an edit: a contact who has left the company is not history, they are a mistake in a list.
GRANT DELETE ON customer_contact, supplier_contact TO varmak_office;

-- And on the steps of a jobcard, for the same reason and with the same test applied: editing a plan
-- means taking a line off it, and a line nobody has worked on is not a record of anything. What makes
-- this safe is not this grant being narrow — it is the trigger in schema.sql that refuses to delete a
-- step with hours booked on it or one that has been started, whoever asks and however they ask.
GRANT DELETE ON operation TO varmak_office;

-- Only an admin creates or changes people — no self-registration, and nobody promotes themselves.
GRANT INSERT, UPDATE, DELETE ON app_user TO varmak_admin;
GRANT SELECT, INSERT, UPDATE ON app_session TO varmak_admin, varmak_office, varmak_workshop;

-- The log is written by triggers and functions and read by people. Nobody updates or deletes it —
-- the trigger in schema.sql refuses that anyway, but a privilege is cheaper than a refusal.
GRANT SELECT, INSERT ON activity_log TO varmak_admin, varmak_office, varmak_workshop;
REVOKE UPDATE, DELETE ON activity_log FROM varmak_admin, varmak_office, varmak_workshop;

-- A stock movement is append-only for the same reason, and it took a test to notice: admin and
-- office held UPDATE and DELETE on it from the broad grant, with no policy behind either, so the
-- privilege did nothing and looked as though it did something.
--
-- Asked properly, the answer is not "add a policy" — it is that a movement is the record explaining
-- why a stock figure changed, and editing one leaves the store unable to explain itself. Getting a
-- movement wrong is corrected by an adjustment movement, which is also what a real store does: you
-- do not rub out the goods-in book, you write the correction underneath.
REVOKE UPDATE, DELETE ON stock_movement FROM varmak_admin, varmak_office, varmak_workshop;

GRANT EXECUTE ON FUNCTION current_app_user(), current_app_role(), current_app_name(),
  is_admin(), may_see_money(), is_signed_in()
TO varmak_admin, varmak_office, varmak_workshop, varmak_api;

GRANT EXECUTE ON FUNCTION sign_in(text, text, session_door, text) TO varmak_api;
GRANT EXECUTE ON FUNCTION session_owner(text) TO varmak_api;
GRANT EXECUTE ON FUNCTION sign_out(text) TO varmak_api, varmak_admin, varmak_office, varmak_workshop;
GRANT EXECUTE ON FUNCTION next_item_number(bigint) TO varmak_admin, varmak_office;

-- issue_stock is deliberately NOT granted here. It takes the name to record against the movement,
-- which means anybody who can call it can sign a movement in somebody else's name. The door is
-- issue_material further down, which takes the name from the session instead.

-- set_password and set_pin are deliberately not granted to anyone but admin. No self-registration,
-- and a PIN reset happens in person — both decided in §3, both true here rather than only written
-- down. A person changing their own password goes through the API, which does it as admin after
-- checking the old one.
REVOKE ALL ON FUNCTION set_password(bigint, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION set_pin(bigint, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION set_password(bigint, text), set_pin(bigint, text) TO varmak_admin;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Row-level security
--
-- Privileges above decide which tables and columns exist for you. Policies here decide which rows.
-- Both are needed: a grant cannot say "your own row", and a policy cannot hide a column.
--
-- Every table gets RLS enabled, including the ones whose policy is simply "signed in". A table
-- with RLS off is a table that is readable by anyone holding the grant, and the list of tables
-- with RLS off is not something anybody will re-check in a year.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

DO $$
DECLARE
  t text;
BEGIN
  FOR t IN SELECT tablename FROM pg_tables WHERE schemaname = 'public'
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    -- Forced, so that the owner is held to the same rules. Otherwise the one role that does all
    -- the migrations is the one role none of this applies to, and it is the role most likely to be
    -- left connected in a console.
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format($p$CREATE POLICY signed_in_can_read ON %I FOR SELECT USING (is_signed_in())$p$, t);
  END LOOP;
END;
$$;

-- Writing is not the same question as reading, so it is answered table by table below.
--
-- First, though, the commercial and store tables, where the answer is the same for all of them: the
-- office runs that side of the business and the floor has no business writing any of it. Written as
-- a loop precisely because the rule is uniform — sixteen hand-copied policies is sixteen chances to
-- leave one out, and leaving one out is invisible. It was: the first version of this file had no
-- write policy on estimate, supplier, purchase_order, lead or eleven others, so the office could not
-- create an estimate or even lock one for update. Nothing caught it, because the tests up to then
-- had asked what the FLOOR could not do and taken the office for granted.
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'estimate', 'estimate_line', 'supplier', 'supplier_item', 'purchase_order',
    'purchase_order_line', 'lead', 'prospect_finding', 'opportunity', 'tender',
    'item_group', 'location', 'offcut', 'barcode', 'document', 'equipment', 'equipment_event',
    'customer_contact', 'supplier_contact'
  ]
  LOOP
    EXECUTE format($p$CREATE POLICY the_office_runs_this ON %I FOR ALL
                      USING (may_see_money()) WITH CHECK (may_see_money())$p$, t);
  END LOOP;
END;
$$;

-- The transition rulebook is reference data. Changing which status may follow which is a decision
-- about how the workshop runs, not a day's work.
CREATE POLICY admin_edits_the_rulebook ON allowed_transition FOR ALL
  USING (is_admin()) WITH CHECK (is_admin());

-- And now the tables where the two roles have different answers.

CREATE POLICY admin_writes_anything ON customer FOR ALL USING (is_admin()) WITH CHECK (is_admin());
CREATE POLICY office_writes_customers ON customer FOR INSERT WITH CHECK (may_see_money());
CREATE POLICY office_edits_customers ON customer FOR UPDATE USING (may_see_money()) WITH CHECK (may_see_money());

CREATE POLICY commercial_writes_projects ON project FOR ALL USING (may_see_money()) WITH CHECK (may_see_money());

-- A jobcard may be moved along by the floor — that is the work — but created and deleted by the
-- office, because a jobcard is a commitment to do something for a customer.
CREATE POLICY commercial_writes_jobcards ON jobcard FOR ALL USING (may_see_money()) WITH CHECK (may_see_money());
CREATE POLICY floor_moves_jobcards ON jobcard FOR UPDATE USING (is_signed_in()) WITH CHECK (is_signed_in());

CREATE POLICY floor_runs_operations ON operation FOR UPDATE USING (is_signed_in()) WITH CHECK (is_signed_in());
CREATE POLICY commercial_writes_operations ON operation FOR ALL USING (may_see_money()) WITH CHECK (may_see_money());

-- Hours: you book your own. Correcting somebody else's timesheet is an office job, and a welder
-- being able to edit another welder's hours is how a time system stops being evidence of anything.
CREATE POLICY book_your_own_hours ON hours_entry FOR INSERT
  WITH CHECK (worker = current_app_name());
CREATE POLICY correct_your_own_hours ON hours_entry FOR UPDATE
  USING (worker = current_app_name() OR may_see_money())
  WITH CHECK (worker = current_app_name() OR may_see_money());
CREATE POLICY office_removes_hours ON hours_entry FOR DELETE USING (may_see_money());

CREATE POLICY anyone_signed_in_moves_stock ON stock_movement FOR INSERT WITH CHECK (is_signed_in());
CREATE POLICY commercial_writes_stock ON stock_item FOR ALL USING (may_see_money()) WITH CHECK (may_see_money());

CREATE POLICY floor_records_equipment_events ON equipment_event FOR INSERT WITH CHECK (is_signed_in());
-- And answers a failed check. Narrow on both ends: the policy allows the floor to touch only a row that
-- is a failed pre-use check, and the column grant above allows it to touch only `resolved` on that row.
-- Together that is one sentence — a welder may mark a failed check answered — and nothing else.
--
-- Needed because the ALL policy above is the office's and asks may_see_money(), so a welder's UPDATE
-- matched no policy and quietly affected nothing: record_equipment_event would insert the check that
-- answers the failure and leave the failure standing, so the machine stayed stopped for a reason
-- somebody had already dealt with. A GRANT with no policy behind it fails closed, which is the safe
-- direction and still the wrong answer.
CREATE POLICY floor_answers_a_failed_check ON equipment_event FOR UPDATE
  USING (is_signed_in() AND kind = 'pre-use-check' AND result = 'fail')
  WITH CHECK (is_signed_in() AND kind = 'pre-use-check' AND result = 'fail');
CREATE POLICY floor_assigns_equipment ON equipment_assignment FOR ALL USING (is_signed_in()) WITH CHECK (is_signed_in());

-- Quality: a welder records what they found. Only the office releases a hold, which is the
-- decision that lets work leave the building.
CREATE POLICY floor_records_inspections ON inspection FOR INSERT WITH CHECK (is_signed_in());
-- And records what they found on one that is still open. The USING clause is read against the row as
-- it stands, so this permits a verdict on an undecided inspection and nothing else: a welder cannot
-- come back a week later and turn a failure into a pass, because by then the row it is matched
-- against no longer says pending.
CREATE POLICY floor_records_a_result ON inspection FOR UPDATE
  USING (is_signed_in() AND result = 'pending') WITH CHECK (is_signed_in());
-- The checklist, while its inspection is still undecided. Tied to the parent rather than to the
-- signed-in person, because an inspection is not owned by whoever happens to write a line on it —
-- what makes a line writable is that nobody has yet signed for the result it is evidence for.
CREATE POLICY floor_writes_the_checklist ON inspection_check FOR INSERT
  WITH CHECK (is_signed_in() AND EXISTS (
    SELECT 1 FROM inspection i WHERE i.id = inspection_id AND i.result = 'pending'));
CREATE POLICY floor_clears_the_checklist ON inspection_check FOR DELETE
  USING (is_signed_in() AND EXISTS (
    SELECT 1 FROM inspection i WHERE i.id = inspection_id AND i.result = 'pending'));
CREATE POLICY commercial_writes_the_checklist ON inspection_check FOR ALL
  USING (may_see_money()) WITH CHECK (may_see_money());
CREATE POLICY commercial_writes_inspections ON inspection FOR ALL USING (may_see_money()) WITH CHECK (may_see_money());
CREATE POLICY only_the_office_holds ON quality_hold FOR ALL USING (may_see_money()) WITH CHECK (may_see_money());
CREATE POLICY commercial_writes_ncrs ON ncr FOR ALL USING (may_see_money()) WITH CHECK (may_see_money());

CREATE POLICY anyone_signed_in_logs ON activity_log FOR INSERT WITH CHECK (is_signed_in());

-- Your own session, and your own row. Reading the whole session table would be a list of who is
-- logged in and on which device, which is nobody's business but an admin's.
CREATE POLICY your_own_session ON app_session FOR ALL
  USING (user_id = current_app_user() OR is_admin())
  WITH CHECK (user_id = current_app_user() OR is_admin());

DROP POLICY signed_in_can_read ON app_user;
CREATE POLICY your_own_row ON app_user FOR SELECT
  USING (id = current_app_user() OR may_see_money());
CREATE POLICY admin_manages_people ON app_user FOR ALL USING (is_admin()) WITH CHECK (is_admin());

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- The four doors that have to work before anybody is signed in
--
-- FORCE ROW LEVEL SECURITY above holds the owner to the same policies as everybody else, which is
-- the point of it — but it also means sign_in cannot write a session row, because at the moment it
-- runs nobody is signed in yet and every policy says no. That is not a flaw in the policies; it is
-- the bootstrap problem every auth system has.
--
-- The answer is one role that may step around row security, owning exactly the functions that have
-- to: signing in, checking a token, signing out, and issuing material. Four functions, listed here,
-- each doing one thing and checking for itself who is asking. Everything else in the system is
-- subject to the policies with no exception, and this list is short enough to read.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'varmak_engine') THEN
    CREATE ROLE varmak_engine NOLOGIN BYPASSRLS;
  END IF;
END;
$$;

-- Same reason as the roles above: set unconditionally, because the role may already exist from an
-- earlier build of a different database in this cluster.
ALTER ROLE varmak_engine NOLOGIN BYPASSRLS;

-- Whoever is installing has to be able to SET ROLE to this one, or every `ALTER FUNCTION ... OWNER TO
-- varmak_engine` below is refused — and those lines are what make the four functions allowed to step
-- around row security belong to a role that may. A superuser can always become any role. A CREATEROLE
-- role, which is the most a managed database gives you, gets ADMIN OPTION on the roles it creates and
-- **not** the right to become one, so the install stopped dead at the first of those ALTERs.
--
-- Two things about the shape of this are the result of finding out the hard way. `pg_has_role(...,
-- 'MEMBER')` answers true on the strength of that admin option alone, so a guard written with it skips
-- the grant that is needed — which is exactly what happened here, and the error message was identical
-- to having no guard at all. And it is a plain GRANT rather than PostgreSQL 16's `WITH SET TRUE`,
-- because the hosted databases this installs onto are still on 15 where that is a parse error; the
-- plain form adds a membership that carries SET on both versions.
DO $$
BEGIN
  IF NOT (SELECT rolsuper FROM pg_roles WHERE rolname = current_user) THEN
    EXECUTE format('GRANT varmak_engine TO %I', current_user);
  END IF;
END;
$$;
-- NOSUPERUSER omitted here for the reason given at the other four: naming the attribute at all needs
-- to be a superuser. This one is checked below instead, where it matters more than the others — this
-- is the role that owns the functions allowed to step around row security.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'varmak_engine' AND rolsuper) THEN
    RAISE EXCEPTION 'varmak_engine is a superuser: it owns the functions that bypass row security, '
      'and as a superuser it would bypass everything else as well';
  END IF;
END;
$$;

GRANT USAGE ON SCHEMA public TO varmak_engine;
-- And on whichever schema pgcrypto is in, for the same reason varmak_api was given it above. This one
-- is not about a search_path: a SECURITY DEFINER function runs as its owner, so the body of sign_in
-- resolves crypt() with this role's privileges, and USAGE on the schema is what lets it.
DO $$
DECLARE
  home text := (SELECT n.nspname FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace
                 WHERE e.extname = 'pgcrypto');
BEGIN
  IF home IS NULL OR home = 'public' THEN
    RETURN;
  END IF;
  -- Attempted, then checked. On a managed database the extension schema often belongs to a role you
  -- are not, so this GRANT can come back as "no privileges were granted" — a WARNING, which an install
  -- scrolls straight past, and then nobody can sign in. Checking turns that into a refusal here, with
  -- the one line somebody has to run. Nothing in this file matters more: crypt() resolves as this role.
  BEGIN
    EXECUTE format('GRANT USAGE ON SCHEMA %I TO varmak_engine', home);
  EXCEPTION WHEN insufficient_privilege THEN
    NULL;
  END;
  IF NOT has_schema_privilege('varmak_engine', home, 'USAGE') THEN
    -- quote_ident and a plain %, because RAISE does not take format()'s %I: written that way, the line
    -- somebody is meant to copy out of this message came out as `GRANT USAGE ON SCHEMA extensionsI`.
    -- A refusal whose instruction does not work is worse than no instruction.
    RAISE EXCEPTION 'varmak_engine cannot use schema %, where pgcrypto lives, so no password in this '
      'system can be hashed or checked. Ask whoever owns that schema to run: GRANT USAGE ON SCHEMA % '
      'TO varmak_engine;', home, quote_ident(home);
  END IF;
END;
$$;
GRANT SELECT, INSERT, UPDATE ON app_user, app_session, stock_item, project TO varmak_engine;
-- And four columns on equipment, for equipment_state_after_event and nothing else: the date a machine
-- was last serviced, inspected or calibrated, and its status when it breaks down. Column by column
-- rather than the table, because this role bypasses row security and the whole point of the function is
-- that it can do exactly two things — a table-wide UPDATE here would make it able to rewrite the
-- register, the certificate expiry and the purchase price of every machine in the shop.
-- SELECT on the three dates as well as the id, because the UPDATE below reads them: each is set to
-- `CASE WHEN ... THEN p_day ELSE last_service_date END`, and reading a column in a SET expression needs
-- SELECT on it. Granted UPDATE and not SELECT, the statement came back as "permission denied for table
-- equipment" with nothing to say which column it meant.
GRANT SELECT (id, status, last_service_date, last_inspection_date, last_calibration_date)
ON equipment TO varmak_engine;
GRANT UPDATE (status, last_service_date, last_inspection_date, last_calibration_date)
ON equipment TO varmak_engine;
-- And the one route by which the floor places a hold: hold_after_failed_inspection reads the
-- inspection it is holding work for and writes the hold. SELECT on inspection and no UPDATE, because
-- that function must not be able to change what was found — only to act on it. INSERT on quality_hold
-- and no UPDATE either: releasing a hold is the office's decision and this role has no part in it.
GRANT SELECT ON inspection TO varmak_engine;
GRANT SELECT, INSERT ON quality_hold TO varmak_engine;
-- Read-only, and only what the roll-up above walks: an hours entry names a jobcard, and the jobcard
-- names the project whose figure is being recomputed.
GRANT SELECT ON jobcard, hours_entry TO varmak_engine;
-- Insert only on the two that are append-only, even for the role that may step around row security.
GRANT SELECT, INSERT ON activity_log, stock_movement TO varmak_engine;
GRANT USAGE ON ALL SEQUENCES IN SCHEMA public TO varmak_engine;

-- CREATE on the schema, for the length of the ownership changes and no longer.
--
-- Postgres requires the incoming owner to hold CREATE on the schema a function lives in. On this
-- machine the install runs as a superuser and the question never comes up; on PostgreSQL 15 and later
-- `public` no longer grants CREATE to everybody, so on a hosted database every ALTER below was refused
-- with "permission denied for schema public" — after the tables, the policies and the grants had all
-- gone in, which is the worst place for an install to stop.
--
-- Granted and then taken away again, in the same transaction, because nothing this role does afterwards
-- creates anything: varmak_engine cannot log in, and the only code that runs as it is the handful of
-- functions listed here. A standing CREATE would be a privilege that serves nobody.
GRANT CREATE ON SCHEMA public TO varmak_engine;

ALTER FUNCTION sign_in(text, text, session_door, text) OWNER TO varmak_engine;
ALTER FUNCTION session_owner(text) OWNER TO varmak_engine;
ALTER FUNCTION sign_out(text) OWNER TO varmak_engine;
ALTER FUNCTION register_failure(bigint) OWNER TO varmak_engine;
ALTER FUNCTION current_app_role() OWNER TO varmak_engine;

-- The project's used hours are recomputed whenever anybody books time, and the person booking it is
-- usually a welder who has no business writing to project at all. The roll-up is the system keeping
-- its own figure straight, not the welder editing a project, so it runs as the engine.
--
-- Narrow on purpose: it recomputes one sum from hours_entry and writes it to one column. A
-- SECURITY DEFINER trigger that did anything broader would be a hole on every write to the table it
-- hangs off.
ALTER FUNCTION project_hours_roll_up() OWNER TO varmak_engine;
ALTER FUNCTION project_hours_roll_up() SECURITY DEFINER;
ALTER FUNCTION current_app_name() OWNER TO varmak_engine;
ALTER FUNCTION set_password(bigint, text) OWNER TO varmak_engine;
ALTER FUNCTION set_pin(bigint, text) OWNER TO varmak_engine;
ALTER FUNCTION set_password(bigint, text) SECURITY DEFINER;
ALTER FUNCTION set_pin(bigint, text) SECURITY DEFINER;

-- ── Material leaves the shelf through one door ────────────────────────────────────────────
--
-- §1b says the workshop may issue material. Doing that changes stock_item, and the obvious way to
-- allow it — granting UPDATE on the quantity columns — would also let a welder set the stock to
-- whatever they liked with no movement written against it. Then the store's figures and the
-- movements that are supposed to explain them drift apart, silently, which is the failure the
-- movement table exists to prevent.
--
-- So the workshop gets no UPDATE on stock_item at all. It gets this function, which is the door.
-- Note what it does NOT take: who is doing it. That comes from the session, so the movement
-- records the person who actually issued the steel rather than whichever name the caller passed.
CREATE FUNCTION issue_material(p_item_id bigint, p_quantity numeric, p_jobcard_id bigint,
                               p_note text DEFAULT NULL)
RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  who text;
BEGIN
  SELECT display_name INTO who FROM app_user WHERE id = current_app_user() AND is_active;
  IF who IS NULL THEN
    RAISE EXCEPTION 'sign in before taking material off the shelf' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN issue_stock(p_item_id, p_quantity, p_jobcard_id, who, p_note);
END;
$$;

ALTER FUNCTION issue_material(bigint, numeric, bigint, text) OWNER TO varmak_engine;
ALTER FUNCTION issue_stock(bigint, numeric, bigint, text, text) OWNER TO varmak_engine;

-- And taken back, as promised above. api.sql grants it again for its own ownership changes and takes
-- it away the same way, so the privilege exists only while it is being used.
REVOKE CREATE ON SCHEMA public FROM varmak_engine;

-- Asked rather than assumed, because the three files each grant this and each take it back, so
-- forgetting it in one of them is invisible: a later file revokes it again and the install ends
-- correct anyway. A mutation that deleted this file's REVOKE went unnoticed by every suite for
-- exactly that reason. The rule is "the privilege exists only while it is being used", and it is
-- auth.sql's own rule, not something to inherit from whatever happens to run next.
DO $$
BEGIN
  IF has_schema_privilege('varmak_engine', 'public', 'CREATE') THEN
    RAISE EXCEPTION 'varmak_engine still holds CREATE on schema public at the end of auth.sql — the grant made for the ownership changes above was not given back';
  END IF;
END $$;
-- Named roles as well as PUBLIC. REVOKE ... FROM PUBLIC does not remove a privilege granted
-- explicitly to a role, and an earlier version of this file granted EXECUTE on issue_stock to all
-- three roles a hundred lines above. The revoke below looked like it closed that and did not: the
-- office kept the privilege, and being the one role that also holds UPDATE on stock_item, it could
-- sign a stock movement in any name it liked. Third time the same shape of mistake appeared in this
-- file — a broad or early GRANT, and a narrower line further down that reads as though it undoes it.
--
-- Naming the roles is defensive rather than load-bearing: with that early GRANT gone, revoking from
-- PUBLIC alone is enough, because EXECUTE is granted to PUBLIC by default and to no role
-- explicitly. It stays because the next person to add a GRANT above this line should find it
-- already closed.
REVOKE ALL ON FUNCTION issue_stock(bigint, numeric, bigint, text, text)
FROM PUBLIC, varmak_admin, varmak_office, varmak_workshop;
REVOKE ALL ON FUNCTION issue_material(bigint, numeric, bigint, text)
FROM PUBLIC, varmak_admin, varmak_office, varmak_workshop;
GRANT EXECUTE ON FUNCTION issue_material(bigint, numeric, bigint, text)
TO varmak_admin, varmak_office, varmak_workshop;

-- ── Two tables where "signed in" is not enough ────────────────────────────────────────────
--
-- The loop above gave every table a permissive "signed in may read" policy, and permissive
-- policies are OR'd together. On these two that would defeat the narrower policy sitting beside
-- it: any signed-in person could read the whole session table — a list of who is logged in, on
-- which device — or every row of app_user.
DROP POLICY signed_in_can_read ON app_session;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- The welding registers: who may read and who may write
--
-- All five tables are granted SELECT to the floor, and that is not a concession — a welder needs to read
-- the procedure they are welding to and the qualification they hold. Nothing in any of them could ever be
-- a price, which is the test §1b sets for this list.
-- ─────────────────────────────────────────────────────────────────────────────────────────────
GRANT SELECT ON wps, welder_qual, weld, weld_repair, ndt_report
TO varmak_admin, varmak_office, varmak_workshop;

-- A welder LOGS THEIR OWN WELD. This is the same rule as booking hours, for the same reason and with more
-- at stake: a weld log filled in by somebody in the office is a document saying what should have happened.
-- The INSERT policy is `welder_id = current_app_user()`, so a weld cannot be entered in another welder's
-- name by anybody — including the office, including an admin. Correcting one afterwards is an office job,
-- like correcting a timesheet.
GRANT INSERT, UPDATE ON weld TO varmak_admin, varmak_office, varmak_workshop;
GRANT INSERT ON weld_repair TO varmak_admin, varmak_office, varmak_workshop;
GRANT INSERT, UPDATE ON ndt_report TO varmak_admin, varmak_office, varmak_workshop;

-- A procedure and a qualification are decisions about who may weld what, not records of what happened.
-- A welder cannot qualify themselves, and the floor holds no write on either.
GRANT INSERT, UPDATE, DELETE ON wps, welder_qual TO varmak_admin, varmak_office;

CREATE POLICY log_your_own_weld ON weld FOR INSERT
  WITH CHECK (welder_id = current_app_user());
CREATE POLICY correct_a_weld ON weld FOR UPDATE
  USING (welder_id = current_app_user() OR may_see_money())
  WITH CHECK (welder_id = current_app_user() OR may_see_money());

-- A repair may be done by somebody other than whoever made the weld, and an NDT report may be signed by a
-- firm outside — so neither is tied to the session's own id. Both record who entered them either way.
CREATE POLICY anyone_signed_in_records_a_repair ON weld_repair FOR INSERT
  WITH CHECK (is_signed_in());
CREATE POLICY anyone_signed_in_records_ndt ON ndt_report FOR INSERT
  WITH CHECK (is_signed_in());
CREATE POLICY ndt_is_corrected_by_whoever_signed_it ON ndt_report FOR UPDATE
  USING (recorded_by = current_app_name() OR may_see_money())
  WITH CHECK (recorded_by = current_app_name() OR may_see_money());

CREATE POLICY the_office_runs_the_procedures ON wps FOR ALL
  USING (may_see_money()) WITH CHECK (may_see_money());
CREATE POLICY the_office_runs_the_qualifications ON welder_qual FOR ALL
  USING (may_see_money()) WITH CHECK (may_see_money());

-- Nobody deletes a weld, a repair or an NDT report. A weld that was made was made, and a register you can
-- delete from is not a register — the same rule as the stock movements and the activity log.
REVOKE DELETE ON weld, weld_repair, ndt_report FROM varmak_admin, varmak_office, varmak_workshop;

-- And nobody edits a repair. It is a row saying a joint was ground out and re-welded on a day, which is
-- either true or it is not; correcting one is not a correction, it is a different past. Revoked explicitly
-- because `GRANT SELECT, INSERT, UPDATE ... ON ALL TABLES` two hundred lines above hands admin and office
-- a write on every table in the schema, including every table added afterwards — so a table that should
-- not be writable has to say so. test-auth.js caught this within a minute of the tables existing: it asks
-- which roles hold a write privilege that no policy permits, and weld_repair had UPDATE with an INSERT
-- policy and nothing else. Fails closed, so it was safe and still wrong, which is the third time that
-- exact sentence has been written in this project.
REVOKE UPDATE ON weld_repair FROM varmak_admin, varmak_office, varmak_workshop;

-- COMMIT; (removed: ending it here would commit a part of the install on its own)

-- ═══════════════════════════════════════════════════════════════════════════════════════════
-- api.sql
-- ═══════════════════════════════════════════════════════════════════════════════════════════

-- Varmak Workshop — the workflows.
--
-- Step 4 of BACKEND.md: the API for the workflows in §4, one at a time. Run after auth.sql.
--
-- §4 divides the system into three layers and says what belongs in each. These are the middle one:
--
--     "workflows that span several tables in one transaction: accepting an estimate and creating
--      its project, receiving goods against a purchase order, issuing material to a jobcard,
--      converting a lead into a customer. Each is several writes that must all succeed or all fail."
--
-- They are written as database functions rather than as code in the HTTP server, for the same
-- reason the safety rules are triggers: a workflow in the server holds until somebody adds a second
-- caller. A function is one transaction by construction, is subject to the same row-level security
-- as everything else, and cannot be gone around. The HTTP layer in server.js carries requests to
-- these and does nothing else — it holds no business logic at all, and there is a test that says so.
--
-- Two of the four were already built where they belonged: issuing material is issue_material() in
-- auth.sql, because it had to be the only door through which stock moves, and per-group item
-- numbering is next_item_number() in schema.sql.

-- BEGIN; (removed: the SQL editor opens the transaction that covers all four files)

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Doing a thing once, even when the tablet sends it twice
--
-- §3 scoped offline to three append-only actions — booking hours, starting or pausing an operation,
-- issuing material — because they happen at the machine and cannot wait for a signal. The tablet
-- queues them with an id it generates itself and replays them when the signal returns.
--
-- Replay is not "did this fail? then send it again": the tablet does not know whether the first
-- attempt reached the server before the connection died. So every one of those calls takes an id,
-- and asking twice with the same id gives the same answer and changes nothing the second time.
-- That is what makes the queue safe to flush blindly.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE device_event (
  id          text PRIMARY KEY CHECK (btrim(id) <> ''),
  kind        text NOT NULL CHECK (btrim(kind) <> ''),
  user_id     bigint NOT NULL REFERENCES app_user(id) ON DELETE RESTRICT,
  received_at timestamptz NOT NULL DEFAULT now(),
  -- What the first attempt produced, handed back verbatim to a replay.
  result      text
);

CREATE INDEX device_event_user_idx ON device_event(user_id, received_at DESC);

ALTER TABLE device_event ENABLE ROW LEVEL SECURITY;
ALTER TABLE device_event FORCE ROW LEVEL SECURITY;
CREATE POLICY your_own_device_events ON device_event FOR ALL
  USING (user_id = current_app_user() OR may_see_money())
  WITH CHECK (user_id = current_app_user());
GRANT SELECT, INSERT, UPDATE ON device_event TO varmak_admin, varmak_office, varmak_workshop;

-- Returns the earlier answer if this id has been seen, or NULL if it is new and has just been
-- claimed. The claim and the check are one statement, so two replays arriving together cannot both
-- decide they are first.
CREATE FUNCTION already_done(p_event_id text, p_kind text) RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  earlier text;
BEGIN
  IF p_event_id IS NULL OR btrim(p_event_id) = '' THEN
    RETURN NULL;
  END IF;
  INSERT INTO device_event (id, kind, user_id)
  VALUES (p_event_id, p_kind, current_app_user())
  ON CONFLICT (id) DO NOTHING;
  IF FOUND THEN
    RETURN NULL;
  END IF;
  SELECT coalesce(result, 'accepted') INTO earlier FROM device_event WHERE id = p_event_id;
  RETURN earlier;
END;
$$;

CREATE FUNCTION record_result(p_event_id text, p_result text) RETURNS void
LANGUAGE sql AS $$
  UPDATE device_event SET result = p_result WHERE id = p_event_id AND result IS NULL;
$$;

-- Asked first, before anything else, in each of the three. already_done() records the event against
-- current_app_user(), so a request with no session used to die on a not-null violation deep inside
-- it — leaving somebody at a tablet that had quietly lost its session reading "null value in column
-- user_id" instead of being told to sign in. The order of two lines, and the whole difference
-- between a message that helps and one that does not.
CREATE FUNCTION require_session(p_doing text) RETURNS text
LANGUAGE plpgsql STABLE AS $$
DECLARE
  who text := current_app_name();
BEGIN
  IF who IS NULL THEN
    RAISE EXCEPTION 'sign in before %', p_doing USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN who;
END;
$$;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- A quotation goes out
--
-- Sending is what locks the lines. Until then a price is just a price; afterwards changing it needs
-- a reason and a name, which the trigger in schema.sql enforces. Nothing set `locked` before this
-- existed, which made that whole rule unreachable.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE FUNCTION send_estimate(p_estimate_id bigint, p_valid_days int DEFAULT 30) RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  est estimate%ROWTYPE;
  lines int;
BEGIN
  SELECT * INTO est FROM estimate WHERE id = p_estimate_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such estimate' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF est.status <> 'draft' THEN
    RAISE EXCEPTION 'estimate % has already been sent (it is %)', est.ref, est.status
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT count(*) INTO lines FROM estimate_line WHERE estimate_id = p_estimate_id;
  IF lines = 0 THEN
    RAISE EXCEPTION 'estimate % has no lines — there is no price to send', est.ref
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE estimate_line SET locked = true WHERE estimate_id = p_estimate_id;
  -- coalesce on the parameter as well as the column: a JSON client that leaves a field out sends
  -- null, and an explicit null overrides a SQL DEFAULT rather than falling back to it. Every
  -- parameter here with a default has to survive being passed null, or the API can only call these
  -- functions by naming every argument every time.
  UPDATE estimate
     SET status = 'sent',
         valid_until = coalesce(valid_until, current_date + coalesce(p_valid_days, 30))
   WHERE id = p_estimate_id;

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('estimate', p_estimate_id, 'sent', coalesce(current_app_name(), 'system'),
          est.ref || ' at ' || (SELECT total FROM estimate WHERE id = p_estimate_id) || ' ' || est.currency);

  RETURN est.ref;
END;
$$;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- The customer says yes
--
-- Several writes that must all succeed or all fail: the estimate becomes accepted, a project comes
-- into being or moves forward, and the hours that were quoted become the hours that were planned.
-- The last one is the point of doing this in one place — a project whose planned hours were never
-- filled in from the estimate is a project every capacity figure downstream is wrong about.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE FUNCTION accept_estimate(p_estimate_id bigint) RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  est estimate%ROWTYPE;
  proj project%ROWTYPE;
  quoted_hours numeric;
BEGIN
  SELECT * INTO est FROM estimate WHERE id = p_estimate_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such estimate' USING ERRCODE = 'foreign_key_violation';
  END IF;
  -- A draft cannot be accepted: nobody outside the building has seen it.
  IF est.status <> 'sent' THEN
    RAISE EXCEPTION 'estimate % cannot be accepted from %', est.ref, est.status
      USING ERRCODE = 'check_violation';
  END IF;
  IF est.valid_until IS NOT NULL AND est.valid_until < current_date THEN
    RAISE EXCEPTION 'estimate % expired on % — requote it rather than accepting it', est.ref, est.valid_until
      USING ERRCODE = 'check_violation';
  END IF;

  -- Labour is quoted in hours, so that is what becomes the plan. Material lines are quantities of
  -- steel and have nothing to say about how long the job takes.
  SELECT coalesce(sum(quantity), 0) INTO quoted_hours
    FROM estimate_line WHERE estimate_id = p_estimate_id AND kind = 'labour';

  IF est.project_id IS NULL THEN
    INSERT INTO project (name, customer_id, status, planned_hours)
    VALUES (est.title, est.customer_id, 'approved', quoted_hours)
    RETURNING * INTO proj;
    UPDATE estimate SET project_id = proj.id WHERE id = p_estimate_id;
  ELSE
    SELECT * INTO proj FROM project WHERE id = est.project_id FOR UPDATE;
    -- Only moved if the sequence allows it. A project already in production does not go back to
    -- approved because a second estimate on it was accepted.
    IF proj.status = 'quotation' THEN
      UPDATE project SET status = 'approved' WHERE id = proj.id;
    END IF;
    UPDATE project SET planned_hours = planned_hours + quoted_hours WHERE id = proj.id;
  END IF;

  UPDATE estimate SET status = 'accepted' WHERE id = p_estimate_id;

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('estimate', p_estimate_id, 'accepted', coalesce(current_app_name(), 'system'),
          est.ref || ' → project ' || (SELECT ref FROM project WHERE id = proj.id)
          || ', ' || trim_scale(quoted_hours) || ' h planned');

  RETURN (SELECT ref FROM project WHERE id = proj.id);
END;
$$;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Steel arrives
--
-- Four writes in one transaction: the line records what came, the item's stock goes up, a movement
-- explains why it went up, and the order's own status follows from its lines. Doing any of those
-- without the others leaves the store unable to explain itself.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE FUNCTION receive_goods(p_line_id bigint, p_quantity numeric, p_note text DEFAULT NULL)
RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  line purchase_order_line%ROWTYPE;
  order_row purchase_order%ROWTYPE;
  who text := coalesce(current_app_name(), 'system');
  outstanding numeric;
  movement_ref text;
BEGIN
  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    RAISE EXCEPTION 'a receipt must be for more than nothing' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO line FROM purchase_order_line WHERE id = p_line_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such order line' USING ERRCODE = 'foreign_key_violation';
  END IF;
  SELECT * INTO order_row FROM purchase_order WHERE id = line.purchase_order_id FOR UPDATE;

  IF order_row.status = 'cancelled' THEN
    RAISE EXCEPTION 'order % was cancelled — receiving against it needs it reopened first', order_row.ref
      USING ERRCODE = 'check_violation';
  END IF;

  -- Named before the constraint fires, so the storeman is told how much is actually outstanding
  -- rather than which CHECK they broke.
  outstanding := line.quantity - line.received_quantity;
  IF p_quantity > outstanding THEN
    RAISE EXCEPTION 'order % has only % of % outstanding on "%" — % is more than was ordered',
      order_row.ref, trim_scale(outstanding), trim_scale(line.quantity), line.description,
      trim_scale(p_quantity)
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE purchase_order_line SET received_quantity = received_quantity + p_quantity
   WHERE id = p_line_id;

  -- A line can be for something that is not a stock item — a service, a carriage charge — and then
  -- there is nothing to put on a shelf.
  IF line.stock_item_id IS NOT NULL THEN
    UPDATE stock_item SET stock = stock + p_quantity WHERE id = line.stock_item_id;
    INSERT INTO stock_movement (stock_item_id, kind, quantity, jobcard_id, moved_by, note)
    VALUES (line.stock_item_id, 'receipt', p_quantity, NULL, who,
            coalesce(p_note, 'Received against ' || order_row.ref))
    RETURNING ref INTO movement_ref;
  END IF;

  -- The order's status is a statement about its lines, so it is derived from them rather than set
  -- by whoever happened to be on the receiving bay.
  UPDATE purchase_order SET status = (CASE
      WHEN NOT EXISTS (SELECT 1 FROM purchase_order_line
                        WHERE purchase_order_id = order_row.id AND received_quantity < quantity)
        THEN 'received'
      ELSE 'part-received'
    END)::purchase_order_status
   WHERE id = order_row.id;

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('purchase_order', order_row.id, 'received', who,
          trim_scale(p_quantity) || ' of "' || line.description || '" on ' || order_row.ref);

  RETURN coalesce(movement_ref, order_row.ref);
END;
$$;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- An enquiry becomes somebody we work for
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE FUNCTION convert_lead(p_lead_id bigint, p_org_no text DEFAULT NULL, p_vat_no text DEFAULT NULL)
RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  the_lead lead%ROWTYPE;
  made customer%ROWTYPE;
BEGIN
  SELECT * INTO the_lead FROM lead WHERE id = p_lead_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such lead' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF the_lead.status = 'converted' THEN
    RAISE EXCEPTION 'lead % is already customer %', the_lead.ref,
      (SELECT ref FROM customer WHERE id = the_lead.customer_id) USING ERRCODE = 'check_violation';
  END IF;
  IF the_lead.status = 'lost' THEN
    RAISE EXCEPTION 'lead % was marked lost', the_lead.ref USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO customer (name, org_no, vat_no, email, phone, city, status)
  VALUES (the_lead.company, p_org_no, p_vat_no, the_lead.email, the_lead.phone, the_lead.city, 'active')
  RETURNING * INTO made;

  UPDATE lead SET status = 'converted', customer_id = made.id WHERE id = p_lead_id;

  -- Anything already quoted to the lead now belongs to the customer, or the history of where the
  -- work came from stops joining up the moment they become real.
  UPDATE opportunity SET customer_id = made.id WHERE lead_id = p_lead_id AND customer_id IS NULL;

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('lead', p_lead_id, 'converted', coalesce(current_app_name(), 'system'),
          the_lead.ref || ' → ' || made.ref || ' (' || made.name || ')');

  RETURN made.ref;
END;
$$;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- The three things the tablet may do with no signal
--
-- Each takes an event id from the device. Replaying gives the same answer and changes nothing.
--
-- And the gates still hold on replay. An operation queued offline against a machine that turned out
-- to be out of service is refused when it reaches the server, and the person is told. Offline delays
-- the check; it does not skip it. This is exactly why the rules are in the database — the tablet
-- cannot be the thing that decides.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE FUNCTION book_hours(p_jobcard_id bigint, p_operation_id bigint, p_hours numeric,
                           p_worked_on date DEFAULT current_date, p_note text DEFAULT NULL,
                           p_event_id text DEFAULT NULL)
RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('booking hours');
  seen text := already_done(p_event_id, 'book_hours');
  entry_id bigint;
BEGIN
  IF seen IS NOT NULL THEN
    RETURN seen;
  END IF;

  -- The worker is the session, never a parameter. An hours entry somebody else's name can be put
  -- on is not a timesheet.
  -- Same as above: null means "not given", so today.
  INSERT INTO hours_entry (jobcard_id, operation_id, worker, hours, worked_on, note)
  VALUES (p_jobcard_id, p_operation_id, who, p_hours, coalesce(p_worked_on, current_date), p_note)
  RETURNING id INTO entry_id;

  PERFORM record_result(p_event_id, 'H-' || entry_id);
  RETURN 'H-' || entry_id;
END;
$$;

CREATE FUNCTION record_operation(p_operation_id bigint, p_status operation_status,
                                 p_event_id text DEFAULT NULL)
RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('starting work');
  seen text := already_done(p_event_id, 'record_operation');
  op operation%ROWTYPE;
BEGIN
  IF seen IS NOT NULL THEN
    RETURN seen;
  END IF;

  -- The equipment gate and the dependency gate are triggers on this UPDATE, so a start queued
  -- offline against a machine that has since gone out of service is refused here, on replay.
  UPDATE operation SET status = p_status,
         actual_completion = CASE WHEN p_status = 'completed' THEN current_date ELSE actual_completion END
   WHERE id = p_operation_id
  RETURNING * INTO op;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such operation, or it is not yours to change'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('operation', p_operation_id, p_status::text, who, op.description);

  PERFORM record_result(p_event_id, p_status::text);
  RETURN p_status::text;
END;
$$;

-- Issuing material is issue_material() in auth.sql, because it had to be the only door stock moves
-- through. This wraps it with the same replay protection as the other two.
CREATE FUNCTION issue_material_offline(p_item_id bigint, p_quantity numeric, p_jobcard_id bigint,
                                       p_note text DEFAULT NULL, p_event_id text DEFAULT NULL)
RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('taking material off the shelf');
  seen text := already_done(p_event_id, 'issue_material');
  movement bigint;
BEGIN
  IF seen IS NOT NULL THEN
    RETURN seen;
  END IF;
  movement := issue_material(p_item_id, p_quantity, p_jobcard_id, p_note);
  PERFORM record_result(p_event_id, (SELECT ref FROM stock_movement WHERE id = movement));
  RETURN (SELECT ref FROM stock_movement WHERE id = movement);
END;
$$;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- People
--
-- Until this existed, adding somebody to the system meant opening psql. A workshop cannot start
-- using a thing it has no way to give anybody access to, so these are the workflows behind an admin
-- screen: make a person, give them a way in, take it away again.
--
-- The awkward one is the first admin. There is no admin to create them, and every rule below is
-- written for a system that already has one. The answer is a function that works exactly once and
-- refuses forever after — not a default password, not a hardcoded account, not a flag somebody has
-- to remember to turn off. It checks whether the table is empty, which is a condition that becomes
-- false the moment it succeeds and cannot become true again without deleting everybody.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE FUNCTION bootstrap_first_admin(p_email text, p_display_name text, p_password text)
RETURNS text
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  made bigint;
BEGIN
  IF EXISTS (SELECT 1 FROM app_user) THEN
    -- Not insufficient_privilege, and the difference is not pedantry. server.js replaces the text of
    -- every 42501 with "that is not yours to do", because Postgres writes its own privilege errors
    -- as "permission denied for table stock_item" and that names the inside of the database to
    -- whoever asked. This refusal is not about who is asking — nobody is signed in, and nobody can
    -- be — it is about the state the system is in, and it was written to be read. Raised as 42501 it
    -- reached the first-run screen as "that is not yours to do", which is both wrong and useless to
    -- the person standing in front of it. A plain RAISE carries its own words through.
    RAISE EXCEPTION 'this system already has people in it — an admin adds the next one';
  END IF;
  INSERT INTO app_user (email, display_name, role)
  VALUES (lower(btrim(p_email)), btrim(p_display_name), 'admin')
  RETURNING id INTO made;
  PERFORM set_password(made, p_password);
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('app_user', made, 'first admin created', lower(btrim(p_email)), 'system had no people in it');
  RETURN lower(btrim(p_email));
END;
$$;

CREATE FUNCTION add_person(p_email text, p_display_name text, p_role user_role)
RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  made bigint;
BEGIN
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'only an admin adds people' USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- No secret here on purpose. A person is created with no way in at all, and an admin then gives
  -- them one — which means there is never a moment where an account exists with a password somebody
  -- chose for them and never changed.
  INSERT INTO app_user (email, display_name, role)
  VALUES (lower(btrim(p_email)), btrim(p_display_name), p_role)
  RETURNING id INTO made;
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('app_user', made, 'created', current_app_name(), p_role::text || ' ' || lower(btrim(p_email)));
  RETURN made;
END;
$$;

CREATE FUNCTION set_person_pin(p_user_id bigint, p_pin text) RETURNS void
LANGUAGE plpgsql AS $$
BEGIN
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'a PIN is set by an admin, in person' USING ERRCODE = 'insufficient_privilege';
  END IF;
  PERFORM set_pin(p_user_id, p_pin);
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('app_user', p_user_id, 'PIN set', current_app_name(), 'by an admin');
END;
$$;

CREATE FUNCTION set_person_password(p_user_id bigint, p_password text) RETURNS void
LANGUAGE plpgsql AS $$
BEGIN
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'only an admin resets somebody else''s password' USING ERRCODE = 'insufficient_privilege';
  END IF;
  PERFORM set_password(p_user_id, p_password);
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('app_user', p_user_id, 'password reset', current_app_name(), 'by an admin');
END;
$$;

-- Your own password, and you have to prove you know the current one. Without that, anybody who
-- walks past an unlocked tablet owns the account from then on.
CREATE FUNCTION change_my_password(p_current text, p_new text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  me bigint := current_app_user();
  stored text;
BEGIN
  IF me IS NULL THEN
    RAISE EXCEPTION 'sign in first' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT password_hash INTO stored FROM app_user WHERE id = me;
  IF stored IS NULL OR crypt(p_current, stored) <> stored THEN
    PERFORM pg_sleep(0.1);
    -- Raised plainly, which makes it P0001, which is what server.js carries through with its words
    -- intact. It was invalid_password (28P01) — a code the server does not recognise as a refusal at
    -- all, so the one refusal in this whole flow that an ordinary person meets weekly came back as
    -- "something went wrong at our end". That sends somebody looking for a server fault that is not
    -- there, and leaves the person who mistyped their password with no idea what to do next.
    RAISE EXCEPTION 'that is not your current password';
  END IF;
  PERFORM set_password(me, p_new);
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('app_user', me, 'password changed', current_app_name(), 'by themselves');
END;
$$;

CREATE FUNCTION set_person_active(p_user_id bigint, p_active boolean) RETURNS void
LANGUAGE plpgsql AS $$
BEGIN
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'only an admin switches somebody off' USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- The invariant this protects is "the system always has at least one active admin", and locking
  -- everybody out is easy to do by accident on a Friday afternoon and not recoverable without a
  -- database console.
  --
  -- One line does it, which took writing the second to notice. A "that is the last admin" check
  -- beside this one is unreachable: only an admin gets here, an admin is active, and if they are not
  -- the person being switched off then another active admin exists by definition. The only path to
  -- zero is switching yourself off, and that is what this refuses. A second check that can never
  -- fire is worse than none, because the next person to read it assumes it is doing something.
  IF NOT p_active AND p_user_id = current_app_user() THEN
    RAISE EXCEPTION 'you cannot switch yourself off' USING ERRCODE = 'check_violation';
  END IF;
  UPDATE app_user SET is_active = p_active WHERE id = p_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such person' USING ERRCODE = 'foreign_key_violation';
  END IF;
  -- Switching somebody off ends the sessions they are holding, not just the next one they try to
  -- start. A tablet already signed in as them is the thing being taken away.
  IF NOT p_active THEN
    UPDATE app_session SET ended_at = now() WHERE user_id = p_user_id AND ended_at IS NULL;
  END IF;
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('app_user', p_user_id, CASE WHEN p_active THEN 'switched on' ELSE 'switched off' END,
          current_app_name(), 'by an admin');
END;
$$;

CREATE FUNCTION set_person_role(p_user_id bigint, p_role user_role) RETURNS void
LANGUAGE plpgsql AS $$
BEGIN
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'only an admin changes what somebody may do' USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- Same invariant, same single line, and the same reason the obvious second check is not here.
  IF p_user_id = current_app_user() AND p_role <> 'admin' THEN
    RAISE EXCEPTION 'you cannot take away your own admin' USING ERRCODE = 'check_violation';
  END IF;
  UPDATE app_user SET role = p_role WHERE id = p_user_id;
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('app_user', p_user_id, 'role changed', current_app_name(), p_role::text);
END;
$$;

-- The staff list for the admin screen. No hashes — those are not readable by anybody, which is
-- checked in test-auth.js — and the row-level policy already narrows this to what the caller may
-- see, so a welder calling it gets their own row and nothing else.
CREATE FUNCTION people() RETURNS jsonb
LANGUAGE sql STABLE AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'id', u.id::text, 'email', u.email, 'name', u.display_name, 'role', u.role,
    'active', u.is_active, 'pinSet', u.pin_set_at IS NOT NULL,
    'passwordSet', u.password_set_at IS NOT NULL,
    -- Which of these rows is the caller. The screen needs it to know what it is allowed to offer:
    -- an admin who could switch themselves off, or demote themselves, would be locking the building
    -- from the inside. The database refuses both anyway — this is so the button is never there to
    -- press, which is a different thing from a refusal and both are wanted.
    'isMe', u.id = current_app_user(),
    'lockedUntil', u.locked_until, 'failedAttempts', u.failed_attempts,
    'lastSeen', u.last_seen_at, 'created', u.created_at
  ) ORDER BY u.display_name), '[]'::jsonb) FROM app_user u;
$$;

-- The same grant-and-revoke as auth.sql does around its ownership changes, and for the same reason:
-- Postgres requires the incoming owner to hold CREATE on the schema, and on PostgreSQL 15 and later
-- `public` does not grant that to everybody. See the long note there.
GRANT CREATE ON SCHEMA public TO varmak_engine;

ALTER FUNCTION bootstrap_first_admin(text, text, text) OWNER TO varmak_engine;
ALTER FUNCTION change_my_password(text, text) OWNER TO varmak_engine;

REVOKE ALL ON FUNCTION bootstrap_first_admin(text, text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION add_person(text, text, user_role) FROM PUBLIC;
REVOKE ALL ON FUNCTION set_person_pin(bigint, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION set_person_password(bigint, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION change_my_password(text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION set_person_active(bigint, boolean) FROM PUBLIC;
REVOKE ALL ON FUNCTION set_person_role(bigint, user_role) FROM PUBLIC;
REVOKE ALL ON FUNCTION people() FROM PUBLIC;

-- The bootstrap is callable without a session, because there is nobody to sign in as yet. It is the
-- only function in the system like that, and it refuses the moment the table has anybody in it.
-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- The document register
--
-- The last screen to be wired, and it had been waiting on file storage — which turned out to be the wrong
-- thing to wait for. The part of a document register that matters is not the bytes: it is knowing that the
-- material certificate for heat H240516 expires on the 12th, that revision B of the duct drawing supersedes
-- revision A, and that the welding procedure filed against this job is the one the weld was actually made
-- to. All of that is metadata, and none of it needs the scan to exist. So the register is wired now and the
-- file half of each row stays empty until there is somewhere to put a file.
--
-- The screen speaks of a "module" — Projects, Purchasing, Quality — where the database has tables. One
-- word covers three tables in the case of Quality, and 'Purchasing' is not the name of anything. The
-- resolver below is the whole of that translation, in one place, and it looks the reference up rather than
-- trusting it: a document filed against a project number nobody has ever used is a document that will not
-- be found by the person who needs it, and the refusal says which reference it could not find.
CREATE FUNCTION document_link_for(p_module text, p_record text,
                                  OUT entity text, OUT entity_id bigint)
LANGUAGE plpgsql STABLE AS $$
DECLARE
  said text := nullif(btrim(coalesce(p_record, '')), '');
  word text := lower(btrim(coalesce(p_module, '')));
BEGIN
  IF said IS NULL OR word IN ('', 'unlinked', 'general') THEN
    RETURN;
  END IF;

  -- One module, one or more tables, tried in order. Quality is three: the screen's Quality section lists
  -- non-conformances, inspections and holds together, and a certificate is filed against whichever of them
  -- raised the question. Store is the one table whose human reference is not called `ref`.
  CASE word
    WHEN 'projects'    THEN SELECT 'project',        p.id INTO entity, entity_id FROM project p WHERE p.ref = said;
    WHEN 'workshop'    THEN SELECT 'jobcard',        j.id INTO entity, entity_id FROM jobcard j WHERE j.ref = said;
    WHEN 'purchasing'  THEN SELECT 'purchase_order', o.id INTO entity, entity_id FROM purchase_order o WHERE o.ref = said;
    WHEN 'estimations' THEN SELECT 'estimate',       e.id INTO entity, entity_id FROM estimate e WHERE e.ref = said;
    WHEN 'store'       THEN SELECT 'stock_item',     i.id INTO entity, entity_id FROM stock_item i WHERE i.code = said;
    WHEN 'suppliers'   THEN
      SELECT 'supplier', x.id INTO entity, entity_id FROM supplier x WHERE x.ref = said OR x.name = said;
    WHEN 'customers'   THEN
      SELECT 'customer', c.id INTO entity, entity_id FROM customer c WHERE c.ref = said OR c.name = said;
    WHEN 'quality'     THEN
      SELECT 'ncr', n.id INTO entity, entity_id FROM ncr n WHERE n.ref = said;
      IF entity_id IS NULL THEN
        SELECT 'inspection', i.id INTO entity, entity_id FROM inspection i WHERE i.ref = said;
      END IF;
      IF entity_id IS NULL THEN
        SELECT 'quality_hold', h.id INTO entity, entity_id FROM quality_hold h WHERE h.ref = said;
      END IF;
    ELSE
      RAISE EXCEPTION 'there is no module called %', p_module USING ERRCODE = 'check_violation';
  END CASE;

  IF entity_id IS NULL THEN
    RAISE EXCEPTION 'nothing in % is called %', p_module, said USING ERRCODE = 'foreign_key_violation';
  END IF;
END;
$$;

-- A document in the register, created or corrected. The file half is not a parameter at all: there is
-- nowhere to put a file, and a function that accepted a storage key would be a function that could be
-- handed one pointing at nothing.
CREATE FUNCTION save_document(
  p_id bigint,
  p_title text,
  p_kind text DEFAULT 'Document',
  p_module text DEFAULT NULL,
  p_record text DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_status document_status DEFAULT 'draft',
  p_expires_on date DEFAULT NULL,
  p_revision text DEFAULT NULL,
  p_author text DEFAULT NULL,
  p_notes text DEFAULT NULL
) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('filing a document');
  named text := nullif(btrim(coalesce(p_title, '')), '');
  link record;
  saved bigint;
BEGIN
  IF named IS NULL THEN
    RAISE EXCEPTION 'a document needs a name somebody can find it by' USING ERRCODE = 'check_violation';
  END IF;
  -- Refuses out loud when the reference names nothing, which is the point of resolving it here.
  SELECT * INTO link FROM document_link_for(p_module, p_record);

  IF p_id IS NULL THEN
    INSERT INTO document (title, kind, category, revision, status, expires_on,
                          entity, entity_id, author, notes, uploaded_by)
    VALUES (named, coalesce(nullif(btrim(coalesce(p_kind,'')), ''), 'Document'),
            nullif(btrim(coalesce(p_category,'')), ''), nullif(btrim(coalesce(p_revision,'')), ''),
            coalesce(p_status, 'draft'), p_expires_on, link.entity, link.entity_id,
            -- The author is whoever filed it unless somebody says otherwise: a drawing can be somebody
            -- else's work. The session's name is the default rather than the answer, and `uploaded_by`
            -- below is the session either way, so who put it in the register is never in doubt.
            coalesce(nullif(btrim(coalesce(p_author,'')), ''), who),
            nullif(btrim(coalesce(p_notes,'')), ''), who)
    RETURNING id INTO saved;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    VALUES ('document', saved, 'filed', who, named);
  ELSE
    UPDATE document SET
      title = named,
      kind = coalesce(nullif(btrim(coalesce(p_kind,'')), ''), kind),
      category = nullif(btrim(coalesce(p_category,'')), ''),
      revision = nullif(btrim(coalesce(p_revision,'')), ''),
      status = coalesce(p_status, status),
      expires_on = p_expires_on,
      entity = link.entity, entity_id = link.entity_id,
      author = coalesce(nullif(btrim(coalesce(p_author,'')), ''), author),
      notes = nullif(btrim(coalesce(p_notes,'')), ''),
      updated_at = now()
     WHERE id = p_id
    RETURNING id INTO saved;
    IF saved IS NULL THEN
      RAISE EXCEPTION 'no such document' USING ERRCODE = 'foreign_key_violation';
    END IF;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    VALUES ('document', saved, 'corrected', who, named);
  END IF;
  RETURN saved;
END;
$$;

-- Linking a document to a record, or taking the link off. Its own function because the screen has its own
-- action for it: a document is often filed before anybody knows which job it belongs to, and correcting
-- that later should not mean re-typing the expiry date and the revision.
CREATE FUNCTION link_document(p_id bigint, p_module text, p_record text) RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('linking a document to a record');
  link record;
  named text;
BEGIN
  SELECT * INTO link FROM document_link_for(p_module, p_record);
  UPDATE document SET entity = link.entity, entity_id = link.entity_id, updated_at = now()
   WHERE id = p_id
  RETURNING title INTO named;
  IF named IS NULL THEN
    RAISE EXCEPTION 'no such document' USING ERRCODE = 'foreign_key_violation';
  END IF;
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('document', p_id, 'linked', who,
          coalesce(link.entity || ' ' || coalesce(p_record, ''), 'unlinked'));
  RETURN coalesce(link.entity, 'unlinked');
END;
$$;

-- Superseding a document, which is how a register stops being a pile. Revision B arrives and revision A
-- does not become wrong — it becomes the one that was true before. Deleting it would be losing the reason
-- the weld was made the way it was.
CREATE FUNCTION supersede_document(p_id bigint, p_by_id bigint DEFAULT NULL) RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('superseding a document');
  old record;
BEGIN
  SELECT id, title, revision, status INTO old FROM document WHERE id = p_id;
  IF old.id IS NULL THEN
    RAISE EXCEPTION 'no such document' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF old.status = 'superseded' THEN
    RAISE EXCEPTION '% is already superseded', old.title USING ERRCODE = 'check_violation';
  END IF;
  IF p_by_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM document WHERE id = p_by_id) THEN
    RAISE EXCEPTION 'no such replacement document' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF p_by_id = p_id THEN
    RAISE EXCEPTION 'a document cannot supersede itself' USING ERRCODE = 'check_violation';
  END IF;
  UPDATE document SET status = 'superseded', updated_at = now() WHERE id = p_id;
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('document', p_id, 'superseded', who,
          CASE WHEN p_by_id IS NULL THEN old.title
               ELSE old.title || ' by ' || (SELECT ref FROM document WHERE id = p_by_id) END);
  RETURN old.title;
END;
$$;

-- A note against a document, in the same log every other record's history comes from.
CREATE FUNCTION add_document_note(p_id bigint, p_text text) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('adding a note to a document');
  said text := nullif(btrim(coalesce(p_text, '')), '');
  made bigint;
BEGIN
  IF said IS NULL THEN
    RAISE EXCEPTION 'an empty note is not a note' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM document WHERE id = p_id) THEN
    RAISE EXCEPTION 'no such document' USING ERRCODE = 'foreign_key_violation';
  END IF;
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('document', p_id, 'note', who, said)
  RETURNING id INTO made;
  RETURN made;
END;
$$;

-- Taken away from everybody first, like every other function in this file, then given back below to the
-- roles that have business with it. The resolver goes to the office too: save_document and link_document
-- run in the caller's own role, so a caller who cannot execute the resolver cannot file anything.
REVOKE ALL ON FUNCTION document_link_for(text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION save_document(bigint, text, text, text, text, text, document_status,
                                     date, text, text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION link_document(bigint, text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION supersede_document(bigint, bigint) FROM PUBLIC;
REVOKE ALL ON FUNCTION add_document_note(bigint, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION document_link_for(text, text) TO varmak_admin, varmak_office;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- The welding registers
--
-- Who may do what here is not a guess. A weld is RECORDED BY THE WELDER: the person at the bench is the
-- only one who knows what they did, and a weld log filled in afterwards by somebody in the office is a
-- document that says what should have happened. So record_weld is granted to the floor and takes the
-- welder from the session — it cannot be handed a name at all, which is the same rule book_hours and
-- record_equipment_event already follow.
--
-- A procedure and a qualification are the other way round. Those are decisions about who may weld what,
-- not records of what happened, so save_wps, approve_wps and save_welder_qual are the office's. A welder
-- cannot qualify themselves.
--
-- NDT sits between: the technician may be somebody here or a firm outside, so the function is granted to
-- both and records which.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

-- The weld, recorded by whoever made it.
--
-- `p_welder_qual_id` is optional and the trigger in schema.sql decides whether what it names is any good.
-- Left out, the function finds the welder's own valid qualification for that process — because asking a
-- welder to type the number of the certificate in their own folder is how a weld log gets left blank.
CREATE FUNCTION record_weld(
  p_jobcard_id bigint,
  p_process text,
  p_component text DEFAULT NULL,
  p_wps_id bigint DEFAULT NULL,
  p_welder_qual_id bigint DEFAULT NULL,
  p_welded_on date DEFAULT NULL,
  p_operation_id bigint DEFAULT NULL,
  p_drawing_no text DEFAULT NULL,
  p_weld_map_position text DEFAULT NULL,
  p_joint_type text DEFAULT NULL,
  p_base_material text DEFAULT NULL,
  p_material_grade text DEFAULT NULL,
  p_thickness numeric DEFAULT NULL,
  p_filler_material text DEFAULT NULL,
  p_consumable_batch text DEFAULT NULL,
  p_shielding_gas text DEFAULT NULL,
  p_preheat_required boolean DEFAULT false,
  p_interpass_temp_req text DEFAULT NULL,
  p_visual_required boolean DEFAULT true,
  p_ndt_required boolean DEFAULT false,
  p_ndt_method text DEFAULT NULL,
  p_notes text DEFAULT NULL
) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('recording a weld');
  me bigint := current_app_user();
  made_on date := coalesce(p_welded_on, current_date);
  cited bigint := p_welder_qual_id;
  made bigint;
  said text := nullif(btrim(coalesce(p_process, '')), '');
BEGIN
  IF said IS NULL THEN
    RAISE EXCEPTION 'a weld says which process it was made by' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM jobcard WHERE id = p_jobcard_id) THEN
    RAISE EXCEPTION 'no such jobcard' USING ERRCODE = 'foreign_key_violation';
  END IF;

  -- The welder's own qualification for this process, valid on the day, if they did not name one. Their own
  -- and nobody else's: `welder_id = me`, so this cannot reach across to somebody else's certificate.
  IF cited IS NULL THEN
    SELECT wq.id INTO cited FROM welder_qual wq
     WHERE wq.welder_id = me
       AND lower(btrim(wq.process)) = lower(btrim(said))
       AND wq.status = 'valid'
       AND wq.expires_on >= made_on
     ORDER BY wq.expires_on DESC
     LIMIT 1;
    -- Nothing found is not an error here. The trigger refuses a BAD qualification; a weld with none cited
    -- is a weld nobody has claimed a certificate for, which is a gap an auditor can see rather than a lie.
  END IF;

  INSERT INTO weld (jobcard_id, project_id, operation_id, component, drawing_no, weld_map_position,
                    joint_type, base_material, material_grade, thickness, process, wps_id, welder_id,
                    welder_qual_id, filler_material, consumable_batch, shielding_gas, preheat_required,
                    interpass_temp_req, welded_on, visual_required, ndt_required, ndt_method, notes,
                    recorded_by)
  SELECT p_jobcard_id, j.project_id, p_operation_id, nullif(btrim(coalesce(p_component,'')), ''),
         nullif(btrim(coalesce(p_drawing_no,'')), ''), nullif(btrim(coalesce(p_weld_map_position,'')), ''),
         nullif(btrim(coalesce(p_joint_type,'')), ''), nullif(btrim(coalesce(p_base_material,'')), ''),
         nullif(btrim(coalesce(p_material_grade,'')), ''), p_thickness, said, p_wps_id, me,
         cited, nullif(btrim(coalesce(p_filler_material,'')), ''),
         nullif(btrim(coalesce(p_consumable_batch,'')), ''), nullif(btrim(coalesce(p_shielding_gas,'')), ''),
         coalesce(p_preheat_required, false), nullif(btrim(coalesce(p_interpass_temp_req,'')), ''),
         made_on, coalesce(p_visual_required, true), coalesce(p_ndt_required, false),
         nullif(btrim(coalesce(p_ndt_method,'')), ''), nullif(btrim(coalesce(p_notes,'')), ''), who
    FROM jobcard j WHERE j.id = p_jobcard_id
  RETURNING id INTO made;

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('weld', made, 'welded', who,
          said || coalesce(' to ' || (SELECT ref FROM wps WHERE id = p_wps_id), ''));
  RETURN made;
END;
$$;

-- A repair against a weld. Its own function rather than an UPDATE, because a repair is a row: a weld that
-- was repaired is not a weld that was always right, and which is which is the question asked when a joint
-- fails in service.
CREATE FUNCTION record_weld_repair(p_weld_id bigint, p_reason text, p_notes text DEFAULT NULL)
RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('recording a weld repair');
  why text := nullif(btrim(coalesce(p_reason, '')), '');
  made bigint;
BEGIN
  IF why IS NULL THEN
    RAISE EXCEPTION 'a repair says why it was needed' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM weld WHERE id = p_weld_id) THEN
    RAISE EXCEPTION 'no such weld' USING ERRCODE = 'foreign_key_violation';
  END IF;
  INSERT INTO weld_repair (weld_id, reason, repaired_by, notes)
  VALUES (p_weld_id, why, who, nullif(btrim(coalesce(p_notes,'')), ''))
  RETURNING id INTO made;
  UPDATE weld SET status = 'repaired', updated_at = now() WHERE id = p_weld_id;
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('weld', p_weld_id, 'repaired', who, why);
  RETURN made;
END;
$$;

-- The NDT report. The trigger in schema.sql carries a rejection back to the weld, so this function does
-- not have to remember to — which is the point of putting it there: a second route into ndt_report, an
-- import or a console, cannot forget.
CREATE FUNCTION record_ndt(
  p_weld_id bigint,
  p_method text,
  p_result ndt_result DEFAULT 'pending',
  p_findings text DEFAULT NULL,
  p_procedure_ref text DEFAULT NULL,
  p_inspection_percent numeric DEFAULT NULL,
  p_inspection_area text DEFAULT NULL,
  p_external_company text DEFAULT NULL,
  p_technician_cert_ref text DEFAULT NULL,
  p_inspected_on date DEFAULT NULL,
  p_acceptance_criteria text DEFAULT NULL,
  p_repair_required boolean DEFAULT false,
  p_reinspection_required boolean DEFAULT false,
  p_notes text DEFAULT NULL
) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('recording an NDT result');
  outside text := nullif(btrim(coalesce(p_external_company, '')), '');
  made bigint;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM weld WHERE id = p_weld_id) THEN
    RAISE EXCEPTION 'no such weld' USING ERRCODE = 'foreign_key_violation';
  END IF;
  INSERT INTO ndt_report (weld_id, drawing_no, method, procedure_ref, inspection_percent, inspection_area,
                          -- The technician is the session unless the work was done outside, in which case
                          -- the firm is named and the session is still who entered it, below.
                          technician, external_company, technician_cert_ref, inspected_on,
                          acceptance_criteria, result, findings, repair_required, reinspection_required,
                          notes, recorded_by)
  SELECT p_weld_id, w.drawing_no, nullif(btrim(coalesce(p_method,'')), ''),
         nullif(btrim(coalesce(p_procedure_ref,'')), ''), p_inspection_percent,
         nullif(btrim(coalesce(p_inspection_area,'')), ''),
         CASE WHEN outside IS NULL THEN who ELSE NULL END, outside,
         nullif(btrim(coalesce(p_technician_cert_ref,'')), ''), coalesce(p_inspected_on, current_date),
         nullif(btrim(coalesce(p_acceptance_criteria,'')), ''), coalesce(p_result, 'pending'),
         nullif(btrim(coalesce(p_findings,'')), ''), coalesce(p_repair_required, false),
         coalesce(p_reinspection_required, false), nullif(btrim(coalesce(p_notes,'')), ''), who
    FROM weld w WHERE w.id = p_weld_id
  RETURNING id INTO made;
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('ndt_report', made, coalesce(p_result, 'pending')::text, who,
          nullif(btrim(coalesce(p_method,'')), '') || coalesce(': ' || nullif(btrim(coalesce(p_findings,'')), ''), ''));
  RETURN made;
END;
$$;

-- Signing a weld off. Separate from recording it, because it happens at a different moment and by a
-- different judgement — and the trigger in schema.sql is what refuses it on evidence that does not exist.
CREATE FUNCTION accept_weld(p_weld_id bigint, p_accepted boolean DEFAULT true, p_why text DEFAULT NULL)
RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('signing a weld off');
  said text;
BEGIN
  UPDATE weld SET final_result = (CASE WHEN p_accepted THEN 'accepted' ELSE 'rejected' END)::weld_result,
                  status = (CASE WHEN p_accepted THEN 'accepted' ELSE 'rejected' END)::weld_status,
                  updated_at = now()
   WHERE id = p_weld_id
  RETURNING ref INTO said;
  IF said IS NULL THEN
    RAISE EXCEPTION 'no such weld' USING ERRCODE = 'foreign_key_violation';
  END IF;
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('weld', p_weld_id, CASE WHEN p_accepted THEN 'accepted' ELSE 'rejected' END, who,
          nullif(btrim(coalesce(p_why,'')), ''));
  RETURN said;
END;
$$;

-- The procedure. Saved as a draft and approved separately, because approval is the whole difference
-- between a proposal and something a weld may be made to — and the schema refuses an approved WPS that
-- does not say who approved it.
CREATE FUNCTION save_wps(
  p_id bigint,
  p_ref text,
  p_process text,
  p_revision int DEFAULT 1,
  p_material_group text DEFAULT NULL,
  p_thickness_range text DEFAULT NULL,
  p_diameter_range text DEFAULT NULL,
  p_joint_type text DEFAULT NULL,
  p_position text DEFAULT NULL,
  p_filler_material text DEFAULT NULL,
  p_shielding_gas text DEFAULT NULL,
  p_preheat_interpass text DEFAULT NULL,
  p_supporting_wpqr text DEFAULT NULL,
  p_document_id bigint DEFAULT NULL,
  p_notes text DEFAULT NULL
) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('saving a welding procedure');
  named text := nullif(btrim(coalesce(p_ref, '')), '');
  said text := nullif(btrim(coalesce(p_process, '')), '');
  saved bigint;
BEGIN
  IF named IS NULL OR said IS NULL THEN
    RAISE EXCEPTION 'a procedure needs a reference and a process' USING ERRCODE = 'check_violation';
  END IF;
  IF p_id IS NULL THEN
    INSERT INTO wps (ref, revision, process, material_group, thickness_range, diameter_range, joint_type,
                     position, filler_material, shielding_gas, preheat_interpass, supporting_wpqr,
                     document_id, notes)
    VALUES (named, coalesce(p_revision, 1), said, nullif(btrim(coalesce(p_material_group,'')), ''),
            nullif(btrim(coalesce(p_thickness_range,'')), ''), nullif(btrim(coalesce(p_diameter_range,'')), ''),
            nullif(btrim(coalesce(p_joint_type,'')), ''), nullif(btrim(coalesce(p_position,'')), ''),
            nullif(btrim(coalesce(p_filler_material,'')), ''), nullif(btrim(coalesce(p_shielding_gas,'')), ''),
            nullif(btrim(coalesce(p_preheat_interpass,'')), ''), nullif(btrim(coalesce(p_supporting_wpqr,'')), ''),
            p_document_id, nullif(btrim(coalesce(p_notes,'')), ''))
    RETURNING id INTO saved;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    VALUES ('wps', saved, 'drafted', who, named || ' rev ' || coalesce(p_revision, 1)::text);
  ELSE
    UPDATE wps SET ref = named, revision = coalesce(p_revision, revision), process = said,
      material_group = nullif(btrim(coalesce(p_material_group,'')), ''),
      thickness_range = nullif(btrim(coalesce(p_thickness_range,'')), ''),
      diameter_range = nullif(btrim(coalesce(p_diameter_range,'')), ''),
      joint_type = nullif(btrim(coalesce(p_joint_type,'')), ''),
      position = nullif(btrim(coalesce(p_position,'')), ''),
      filler_material = nullif(btrim(coalesce(p_filler_material,'')), ''),
      shielding_gas = nullif(btrim(coalesce(p_shielding_gas,'')), ''),
      preheat_interpass = nullif(btrim(coalesce(p_preheat_interpass,'')), ''),
      supporting_wpqr = nullif(btrim(coalesce(p_supporting_wpqr,'')), ''),
      document_id = coalesce(p_document_id, document_id),
      notes = nullif(btrim(coalesce(p_notes,'')), ''), updated_at = now()
     WHERE id = p_id
    RETURNING id INTO saved;
    IF saved IS NULL THEN
      RAISE EXCEPTION 'no such procedure' USING ERRCODE = 'foreign_key_violation';
    END IF;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    VALUES ('wps', saved, 'corrected', who, named);
  END IF;
  RETURN saved;
END;
$$;

CREATE FUNCTION approve_wps(p_id bigint, p_approve boolean DEFAULT true) RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('approving a welding procedure');
  held record;
BEGIN
  SELECT ref, revision, status, supporting_wpqr INTO held FROM wps WHERE id = p_id;
  IF held.ref IS NULL THEN
    RAISE EXCEPTION 'no such procedure' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF p_approve AND btrim(coalesce(held.supporting_wpqr, '')) = '' THEN
    -- The one thing an auditor asks for first: a procedure is approved because somebody welded a test
    -- piece and it was tested. Approving one with no qualification record behind it is approving a
    -- document because it exists.
    RAISE EXCEPTION 'procedure % rev % cannot be approved with no supporting WPQR — a procedure is '
      'approved on a qualification record, not on its own say-so', held.ref, held.revision
      USING ERRCODE = 'check_violation';
  END IF;
  UPDATE wps SET status = (CASE WHEN p_approve THEN 'approved' ELSE 'withdrawn' END)::wps_status,
                 approved_on = CASE WHEN p_approve THEN current_date ELSE approved_on END,
                 approved_by = CASE WHEN p_approve THEN who ELSE approved_by END,
                 updated_at = now()
   WHERE id = p_id;
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('wps', p_id, CASE WHEN p_approve THEN 'approved' ELSE 'withdrawn' END, who,
          held.ref || ' rev ' || held.revision::text);
  RETURN held.ref;
END;
$$;

-- Which welder is qualified to what. The office's, because a welder cannot qualify themselves.
CREATE FUNCTION save_welder_qual(
  p_id bigint,
  p_welder_id bigint,
  p_qual_no text,
  p_process text,
  p_issued_by text,
  p_issued_on date,
  p_expires_on date,
  p_material_group text DEFAULT NULL,
  p_thickness_range text DEFAULT NULL,
  p_position text DEFAULT NULL,
  p_status welder_qual_status DEFAULT 'valid',
  p_document_id bigint DEFAULT NULL,
  p_notes text DEFAULT NULL
) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('recording a welder qualification');
  saved bigint;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM app_user WHERE id = p_welder_id AND is_active) THEN
    RAISE EXCEPTION 'that is not somebody who works here' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF nullif(btrim(coalesce(p_qual_no, '')), '') IS NULL
     OR nullif(btrim(coalesce(p_process, '')), '') IS NULL
     OR nullif(btrim(coalesce(p_issued_by, '')), '') IS NULL THEN
    RAISE EXCEPTION 'a qualification needs a number, a process and who issued it'
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_issued_on IS NULL OR p_expires_on IS NULL THEN
    RAISE EXCEPTION 'a qualification needs the day it was issued and the day it runs out'
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_id IS NULL THEN
    INSERT INTO welder_qual (welder_id, qual_no, process, material_group, thickness_range, position,
                             issued_by, issued_on, expires_on, status, document_id, notes)
    VALUES (p_welder_id, btrim(p_qual_no), btrim(p_process),
            nullif(btrim(coalesce(p_material_group,'')), ''), nullif(btrim(coalesce(p_thickness_range,'')), ''),
            nullif(btrim(coalesce(p_position,'')), ''), btrim(p_issued_by), p_issued_on, p_expires_on,
            coalesce(p_status, 'valid'), p_document_id, nullif(btrim(coalesce(p_notes,'')), ''))
    RETURNING id INTO saved;
  ELSE
    UPDATE welder_qual SET welder_id = p_welder_id, qual_no = btrim(p_qual_no), process = btrim(p_process),
      material_group = nullif(btrim(coalesce(p_material_group,'')), ''),
      thickness_range = nullif(btrim(coalesce(p_thickness_range,'')), ''),
      position = nullif(btrim(coalesce(p_position,'')), ''), issued_by = btrim(p_issued_by),
      issued_on = p_issued_on, expires_on = p_expires_on, status = coalesce(p_status, status),
      document_id = coalesce(p_document_id, document_id),
      notes = nullif(btrim(coalesce(p_notes,'')), ''), updated_at = now()
     WHERE id = p_id
    RETURNING id INTO saved;
    IF saved IS NULL THEN
      RAISE EXCEPTION 'no such qualification' USING ERRCODE = 'foreign_key_violation';
    END IF;
  END IF;
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('welder_qual', saved, CASE WHEN p_id IS NULL THEN 'recorded' ELSE 'corrected' END, who,
          btrim(p_qual_no) || ' (' || btrim(p_process) || ') to ' || p_expires_on::text);
  RETURN saved;
END;
$$;

-- A note against any of the four, in the same log every other record's history comes from.
CREATE FUNCTION add_welding_note(p_entity text, p_id bigint, p_text text) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('adding a note to a welding record');
  said text := nullif(btrim(coalesce(p_text, '')), '');
  made bigint;
  there boolean;
BEGIN
  IF said IS NULL THEN
    RAISE EXCEPTION 'an empty note is not a note' USING ERRCODE = 'check_violation';
  END IF;
  IF p_entity NOT IN ('weld', 'ndt_report', 'wps', 'welder_qual') THEN
    RAISE EXCEPTION 'there is no welding register called %', p_entity USING ERRCODE = 'check_violation';
  END IF;
  EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I WHERE id = $1)', p_entity) INTO there USING p_id;
  IF NOT there THEN
    RAISE EXCEPTION 'no such %', p_entity USING ERRCODE = 'foreign_key_violation';
  END IF;
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES (p_entity, p_id, 'note', who, said)
  RETURNING id INTO made;
  RETURN made;
END;
$$;

-- Taken away from everybody first, like every other function in this file, and given back below to the
-- roles that have business with it. These sit here rather than beside the document revokes because
-- api.sql runs top to bottom and a REVOKE cannot name a function that does not exist yet — which is
-- the second time that has been got wrong in this file today.
REVOKE ALL ON FUNCTION record_weld(bigint, text, text, bigint, bigint, date, bigint, text, text, text,
  text, text, numeric, text, text, text, boolean, text, boolean, boolean, text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION record_weld_repair(bigint, text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION record_ndt(bigint, text, ndt_result, text, text, numeric, text, text, text, date,
  text, boolean, boolean, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION accept_weld(bigint, boolean, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION save_wps(bigint, text, text, int, text, text, text, text, text, text, text, text,
  text, bigint, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION approve_wps(bigint, boolean) FROM PUBLIC;
REVOKE ALL ON FUNCTION save_welder_qual(bigint, bigint, text, text, text, date, date, text, text, text,
  welder_qual_status, bigint, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION add_welding_note(text, bigint, text) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION bootstrap_first_admin(text, text, text) TO varmak_api;
GRANT EXECUTE ON FUNCTION add_person(text, text, user_role), set_person_pin(bigint, text),
  set_person_password(bigint, text), set_person_active(bigint, boolean), set_person_role(bigint, user_role)
TO varmak_admin;
GRANT EXECUTE ON FUNCTION change_my_password(text, text), people()
TO varmak_admin, varmak_office, varmak_workshop;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- What the HTTP layer needs to know about a token
--
-- The pool connects as varmak_api, which can read nothing at all — so it cannot look up who a token
-- belongs to, and that is deliberate. This is the one thing it may ask, and the answer is exactly
-- enough to set the session up: who you are, what role to become, and the name to record against
-- whatever you do. Nothing else, and never from anything the client sent.
CREATE FUNCTION session_identity(p_token text)
RETURNS TABLE (user_id bigint, user_role user_role, display_name text)
LANGUAGE sql STABLE SECURITY DEFINER AS $$
  SELECT u.id, u.role, u.display_name
    FROM app_session s JOIN app_user u ON u.id = s.user_id
   WHERE s.token = p_token AND s.ended_at IS NULL AND s.expires_at > now() AND u.is_active;
$$;

ALTER FUNCTION session_identity(text) OWNER TO varmak_engine;
REVOKE ALL ON FUNCTION session_identity(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION session_identity(text) TO varmak_api;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Who may call what
--
-- The workflows are granted to the roles whose job they are. The floor books hours, records
-- operations and issues material; the office quotes, accepts, receives and converts.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

REVOKE ALL ON FUNCTION already_done(text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION require_session(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION record_result(text, text) FROM PUBLIC;
-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- The store
--
-- Material could leave the shelf before these — issue_material_offline is what the shop tablet calls —
-- but nothing could put an item on the shelf in the first place, or record steel arriving. So a
-- workshop could issue material it had no way of telling the system it had.
--
-- receive_stock is not receive_goods. That one takes a purchase-order line and derives the order's
-- status from what has arrived against it. This one is the storeman entering steel from a delivery note
-- with no order behind it, which is how a small workshop buys most of what it uses.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE FUNCTION save_stock_item(
  p_id bigint,
  p_code text,
  p_description text,
  p_unit text,
  p_group_id bigint DEFAULT NULL,
  p_subgroup_id bigint DEFAULT NULL,
  p_location_id bigint DEFAULT NULL,
  p_sublocation_id bigint DEFAULT NULL,
  p_bin_code text DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_grade text DEFAULT NULL,
  p_dimensions text DEFAULT NULL,
  p_base_unit text DEFAULT NULL,
  p_size_per_unit numeric DEFAULT NULL,
  p_weight_per_base numeric DEFAULT NULL,
  p_unit_weight numeric DEFAULT NULL,
  p_min_stock numeric DEFAULT 0,
  p_reorder_quantity numeric DEFAULT NULL,
  p_heat_no text DEFAULT NULL,
  p_material_cert_ref text DEFAULT NULL,
  p_avg_cost numeric DEFAULT NULL,
  p_last_price numeric DEFAULT NULL
) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  saved bigint;
  existing text;
  who text;
BEGIN
  PERFORM require_session('saving a store item');
  who := current_app_name();
  p_min_stock := coalesce(p_min_stock, 0);

  IF coalesce(btrim(p_code), '') = '' THEN
    RAISE EXCEPTION 'a store item needs a code — it is what the label says';
  END IF;
  IF coalesce(btrim(p_description), '') = '' THEN
    RAISE EXCEPTION 'a store item needs a description';
  END IF;
  IF coalesce(btrim(p_unit), '') = '' THEN
    RAISE EXCEPTION 'a store item needs a unit — a number with no unit is not a quantity';
  END IF;

  -- Two rows with one code is two items to the system and one item to whoever is holding the label.
  SELECT description INTO existing FROM stock_item
   WHERE upper(btrim(code)) = upper(btrim(p_code)) AND (p_id IS NULL OR id <> p_id) LIMIT 1;
  IF existing IS NOT NULL THEN
    RAISE EXCEPTION 'there is already an item coded % — it is %', upper(btrim(p_code)), existing;
  END IF;

  -- `stock` is not a parameter, and that is the whole point of the store. A figure typed straight into
  -- the stock column is a figure with no movement behind it, and the shelf then disagrees with the
  -- record of why. Steel arrives through receive_stock, leaves through issue_material, and is corrected
  -- through record_stocktake — each of which writes the movement that explains itself.
  IF p_id IS NULL THEN
    INSERT INTO stock_item (code, description, unit, group_id, subgroup_id, location_id,
                            sublocation_id, bin_code, category, grade, dimensions, base_unit,
                            size_per_unit, weight_per_base, unit_weight, min_stock, reorder_quantity,
                            heat_no, material_cert_ref, avg_cost, last_price)
    VALUES (upper(btrim(p_code)), btrim(p_description), btrim(p_unit), p_group_id, p_subgroup_id,
            p_location_id, p_sublocation_id, p_bin_code, p_category, p_grade, p_dimensions,
            p_base_unit, p_size_per_unit, p_weight_per_base, p_unit_weight, p_min_stock,
            p_reorder_quantity, p_heat_no, p_material_cert_ref, p_avg_cost, p_last_price)
    RETURNING id INTO saved;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    VALUES ('stock_item', saved, 'created', who, upper(btrim(p_code)) || ' ' || btrim(p_description));
  ELSE
    UPDATE stock_item SET
      code = upper(btrim(p_code)), description = btrim(p_description), unit = btrim(p_unit),
      group_id = p_group_id, subgroup_id = p_subgroup_id, location_id = p_location_id,
      sublocation_id = p_sublocation_id, bin_code = p_bin_code, category = p_category,
      grade = p_grade, dimensions = p_dimensions, base_unit = p_base_unit,
      size_per_unit = p_size_per_unit, weight_per_base = p_weight_per_base,
      unit_weight = p_unit_weight, min_stock = p_min_stock, reorder_quantity = p_reorder_quantity,
      heat_no = p_heat_no, material_cert_ref = p_material_cert_ref,
      avg_cost = p_avg_cost, last_price = p_last_price
     WHERE id = p_id
    RETURNING id INTO saved;
    IF saved IS NULL THEN
      RAISE EXCEPTION 'no such store item, or it is not yours to change'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    VALUES ('stock_item', saved, 'updated', who, upper(btrim(p_code)));
  END IF;
  RETURN saved;
END;
$$;

-- Steel arriving, from a delivery note rather than against an order.
--
-- The average cost is recomputed rather than overwritten, which is the difference between a store that
-- can cost a job and one that can only tell you what the last load cost. Weighted by what was on the
-- shelf and what arrived: fifty kilos at 14.00 plus fifty at 16.00 is a hundred at 15.00, not a hundred
-- at 16.00.
CREATE FUNCTION receive_stock(
  p_item_id bigint,
  p_quantity numeric,
  p_unit_price numeric DEFAULT NULL,
  p_supplier text DEFAULT NULL,
  p_delivery_note text DEFAULT NULL,
  p_heat_no text DEFAULT NULL,
  p_material_cert_ref text DEFAULT NULL,
  p_bin_code text DEFAULT NULL,
  p_note text DEFAULT NULL
) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  item stock_item%ROWTYPE;
  movement_id bigint;
  who text;
BEGIN
  -- The session, read here rather than through require_session(), because this function is owned by
  -- varmak_engine and that role holds no EXECUTE on the helper the three app roles do. Same shape as
  -- issue_material, which is the other engine-owned door onto the store.
  SELECT display_name INTO who FROM app_user WHERE id = current_app_user() AND is_active;
  IF who IS NULL THEN
    RAISE EXCEPTION 'sign in before entering stock' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    RAISE EXCEPTION 'a receipt must be for more than nothing';
  END IF;
  -- Locked for the same reason issue_stock locks: two deliveries of the same item entered at the same
  -- moment must not each recompute the average cost from the figure the other started with.
  SELECT * INTO item FROM stock_item WHERE id = p_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such store item' USING ERRCODE = 'foreign_key_violation';
  END IF;

  UPDATE stock_item SET
    stock = stock + p_quantity,
    -- Weighted average, and only when a price came with the delivery. A receipt with no price on it
    -- must not drag the average to zero.
    avg_cost = CASE
      WHEN p_unit_price IS NULL THEN item.avg_cost
      WHEN coalesce(item.avg_cost, 0) = 0 OR item.stock <= 0 THEN p_unit_price
      ELSE round(((item.stock * item.avg_cost) + (p_quantity * p_unit_price))
                 / (item.stock + p_quantity), 2)
    END,
    last_price = coalesce(p_unit_price, item.last_price),
    heat_no = coalesce(nullif(btrim(coalesce(p_heat_no, '')), ''), item.heat_no),
    material_cert_ref = coalesce(nullif(btrim(coalesce(p_material_cert_ref, '')), ''),
                                 item.material_cert_ref),
    bin_code = coalesce(nullif(btrim(coalesce(p_bin_code, '')), ''), item.bin_code)
   WHERE id = p_item_id;

  -- The name on the movement is the session's, never the caller's. Same rule as issuing: a record of
  -- who put the steel on the shelf that anybody could sign is not a record.
  INSERT INTO stock_movement (stock_item_id, kind, quantity, moved_by, moved_from, moved_to, unit, note)
  VALUES (p_item_id, 'receipt', p_quantity, who,
          nullif(btrim(coalesce(p_supplier, '')), ''),
          coalesce(nullif(btrim(coalesce(p_bin_code, '')), ''), item.bin_code),
          item.unit,
          nullif(btrim(concat_ws(' · ', nullif(btrim(coalesce(p_delivery_note, '')), ''),
                                 nullif(btrim(coalesce(p_note, '')), ''))), ''))
  RETURNING id INTO movement_id;

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('stock_item', p_item_id, 'received', who,
          trim_scale(p_quantity) || ' ' || item.unit || ' of ' || item.code);
  RETURN movement_id;
END;
$$;

-- A stocktake. The counted figure becomes the stock, and the difference becomes a movement that says
-- so — because a shelf corrected without a record is a shelf nobody can reconcile afterwards.
CREATE FUNCTION record_stocktake(p_item_id bigint, p_counted numeric, p_note text DEFAULT NULL)
RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  item stock_item%ROWTYPE;
  movement_id bigint;
  difference numeric;
  who text;
BEGIN
  SELECT display_name INTO who FROM app_user WHERE id = current_app_user() AND is_active;
  IF who IS NULL THEN
    RAISE EXCEPTION 'sign in before recording a count' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_counted IS NULL OR p_counted < 0 THEN
    RAISE EXCEPTION 'a count cannot be less than nothing';
  END IF;
  SELECT * INTO item FROM stock_item WHERE id = p_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such store item' USING ERRCODE = 'foreign_key_violation';
  END IF;
  difference := p_counted - item.stock;
  IF difference = 0 THEN
    -- Counted and found right. Nothing to correct, and a movement of nothing would be noise in the
    -- one place a storeman goes to find out why a figure changed.
    RETURN NULL;
  END IF;

  UPDATE stock_item SET stock = p_counted WHERE id = p_item_id;

  INSERT INTO stock_movement (stock_item_id, kind, quantity, moved_by, unit, note)
  VALUES (p_item_id, 'adjustment', abs(difference), who, item.unit,
          concat_ws(' · ', 'counted ' || trim_scale(p_counted) || ', was ' || trim_scale(item.stock),
                    nullif(btrim(coalesce(p_note, '')), '')))
  RETURNING id INTO movement_id;

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('stock_item', p_item_id, 'counted', who,
          item.code || ': ' || trim_scale(item.stock) || ' → ' || trim_scale(p_counted));
  RETURN movement_id;
END;
$$;

-- Owned by the engine for the same reason issue_material is: they write a stock movement, and the name
-- on it has to be the session's rather than anything the caller could pass. SECURITY DEFINER is what
-- lets them insert the movement while the caller's own role holds no INSERT on that table directly.
ALTER FUNCTION receive_stock(bigint, numeric, numeric, text, text, text, text, text, text) OWNER TO varmak_engine;
ALTER FUNCTION record_stocktake(bigint, numeric, text) OWNER TO varmak_engine;

-- CREATE on the schema stays granted through the equipment section below, which has the last
-- ownership change in the file; it is revoked at the end of that section.

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- The machines, and what has been done to them
--
-- The equipment register was the strangest gap in this system: every safety gate in the app reads it,
-- the jobcard screen refuses to attach a machine that may not be run, the shop-floor hours screen
-- refuses to book time against one — and nothing could put a machine in the register, mark it serviced,
-- or sign a check before use. The gates were real and had nothing to read. `equipment-gates.js` has
-- looked for a passed pre-use check since it was written, and the answer was always "there isn't one".
--
-- Two functions, and the split is the authorisation. Editing the register is the office's job — what a
-- machine is, what it cost, when its certificate runs out. Signing a check before running it is the
-- welder's, and it is the one thing on this screen the floor may write: a check nobody on the floor can
-- record is a check the office signs for machines it is not standing in front of.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE FUNCTION save_equipment(
  p_id bigint,
  p_ref text,
  p_name text,
  p_category text,
  p_status equipment_status DEFAULT 'Available',
  p_manufacturer text DEFAULT NULL,
  p_model text DEFAULT NULL,
  p_serial_no text DEFAULT NULL,
  p_asset_no text DEFAULT NULL,
  p_year_of_manufacture int DEFAULT NULL,
  p_description text DEFAULT NULL,
  p_current_location text DEFAULT NULL,
  p_home_location text DEFAULT NULL,
  p_department text DEFAULT NULL,
  p_responsible_person text DEFAULT NULL,
  p_operator text DEFAULT NULL,
  p_condition text DEFAULT NULL,
  p_criticality text DEFAULT NULL,
  p_safety_warnings text DEFAULT NULL,
  p_certification_expiry date DEFAULT NULL,
  p_purchase_date date DEFAULT NULL,
  p_purchase_supplier text DEFAULT NULL,
  p_purchase_price numeric DEFAULT NULL,
  p_warranty_expiry date DEFAULT NULL,
  p_operating_hours numeric DEFAULT NULL,
  p_service_interval_hours int DEFAULT NULL,
  p_qr_code text DEFAULT NULL,
  p_pre_use_check_required boolean DEFAULT false,
  p_notes text DEFAULT NULL
) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  saved bigint;
  existing text;
  who text;
BEGIN
  PERFORM require_session('saving a machine');
  who := current_app_name();

  IF coalesce(btrim(p_ref), '') = '' THEN
    RAISE EXCEPTION 'a machine needs a reference — it is what is written on the machine itself';
  END IF;
  IF coalesce(btrim(p_name), '') = '' THEN
    RAISE EXCEPTION 'a machine needs a name';
  END IF;
  IF coalesce(btrim(p_category), '') = '' THEN
    RAISE EXCEPTION 'a machine needs a category — it is what the safety rules are grouped by';
  END IF;

  -- Two rows under one reference is two machines to the system and one machine to whoever is standing
  -- in front of it, which is how a service record ends up on the wrong press.
  SELECT name INTO existing FROM equipment
   WHERE upper(btrim(ref)) = upper(btrim(p_ref)) AND (p_id IS NULL OR id <> p_id) LIMIT 1;
  IF existing IS NOT NULL THEN
    RAISE EXCEPTION 'there is already a machine referenced % — it is %', upper(btrim(p_ref)), existing;
  END IF;

  -- The three dates a machine is judged by are not touched here, and that is deliberate: the date of
  -- the last service, inspection and calibration are what record_equipment_event writes, from the event
  -- that actually happened. A form that could type them in is a form that can claim a service nobody
  -- performed, which is exactly the claim a certificate is supposed to make impossible.
  IF p_id IS NULL THEN
    INSERT INTO equipment (ref, name, category, status, manufacturer, model, serial_no, asset_no,
                           year_of_manufacture, description, current_location, home_location,
                           department, responsible_person, operator, condition, criticality,
                           safety_warnings, certification_expiry, purchase_date, purchase_supplier,
                           purchase_price, warranty_expiry, operating_hours, service_interval_hours,
                           qr_code, pre_use_check_required, notes)
    VALUES (upper(btrim(p_ref)), btrim(p_name), btrim(p_category), p_status, p_manufacturer, p_model,
            p_serial_no, p_asset_no, p_year_of_manufacture, p_description, p_current_location,
            p_home_location, p_department, p_responsible_person, p_operator, p_condition,
            p_criticality, p_safety_warnings, p_certification_expiry, p_purchase_date,
            p_purchase_supplier, p_purchase_price, p_warranty_expiry, coalesce(p_operating_hours, 0),
            p_service_interval_hours, p_qr_code, coalesce(p_pre_use_check_required, false), p_notes)
    RETURNING id INTO saved;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    VALUES ('equipment', saved, 'created', who, upper(btrim(p_ref)) || ' ' || btrim(p_name));
  ELSE
    UPDATE equipment SET
      ref = upper(btrim(p_ref)), name = btrim(p_name), category = btrim(p_category),
      status = p_status, manufacturer = p_manufacturer, model = p_model, serial_no = p_serial_no,
      asset_no = p_asset_no, year_of_manufacture = p_year_of_manufacture, description = p_description,
      current_location = p_current_location, home_location = p_home_location,
      department = p_department, responsible_person = p_responsible_person, operator = p_operator,
      condition = p_condition, criticality = p_criticality, safety_warnings = p_safety_warnings,
      certification_expiry = p_certification_expiry, purchase_date = p_purchase_date,
      purchase_supplier = p_purchase_supplier, purchase_price = p_purchase_price,
      warranty_expiry = p_warranty_expiry,
      operating_hours = coalesce(p_operating_hours, operating_hours),
      service_interval_hours = p_service_interval_hours, qr_code = p_qr_code,
      pre_use_check_required = coalesce(p_pre_use_check_required, false), notes = p_notes
     WHERE id = p_id
    RETURNING id INTO saved;
    IF saved IS NULL THEN
      RAISE EXCEPTION 'no such machine, or it is not yours to change'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    VALUES ('equipment', saved, 'updated', who, upper(btrim(p_ref)));
  END IF;
  RETURN saved;
END;
$$;

-- Something happened to a machine: it was serviced, calibrated, inspected, repaired, it broke down, or
-- somebody signed a check before running it.
--
-- One function for all six because they are one fact — a dated record of who did what to which machine
-- and how it came out — and six functions would be six places for the date of the last service to be
-- written differently. The kind decides which of the three "last done" dates moves, which is the only
-- branch in here.
--
-- Who performed it is the session, never a parameter. A service record somebody else's name can be put
-- on is not a service record, and a pre-use check signed in another welder's name is worse than none.
-- What an event does to the machine, and the only function in the system allowed to write it.
--
-- Two columns, both of which have to move and neither of which any of the three roles should hold
-- directly: the date a machine was last serviced, and its status when it breaks down. A welder with
-- UPDATE on equipment.status could bring a quarantined machine back into service; a welder with UPDATE
-- on last_service_date could claim a service nobody performed. So this runs as varmak_engine, does
-- exactly these two things, and every other route to those columns stays shut.
--
-- Split out rather than making record_equipment_event itself SECURITY DEFINER, which is the shape
-- issue_material_offline already uses: the replay protection stays in the caller's own role — where the
-- grants on device_event are — and only the write nobody should hold runs as the engine.
CREATE FUNCTION equipment_state_after_event(
  p_equipment_id bigint,
  p_kind equipment_event_kind,
  p_result text,
  p_day date
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  -- Keyed on the kind as well as the result, and not only for tidiness: written on the result alone, a
  -- pre-use check that passed ran an UPDATE changing all three dates to their own current values — a
  -- no-op that still needs the privilege to write them.
  IF p_result IN ('pass', 'done') AND p_kind IN ('service', 'repair', 'inspection', 'calibration') THEN
    UPDATE equipment SET
      last_service_date = CASE WHEN p_kind IN ('service', 'repair') THEN p_day ELSE last_service_date END,
      last_inspection_date = CASE WHEN p_kind = 'inspection' THEN p_day ELSE last_inspection_date END,
      last_calibration_date = CASE WHEN p_kind = 'calibration' THEN p_day ELSE last_calibration_date END
     WHERE id = p_equipment_id;
  END IF;

  -- A breakdown takes the machine out of service by itself. Nobody has to remember to, which is the
  -- point: the record of the breakdown and the machine being stopped are the same event, and a shop
  -- where they are two actions is a shop where one of them gets missed.
  IF p_kind = 'breakdown' THEN
    UPDATE equipment SET status = 'Out of Service' WHERE id = p_equipment_id;
  END IF;
END;
$$;

CREATE FUNCTION record_equipment_event(
  p_equipment_id bigint,
  p_kind equipment_event_kind,
  p_result text,
  p_happened_on date DEFAULT NULL,
  p_next_due_on date DEFAULT NULL,
  p_cost numeric DEFAULT NULL,
  p_note text DEFAULT NULL,
  p_jobcard_id bigint DEFAULT NULL,
  p_resolves_event_id bigint DEFAULT NULL,
  p_event_id text DEFAULT NULL
) RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('recording what happened to a machine');
  seen text := already_done(p_event_id, 'record_equipment_event');
  machine text;
  made bigint;
  on_day date := coalesce(p_happened_on, current_date);
BEGIN
  -- Replay protection, for the same reason booking hours has it: a pre-use check is signed at the
  -- machine, which is where the signal dies, and a second check for the same press is a second record
  -- of a thing that happened once.
  IF seen IS NOT NULL THEN
    RETURN seen;
  END IF;

  SELECT name INTO machine FROM equipment WHERE id = p_equipment_id;
  IF machine IS NULL THEN
    RAISE EXCEPTION 'no such machine' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF on_day > current_date THEN
    RAISE EXCEPTION 'a service or a check cannot be recorded for a date that has not happened yet'
      USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO equipment_event (equipment_id, kind, happened_on, performed_by, result, next_due_on,
                               cost, note, jobcard_id, resolves_event_id)
  VALUES (p_equipment_id, p_kind, on_day, who, p_result, p_next_due_on, p_cost, p_note,
          p_jobcard_id, p_resolves_event_id)
  RETURNING id INTO made;

  -- An event that answers an earlier failure marks that failure answered. Done here rather than left
  -- to the caller, because a resolution recorded without it is a machine that stays stopped for a
  -- reason somebody has already dealt with — and the gate reads the flag, not the link.
  IF p_resolves_event_id IS NOT NULL THEN
    UPDATE equipment_event SET resolved = true
     WHERE id = p_resolves_event_id AND equipment_id = p_equipment_id;
  END IF;

  -- The date a machine is judged by moves only when the thing that sets it actually happened and
  -- passed. A failed inspection is not an inspection date; it is a reason the machine is stopped.
  -- What the event does to the machine itself, through the one function allowed to write those columns.
  PERFORM equipment_state_after_event(p_equipment_id, p_kind, p_result, on_day);

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('equipment', p_equipment_id, p_kind::text, who,
          machine || ': ' || p_result || coalesce(' — ' || p_note, ''));

  PERFORM record_result(p_event_id, 'E-' || made);
  RETURN 'E-' || made;
END;
$$;

-- A machine taken to a bench, and brought back.
--
-- One row per period a machine spends on a jobcard, and a partial unique index that refuses the second
-- live one — so "which jobcard is the plasma cutter on" has exactly one answer and the database is what
-- makes that true, not the screen that happens to ask.
--
-- Nothing here changes the machine's status, and that is deliberate. A machine on a bench is still
-- available in the sense the safety gates mean: `available` versus `out-of-service` is about whether it
-- may be run at all, and overwriting it with something about where it is would make the gate read the
-- wrong question. Where it is, is the assignment — which the snapshot carries as `assignedJobcard`.
CREATE FUNCTION assign_equipment(
  p_equipment_id bigint,
  p_jobcard_id bigint,
  p_event_id text DEFAULT NULL
) RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('assigning a machine');
  seen text := already_done(p_event_id, 'assign_equipment');
  machine text;
  card text;
  held text;
  made bigint;
BEGIN
  IF seen IS NOT NULL THEN
    RETURN seen;
  END IF;

  SELECT name INTO machine FROM equipment WHERE id = p_equipment_id;
  IF machine IS NULL THEN
    RAISE EXCEPTION 'no such machine' USING ERRCODE = 'foreign_key_violation';
  END IF;
  SELECT ref INTO card FROM jobcard WHERE id = p_jobcard_id;
  IF card IS NULL THEN
    RAISE EXCEPTION 'no such jobcard' USING ERRCODE = 'foreign_key_violation';
  END IF;

  -- Named before the index refuses it, because "duplicate key value violates unique constraint
  -- equipment_one_live_assignment" tells a welder nothing and the answer they need is which jobcard has
  -- it. The index is still what makes this true under two requests arriving together.
  SELECT j.ref INTO held FROM equipment_assignment a JOIN jobcard j ON j.id = a.jobcard_id
   WHERE a.equipment_id = p_equipment_id AND a.released_at IS NULL LIMIT 1;
  IF held IS NOT NULL THEN
    IF held = card THEN
      -- Already where it is being sent. Not an error: two people pressing the same button is not a
      -- mistake, and a refusal here would read as one.
      PERFORM record_result(p_event_id, card);
      RETURN card;
    END IF;
    RAISE EXCEPTION '% is on % — return it from there first', machine, held
      USING ERRCODE = 'unique_violation';
  END IF;

  INSERT INTO equipment_assignment (equipment_id, jobcard_id) VALUES (p_equipment_id, p_jobcard_id)
  RETURNING id INTO made;
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('equipment', p_equipment_id, 'assigned', who, machine || ' to ' || card);

  PERFORM record_result(p_event_id, card);
  RETURN card;
END;
$$;

CREATE FUNCTION return_equipment(
  p_equipment_id bigint,
  p_note text DEFAULT NULL,
  p_event_id text DEFAULT NULL
) RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('returning a machine');
  seen text := already_done(p_event_id, 'return_equipment');
  machine text;
  card text;
BEGIN
  IF seen IS NOT NULL THEN
    RETURN seen;
  END IF;

  SELECT e.name, j.ref INTO machine, card
    FROM equipment e
    LEFT JOIN equipment_assignment a ON a.equipment_id = e.id AND a.released_at IS NULL
    LEFT JOIN jobcard j ON j.id = a.jobcard_id
   WHERE e.id = p_equipment_id;
  IF machine IS NULL THEN
    RAISE EXCEPTION 'no such machine' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF card IS NULL THEN
    -- Nothing to return it from. Said plainly rather than refused, for the same reason as above: this is
    -- the state somebody pressing the button twice arrives at.
    PERFORM record_result(p_event_id, 'already returned');
    RETURN 'already returned';
  END IF;

  UPDATE equipment_assignment SET released_at = now()
   WHERE equipment_id = p_equipment_id AND released_at IS NULL;
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('equipment', p_equipment_id, 'returned', who,
          machine || ' from ' || card || coalesce(' — ' || p_note, ''));

  PERFORM record_result(p_event_id, card);
  RETURN card;
END;
$$;

ALTER FUNCTION equipment_state_after_event(bigint, equipment_event_kind, text, date)
  OWNER TO varmak_engine;
REVOKE ALL ON FUNCTION equipment_state_after_event(bigint, equipment_event_kind, text, date) FROM PUBLIC;
REVOKE ALL ON FUNCTION assign_equipment(bigint, bigint, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION return_equipment(bigint, text, text) FROM PUBLIC;
-- Taking a machine to a bench and bringing it back is floor work: the welder who needs the plasma
-- cutter is the one who fetches it, and a shop where that needs the office is a shop where the
-- assignment record stops matching where the machines actually are.
GRANT EXECUTE ON FUNCTION assign_equipment(bigint, bigint, text), return_equipment(bigint, text, text)
TO varmak_admin, varmak_office, varmak_workshop;
GRANT EXECUTE ON FUNCTION equipment_state_after_event(bigint, equipment_event_kind, text, date)
TO varmak_admin, varmak_office, varmak_workshop;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Work: the project, the jobcards on it, and the steps on those
--
-- Nothing could get onto the shop floor before these. accept_estimate makes a project out of a
-- quotation that was won, which is the path the estimating screen takes — but a workshop also puts
-- work on the bench that never had a quotation, and there was no way to do that except an INSERT.
--
-- Three functions, and the third is the shape that needed thinking about: a jobcard's steps are a
-- list, like the customer's contacts, but unlike contacts they have hours booked against them. So it
-- cannot be delete-and-rebuild — that would detach every hour ever booked from the step it was booked
-- on, silently, because hours_entry.operation_id is ON DELETE SET NULL. It matches on the id the
-- snapshot handed out instead, and refuses to remove a step somebody has already worked on.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE FUNCTION save_project(
  p_id bigint,
  p_name text,
  p_customer_id bigint,
  p_status text DEFAULT 'quotation',
  p_planned_hours numeric DEFAULT 0,
  p_progress int DEFAULT 0,
  p_deadline date DEFAULT NULL,
  p_description text DEFAULT NULL,
  p_phase text DEFAULT NULL,
  p_work_types text DEFAULT NULL,
  p_po_number text DEFAULT NULL,
  p_workshop text DEFAULT NULL,
  p_responsible text DEFAULT NULL,
  p_material_status text DEFAULT NULL,
  p_notes text DEFAULT NULL,
  p_planned_start date DEFAULT NULL,
  p_planned_completion date DEFAULT NULL,
  p_expected_completion date DEFAULT NULL,
  p_deliver_on date DEFAULT NULL,
  p_hold_reason text DEFAULT NULL,
  p_hold_comment text DEFAULT NULL,
  p_expected_resume date DEFAULT NULL,
  p_cancel_reason text DEFAULT NULL,
  p_quoted_value numeric DEFAULT NULL
) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  saved bigint;
  was project_status;
  who text;
BEGIN
  PERFORM require_session('saving a project');
  p_status := coalesce(p_status, 'quotation');
  -- The frontend carries two names for one state — 'active' in the estimating screen's vocabulary and
  -- 'production' from the estimate-conversion path, aliased to each other in project-rules.js — and
  -- 'draft' as a retired alias of 'quotation'. schema.sql fixed one canonical spelling and said the API
  -- would translate on the way in; this is that. It is the opposite decision from the jobcard priority,
  -- and for a reason: there the screen had one word and the schema had invented another, so the screen
  -- won. Here the screen has two words for the same state, so it cannot be followed — a database that
  -- accepted both would mean every query had to know the aliases.
  p_status := CASE lower(btrim(p_status))
                WHEN 'active' THEN 'production'
                WHEN 'in production' THEN 'production'
                WHEN 'draft' THEN 'quotation'
                ELSE lower(btrim(p_status))
              END;
  p_planned_hours := coalesce(p_planned_hours, 0);
  p_progress := coalesce(p_progress, 0);
  who := current_app_name();

  IF coalesce(btrim(p_name), '') = '' THEN
    RAISE EXCEPTION 'a project needs a name';
  END IF;
  IF p_customer_id IS NULL THEN
    RAISE EXCEPTION 'a project belongs to a customer — say which one';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM customer WHERE id = p_customer_id) THEN
    RAISE EXCEPTION 'no such customer, or it is not yours to read'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- used_hours is not a parameter and must never become one. It is a running total the hours entries
  -- maintain by trigger, and a screen that could set it could make a project claim work nobody did.
  IF p_id IS NULL THEN
    INSERT INTO project (name, customer_id, status, planned_hours, progress, deadline, description,
                         phase, work_types, po_number, workshop, responsible, material_status, notes,
                         planned_start, planned_completion, expected_completion, actual_completion,
                         hold_reason, hold_comment, expected_resume, cancel_reason, quoted_value)
    VALUES (btrim(p_name), p_customer_id, p_status::project_status, p_planned_hours, p_progress,
            p_deadline, p_description, p_phase, p_work_types, p_po_number, p_workshop, p_responsible,
            p_material_status, p_notes, p_planned_start, p_planned_completion, p_expected_completion,
            p_deliver_on, p_hold_reason, p_hold_comment, p_expected_resume, p_cancel_reason,
            p_quoted_value)
    RETURNING id INTO saved;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    VALUES ('project', saved, 'created', who, btrim(p_name));
  ELSE
    SELECT status INTO was FROM project WHERE id = p_id;
    IF was IS NULL THEN
      RAISE EXCEPTION 'no such project, or it is not yours to change'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    -- The status is assigned like any other field and the transition trigger has the last word on
    -- whether this one was allowed. Checking it here as well would be a second copy of the rulebook,
    -- and the rulebook is a table precisely so there is only one.
    UPDATE project SET
      name = btrim(p_name), customer_id = p_customer_id, status = p_status::project_status,
      planned_hours = p_planned_hours, progress = p_progress, deadline = p_deadline,
      description = p_description, phase = p_phase, work_types = p_work_types,
      po_number = p_po_number, workshop = p_workshop, responsible = p_responsible,
      material_status = p_material_status, notes = p_notes, planned_start = p_planned_start,
      planned_completion = p_planned_completion, expected_completion = p_expected_completion,
      actual_completion = p_deliver_on, hold_reason = p_hold_reason, hold_comment = p_hold_comment,
      expected_resume = p_expected_resume, cancel_reason = p_cancel_reason,
      quoted_value = p_quoted_value
     WHERE id = p_id
    RETURNING id INTO saved;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    VALUES ('project', saved, CASE WHEN was::text = p_status THEN 'updated' ELSE p_status END,
            who, btrim(p_name));
  END IF;
  RETURN saved;
END;
$$;

CREATE FUNCTION save_jobcard(
  p_id bigint,
  p_project_id bigint,
  p_title text,
  p_status text DEFAULT 'draft',
  p_item text DEFAULT NULL,
  p_quantity int DEFAULT 1,
  p_drawing_no text DEFAULT NULL,
  p_revision int DEFAULT 0,
  p_planned_hours numeric DEFAULT 0,
  p_planned_start date DEFAULT NULL,
  p_planned_completion date DEFAULT NULL,
  p_delivery_target date DEFAULT NULL,
  p_work_type text DEFAULT NULL,
  p_location text DEFAULT NULL,
  p_priority text DEFAULT NULL,
  p_responsible text DEFAULT NULL,
  p_material_readiness text DEFAULT NULL,
  p_heat_no text DEFAULT NULL,
  p_material_cert_ref text DEFAULT NULL,
  p_notes text DEFAULT NULL,
  p_progress int DEFAULT 0,
  p_inspection_required boolean DEFAULT false
) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  saved bigint;
  owner bigint;
  project_name text;
  who text;
BEGIN
  PERFORM require_session('saving a jobcard');
  p_status := coalesce(p_status, 'draft');
  p_quantity := coalesce(p_quantity, 1);
  p_revision := coalesce(p_revision, 0);
  p_planned_hours := coalesce(p_planned_hours, 0);
  p_progress := coalesce(p_progress, 0);
  who := current_app_name();

  IF coalesce(btrim(p_title), '') = '' THEN
    RAISE EXCEPTION 'a jobcard needs a title — it is what the person at the bench reads first';
  END IF;
  IF p_project_id IS NULL THEN
    RAISE EXCEPTION 'a jobcard belongs to a project — say which one';
  END IF;
  -- The customer comes from the project, and there is no parameter for it. A jobcard carrying a
  -- different customer from its project is a record that makes every report disagree with itself, and
  -- nobody would ever look at the two columns side by side to notice.
  SELECT customer_id, name INTO owner, project_name FROM project WHERE id = p_project_id;
  IF owner IS NULL THEN
    RAISE EXCEPTION 'no such project, or it is not yours to read'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO jobcard (project_id, customer_id, title, status, item, quantity, drawing_no,
                         revision, planned_hours, planned_start, planned_completion, delivery_target,
                         work_type, location, priority, responsible, material_readiness, heat_no,
                         material_cert_ref, notes, progress, inspection_required, created_by)
    VALUES (p_project_id, owner, btrim(p_title), p_status::jobcard_status, p_item, p_quantity,
            p_drawing_no, p_revision, p_planned_hours, p_planned_start, p_planned_completion,
            p_delivery_target, p_work_type, p_location, p_priority, p_responsible,
            p_material_readiness, p_heat_no, p_material_cert_ref, p_notes, p_progress,
            coalesce(p_inspection_required, false), who)
    RETURNING id INTO saved;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    VALUES ('jobcard', saved, 'created', who, project_name || ' — ' || btrim(p_title));
  ELSE
    UPDATE jobcard SET
      project_id = p_project_id, customer_id = owner, title = btrim(p_title),
      status = p_status::jobcard_status, item = p_item, quantity = p_quantity,
      drawing_no = p_drawing_no, revision = p_revision, planned_hours = p_planned_hours,
      planned_start = p_planned_start, planned_completion = p_planned_completion,
      delivery_target = p_delivery_target, work_type = p_work_type, location = p_location,
      priority = p_priority, responsible = p_responsible, material_readiness = p_material_readiness,
      heat_no = p_heat_no, material_cert_ref = p_material_cert_ref, notes = p_notes,
      progress = p_progress, inspection_required = coalesce(p_inspection_required, false)
     WHERE id = p_id
    RETURNING id INTO saved;
    IF saved IS NULL THEN
      RAISE EXCEPTION 'no such jobcard, or it is not yours to change'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    VALUES ('jobcard', saved, 'updated', who, btrim(p_title));
  END IF;
  RETURN saved;
END;
$$;

-- The steps on a jobcard. Matched on the id the snapshot handed out rather than rebuilt, for one
-- reason: hours are booked against a step, and hours_entry.operation_id is ON DELETE SET NULL — so
-- deleting and reinserting the list would leave every hour ever booked pointing at nothing, with no
-- error and nothing on screen to say it had happened. What the workshop would lose is the answer to
-- "how long did the weld-out actually take", which is the only number that makes the next estimate
-- better than a guess.
CREATE FUNCTION set_jobcard_operations(p_jobcard_id bigint, p_operations jsonb) RETURNS int
LANGUAGE plpgsql AS $$
DECLARE
  row_in jsonb;
  at int := 0;
  keeping bigint[] := ARRAY[]::bigint[];
  doomed record;
  title text;
BEGIN
  PERFORM require_session('saving the steps on a jobcard');
  SELECT j.title INTO title FROM jobcard j WHERE j.id = p_jobcard_id;
  IF title IS NULL THEN
    RAISE EXCEPTION 'no such jobcard, or it is not yours to change'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  p_operations := coalesce(p_operations, '[]'::jsonb);
  IF jsonb_typeof(p_operations) <> 'array' THEN
    RAISE EXCEPTION 'the steps have to arrive as a list';
  END IF;

  FOR row_in IN SELECT * FROM jsonb_array_elements(p_operations) LOOP
    IF coalesce(btrim(row_in->>'desc'), '') = '' THEN
      RAISE EXCEPTION 'every step needs a description — step % has none', at + 1;
    END IF;
    IF (row_in->>'id') IS NOT NULL AND (row_in->>'id') <> '' THEN
      keeping := keeping || (row_in->>'id')::bigint;
    END IF;
    at := at + 1;
  END LOOP;

  -- Refused before anything is written, and named. A step somebody has booked hours on, or has
  -- started, is a record of what happened rather than a line on a plan.
  FOR doomed IN
    SELECT o.seq, o.description, o.logged_hours, o.status FROM operation o
     WHERE o.jobcard_id = p_jobcard_id AND NOT (o.id = ANY (keeping))
     ORDER BY o.seq
  LOOP
    IF doomed.logged_hours > 0 THEN
      RAISE EXCEPTION 'step % (%) has % hours booked on it and cannot be taken off the jobcard',
        doomed.seq, doomed.description, doomed.logged_hours;
    END IF;
    IF doomed.status <> 'pending' THEN
      RAISE EXCEPTION 'step % (%) is % and cannot be taken off the jobcard',
        doomed.seq, doomed.description, doomed.status;
    END IF;
  END LOOP;

  DELETE FROM operation o WHERE o.jobcard_id = p_jobcard_id AND NOT (o.id = ANY (keeping));

  -- Checked at the end of this transaction rather than statement by statement, because writing seq 1
  -- where seq 2 was while 1 is still 1 collides halfway through a re-order that is perfectly fine by
  -- the time it finishes. The constraint is not relaxed — it is checked once, on the finished list.
  SET CONSTRAINTS operation_one_step_per_place DEFERRED;

  at := 0;
  FOR row_in IN SELECT * FROM jsonb_array_elements(p_operations) LOOP
    at := at + 1;
    IF (row_in->>'id') IS NOT NULL AND (row_in->>'id') <> '' THEN
      -- The sequence is the position in the list the screen sent, so it cannot arrive with a gap or
      -- with two steps claiming to be the third. The caller does not get to choose it.
      UPDATE operation SET
        description = btrim(row_in->>'desc'),
        instructions = nullif(btrim(coalesce(row_in->>'instructions', '')), ''),
        planned_hours = coalesce((row_in->>'plannedHours')::numeric, 0),
        planned_start = (row_in->>'plannedStart')::date,
        inspection_checkpoint = coalesce((row_in->>'inspectionCheckpoint')::boolean, false),
        notes = nullif(btrim(coalesce(row_in->>'notes', '')), ''),
        seq = at
       WHERE id = (row_in->>'id')::bigint AND jobcard_id = p_jobcard_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'step % is not on this jobcard', row_in->>'id';
      END IF;
    ELSE
      INSERT INTO operation (jobcard_id, seq, description, instructions, planned_hours,
                             planned_start, inspection_checkpoint, notes)
      VALUES (p_jobcard_id, at, btrim(row_in->>'desc'),
              nullif(btrim(coalesce(row_in->>'instructions', '')), ''),
              coalesce((row_in->>'plannedHours')::numeric, 0),
              (row_in->>'plannedStart')::date,
              coalesce((row_in->>'inspectionCheckpoint')::boolean, false),
              nullif(btrim(coalesce(row_in->>'notes', '')), ''));
    END IF;
  END LOOP;
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('jobcard', p_jobcard_id, 'steps changed', current_app_name(),
          at::text || ' step' || CASE WHEN at = 1 THEN '' ELSE 's' END);
  RETURN at;
END;
$$;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Customers
--
-- The first record a workshop starting from nothing has to be able to make, and until now there was
-- no way to make one except an INSERT. Two functions, because the customer and the people at the
-- customer are two different shapes: one row, and a list.
--
-- save_customer REPLACES the record rather than patching it. That is a decision and it is the
-- screen's shape: the customer page holds the whole record in the browser and hands all of it back,
-- so a function that treated a missing field as "leave it alone" would be answering a question the
-- caller never asks, while quietly making it impossible to clear a field. Passing NULL clears it,
-- which is what the person did when they emptied the box.
--
-- The commercial half — the credit limit, the terms, the price list, the discount agreement, the
-- billing address — is in the same function rather than a second one, because the policy on customer
-- already says only may_see_money() may write the table at all. A welder does not reach this.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE FUNCTION save_customer(
  p_id bigint,
  p_name text,
  p_status text DEFAULT 'active',
  p_city text DEFAULT NULL,
  p_country text DEFAULT NULL,
  p_org_no text DEFAULT NULL,
  p_vat_no text DEFAULT NULL,
  p_email text DEFAULT NULL,
  p_phone text DEFAULT NULL,
  p_website text DEFAULT NULL,
  p_industry text DEFAULT NULL,
  p_customer_since date DEFAULT NULL,
  p_customer_type text DEFAULT NULL,
  p_is_preferred boolean DEFAULT false,
  p_preferred_contact text DEFAULT NULL,
  p_notes text DEFAULT NULL,
  p_credit_limit numeric DEFAULT NULL,
  p_currency text DEFAULT 'SEK',
  p_payment_terms_days int DEFAULT NULL,
  p_price_list text DEFAULT NULL,
  p_delivery_terms text DEFAULT NULL,
  p_discount_agreement text DEFAULT NULL,
  p_billing_address text DEFAULT NULL,
  p_shipping_address text DEFAULT NULL
) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  saved bigint;
  existing text;
BEGIN
  PERFORM require_session('saving a customer');
  -- Every defaulted parameter is coalesced, because a JSON null on the wire arrives as a SQL NULL
  -- and overrides the DEFAULT rather than falling back to it. That has caught this project before.
  p_status := coalesce(p_status, 'active');
  p_currency := upper(coalesce(nullif(btrim(p_currency), ''), 'SEK'));
  p_is_preferred := coalesce(p_is_preferred, false);

  IF coalesce(btrim(p_name), '') = '' THEN
    RAISE EXCEPTION 'a customer needs a name';
  END IF;

  -- The name, not the reference. Two rows called Skåne Verkstad AB is two customers as far as every
  -- report is concerned and one customer as far as anybody in the building is concerned, and the
  -- second one is made by somebody who searched, did not find it, and typed it again.
  SELECT ref INTO existing FROM customer
   WHERE lower(btrim(name)) = lower(btrim(p_name))
     AND (p_id IS NULL OR id <> p_id)
   LIMIT 1;
  IF existing IS NOT NULL THEN
    RAISE EXCEPTION 'there is already a customer called % — it is %', btrim(p_name), existing;
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO customer (name, status, city, country, org_no, vat_no, email, phone, website,
                          industry, customer_since, customer_type, is_preferred, preferred_contact,
                          notes, credit_limit, currency, payment_terms_days, price_list,
                          delivery_terms, discount_agreement, billing_address, shipping_address)
    VALUES (btrim(p_name), p_status, p_city, p_country, p_org_no, p_vat_no, p_email, p_phone,
            p_website, p_industry, p_customer_since, p_customer_type, p_is_preferred,
            p_preferred_contact, p_notes, p_credit_limit, p_currency, p_payment_terms_days,
            p_price_list, p_delivery_terms, p_discount_agreement, p_billing_address,
            p_shipping_address)
    RETURNING id INTO saved;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    VALUES ('customer', saved, 'created', current_app_name(), btrim(p_name));
  ELSE
    UPDATE customer SET
      name = btrim(p_name), status = p_status, city = p_city, country = p_country,
      org_no = p_org_no, vat_no = p_vat_no, email = p_email, phone = p_phone, website = p_website,
      industry = p_industry, customer_since = p_customer_since, customer_type = p_customer_type,
      is_preferred = p_is_preferred, preferred_contact = p_preferred_contact, notes = p_notes,
      credit_limit = p_credit_limit,
      currency = p_currency, payment_terms_days = p_payment_terms_days, price_list = p_price_list,
      delivery_terms = p_delivery_terms, discount_agreement = p_discount_agreement,
      billing_address = p_billing_address, shipping_address = p_shipping_address
     WHERE id = p_id
    RETURNING id INTO saved;
    -- Row-level security filters rather than refuses, so an UPDATE nobody is allowed to make simply
    -- changes nothing and reports success. NOT FOUND is the only thing that tells the difference.
    IF NOT FOUND THEN
      RAISE EXCEPTION 'no such customer, or it is not yours to change'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    VALUES ('customer', saved, 'updated', current_app_name(), btrim(p_name));
  END IF;
  RETURN saved;
END;
$$;

-- The whole list at once, because that is how the screen holds it: it hands back the contacts as
-- they now stand rather than telling anybody which one changed. Replacing them inside one
-- transaction is therefore the honest translation, and it is atomic — a refused list leaves the old
-- one exactly as it was rather than half of it.
CREATE FUNCTION set_customer_contacts(p_customer_id bigint, p_contacts jsonb) RETURNS int
LANGUAGE plpgsql AS $$
DECLARE
  row_in jsonb;
  mains int := 0;
  kept int := 0;
  owner text;
BEGIN
  PERFORM require_session('saving contacts');
  SELECT name INTO owner FROM customer WHERE id = p_customer_id;
  IF owner IS NULL THEN
    RAISE EXCEPTION 'no such customer, or it is not yours to change'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  p_contacts := coalesce(p_contacts, '[]'::jsonb);
  IF jsonb_typeof(p_contacts) <> 'array' THEN
    RAISE EXCEPTION 'the contacts have to arrive as a list';
  END IF;

  -- Counted before anything is written, so the refusal is a sentence rather than the name of a
  -- unique index. The index behind it is what makes the rule true; this is what makes it readable.
  FOR row_in IN SELECT * FROM jsonb_array_elements(p_contacts) LOOP
    IF coalesce(btrim(row_in->>'name'), '') = '' THEN
      RAISE EXCEPTION 'a contact needs a name';
    END IF;
    IF coalesce(btrim(row_in->>'email'), '') = '' AND coalesce(btrim(row_in->>'phone'), '') = '' THEN
      RAISE EXCEPTION 'give % an email or a telephone number — a contact nobody can reach is not one',
        btrim(row_in->>'name');
    END IF;
    IF coalesce((row_in->>'primary')::boolean, false) THEN
      mains := mains + 1;
    END IF;
  END LOOP;
  IF mains > 1 THEN
    RAISE EXCEPTION '% has one main contact, and this list has %', owner, mains;
  END IF;

  DELETE FROM customer_contact WHERE customer_id = p_customer_id;
  FOR row_in IN SELECT * FROM jsonb_array_elements(p_contacts) LOOP
    INSERT INTO customer_contact (customer_id, name, role, email, phone, is_primary)
    VALUES (p_customer_id, btrim(row_in->>'name'), nullif(btrim(coalesce(row_in->>'role', '')), ''),
            nullif(btrim(coalesce(row_in->>'email', '')), ''),
            nullif(btrim(coalesce(row_in->>'phone', '')), ''),
            coalesce((row_in->>'primary')::boolean, false));
    kept := kept + 1;
  END LOOP;

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('customer', p_customer_id, 'contacts changed', current_app_name(),
          kept::text || ' contact' || CASE WHEN kept = 1 THEN '' ELSE 's' END);
  RETURN kept;
END;
$$;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- The sales pipeline
--
-- A lead is a company nobody has dealt with yet; an opportunity is a piece of work somebody wants; a
-- tender is a formal offer of it. The chain has to stay walkable backwards — from a running project to
-- the enquiry it came from, two years later — which is what the foreign keys are for and what
-- convert_lead already protects at the customer end.
--
-- The one obligation in here that is not a convention is do-not-contact. It is the law in Sweden as
-- everywhere else, and the column enforces it on the lead. The two places somebody would actually act
-- against it are booking a follow-up on the lead and booking one against the enquiry, so both ask.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE FUNCTION save_lead(
  p_id bigint,
  p_company text,
  p_contact text DEFAULT NULL,
  p_email text DEFAULT NULL,
  p_phone text DEFAULT NULL,
  p_city text DEFAULT NULL,
  p_country text DEFAULT NULL,
  p_industry text DEFAULT NULL,
  p_company_size text DEFAULT NULL,
  p_source text DEFAULT NULL,
  p_service_wanted text DEFAULT NULL,
  p_estimated_value numeric DEFAULT NULL,
  p_priority text DEFAULT NULL,
  p_status lead_status DEFAULT 'new',
  p_owner text DEFAULT NULL,
  p_last_contact_on date DEFAULT NULL,
  p_next_follow_up_on date DEFAULT NULL,
  p_contact_preference text DEFAULT NULL,
  p_do_not_contact boolean DEFAULT false,
  p_notes text DEFAULT NULL
) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('saving a lead');
  saved bigint;
  existing text;
BEGIN
  IF coalesce(btrim(p_company), '') = '' THEN
    RAISE EXCEPTION 'a lead is a company — it needs the company''s name';
  END IF;

  -- The same enquiry entered twice is two leads to the system and one company to whoever rings them,
  -- which is how the same firm gets telephoned by two people in the same week.
  SELECT ref INTO existing FROM lead
   WHERE upper(btrim(company)) = upper(btrim(p_company)) AND (p_id IS NULL OR id <> p_id) LIMIT 1;
  IF existing IS NOT NULL THEN
    RAISE EXCEPTION 'there is already a lead for % — it is %', btrim(p_company), existing;
  END IF;

  -- The refusal the database also makes, said in a sentence first. Somebody who has asked not to be
  -- contacted cannot have a follow-up booked against them, and the constraint's name is not something
  -- whoever is looking at the screen can act on.
  IF coalesce(p_do_not_contact, false) AND p_next_follow_up_on IS NOT NULL THEN
    RAISE EXCEPTION '% has asked not to be contacted, so no follow-up can be booked against them',
      btrim(p_company) USING ERRCODE = 'check_violation';
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO lead (company, contact, email, phone, city, country, industry, company_size, source,
                      service_wanted, estimated_value, priority, status, owner, last_contact_on,
                      next_follow_up_on, contact_preference, do_not_contact, notes)
    VALUES (btrim(p_company), p_contact, p_email, p_phone, p_city, p_country, p_industry,
            p_company_size, p_source, p_service_wanted, p_estimated_value, p_priority,
            coalesce(p_status, 'new'), p_owner, p_last_contact_on, p_next_follow_up_on,
            p_contact_preference, coalesce(p_do_not_contact, false), p_notes)
    RETURNING id INTO saved;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    SELECT 'lead', l.id, 'added', who, l.ref || ' ' || l.company FROM lead l WHERE l.id = saved;
  ELSE
    -- `customer_id` and the converted status are not settable here, deliberately: a lead becomes a
    -- customer through convert_lead, which makes the customer and ties the two together in one
    -- transaction. A form that could set the status by itself could mark a lead converted to nobody.
    UPDATE lead SET
      company = btrim(p_company), contact = p_contact, email = p_email, phone = p_phone,
      city = p_city, country = p_country, industry = p_industry, company_size = p_company_size,
      source = p_source, service_wanted = p_service_wanted, estimated_value = p_estimated_value,
      priority = p_priority,
      status = CASE WHEN status = 'converted' THEN status ELSE coalesce(p_status, status) END,
      owner = p_owner, last_contact_on = p_last_contact_on, next_follow_up_on = p_next_follow_up_on,
      contact_preference = p_contact_preference, do_not_contact = coalesce(p_do_not_contact, false),
      notes = p_notes
     WHERE id = p_id
    RETURNING id INTO saved;
    IF saved IS NULL THEN
      RAISE EXCEPTION 'no such lead, or it is not yours to change'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    SELECT 'lead', l.id, 'updated', who, l.ref FROM lead l WHERE l.id = saved;
  END IF;
  RETURN saved;
END;
$$;

-- A piece of work somebody wants, at a stage on the board.
--
-- The stages are the board's own columns and a card is dragged between them, so the enum holds the
-- board's eight words rather than a tidier six — two of the board's columns had no value at all before
-- this, which means dragging a card into either of them was refused.
CREATE FUNCTION save_opportunity(
  p_id bigint,
  p_title text,
  p_customer_id bigint DEFAULT NULL,
  p_lead_id bigint DEFAULT NULL,
  p_stage opportunity_stage DEFAULT 'discovery',
  p_value numeric DEFAULT NULL,
  p_probability int DEFAULT NULL,
  p_contact text DEFAULT NULL,
  p_industry text DEFAULT NULL,
  p_services text DEFAULT NULL,
  p_scope text DEFAULT NULL,
  p_owner text DEFAULT NULL,
  p_expected_close date DEFAULT NULL,
  p_expected_decision_on date DEFAULT NULL,
  p_required_delivery_on date DEFAULT NULL,
  p_competitor text DEFAULT NULL,
  p_decision_reason text DEFAULT NULL,
  p_next_action text DEFAULT NULL,
  p_follow_up_on date DEFAULT NULL,
  p_currency text DEFAULT 'SEK'
) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('saving an enquiry');
  saved bigint;
  said_no boolean;
  whose text;
BEGIN
  IF coalesce(btrim(p_title), '') = '' THEN
    RAISE EXCEPTION 'an enquiry needs a title — what the work is';
  END IF;
  IF p_customer_id IS NULL AND p_lead_id IS NULL THEN
    RAISE EXCEPTION 'an enquiry belongs to somebody, whether they are a customer yet or not'
      USING ERRCODE = 'check_violation';
  END IF;
  -- The readable half of lost_opportunity_says_why. The most useful field in the pipeline and the one
  -- most often left empty, and it cannot be reconstructed six months later.
  IF p_stage = 'lost' AND coalesce(btrim(p_decision_reason), '') = '' THEN
    RAISE EXCEPTION 'a lost enquiry records why it was lost — it is the one field worth having'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Do-not-contact, asked where somebody would act on it. This is NOT a CHECK on `opportunity`, and the
  -- reason is written in schema.sql beside where one would have gone: a constraint that reads another
  -- table is only evaluated when this row changes, so it would hold until the moment the flag was set on
  -- the lead and then quietly stop being true. A half-checked legal obligation reads as enforced.
  IF p_lead_id IS NOT NULL AND (p_follow_up_on IS NOT NULL OR coalesce(btrim(p_next_action),'') <> '') THEN
    SELECT do_not_contact, company INTO said_no, whose FROM lead WHERE id = p_lead_id;
    IF said_no IS NULL THEN
      RAISE EXCEPTION 'no such lead' USING ERRCODE = 'foreign_key_violation';
    END IF;
    IF said_no THEN
      RAISE EXCEPTION '% has asked not to be contacted, so no next step can be booked against them',
        whose USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO opportunity (title, customer_id, lead_id, stage, value, currency, probability,
                             contact, industry, services, scope, owner, expected_close,
                             expected_decision_on, required_delivery_on, competitor,
                             decision_reason, next_action, follow_up_on)
    VALUES (btrim(p_title), p_customer_id, p_lead_id, coalesce(p_stage, 'discovery'), p_value,
            upper(coalesce(nullif(btrim(coalesce(p_currency,'')), ''), 'SEK')), p_probability,
            p_contact, p_industry, p_services, p_scope, p_owner, p_expected_close,
            p_expected_decision_on, p_required_delivery_on, p_competitor, p_decision_reason,
            p_next_action, p_follow_up_on)
    RETURNING id INTO saved;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    SELECT 'opportunity', o.id, 'raised', who, o.ref || ' ' || o.title
      FROM opportunity o WHERE o.id = saved;
  ELSE
    UPDATE opportunity SET
      title = btrim(p_title), customer_id = p_customer_id, lead_id = p_lead_id,
      stage = coalesce(p_stage, stage), value = p_value,
      currency = upper(coalesce(nullif(btrim(coalesce(p_currency,'')), ''), currency)),
      probability = p_probability, contact = p_contact, industry = p_industry, services = p_services,
      scope = p_scope, owner = p_owner, expected_close = p_expected_close,
      expected_decision_on = p_expected_decision_on, required_delivery_on = p_required_delivery_on,
      competitor = p_competitor, decision_reason = p_decision_reason, next_action = p_next_action,
      follow_up_on = p_follow_up_on
     WHERE id = p_id
    RETURNING id INTO saved;
    IF saved IS NULL THEN
      RAISE EXCEPTION 'no such enquiry, or it is not yours to change'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    SELECT 'opportunity', o.id, 'moved to ' || o.stage::text, who, o.ref
      FROM opportunity o WHERE o.id = saved;
  END IF;
  RETURN saved;
END;
$$;

-- A formal offer, and the date it went in on.
--
-- Awarded and declined both mean it went in, so all three demand the date. It is what every chase and
-- every deadline is counted from and it cannot be reconstructed afterwards.
CREATE FUNCTION save_tender(
  p_id bigint,
  p_title text,
  p_opportunity_id bigint DEFAULT NULL,
  p_customer_id bigint DEFAULT NULL,
  p_status tender_status DEFAULT 'in-progress',
  p_due_on date DEFAULT NULL,
  p_submitted_on date DEFAULT NULL,
  p_value numeric DEFAULT NULL,
  p_company text DEFAULT NULL,
  p_customer_ref text DEFAULT NULL,
  p_source text DEFAULT NULL,
  p_industry text DEFAULT NULL,
  p_description text DEFAULT NULL,
  p_requirements text DEFAULT NULL,
  p_responsible text DEFAULT NULL,
  p_bid_decision text DEFAULT 'pending',
  p_reminder_on date DEFAULT NULL
) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('saving a tender');
  saved bigint;
BEGIN
  IF coalesce(btrim(p_title), '') = '' THEN
    RAISE EXCEPTION 'a tender needs a title';
  END IF;
  IF p_status IN ('submitted', 'awarded', 'declined') AND p_submitted_on IS NULL THEN
    RAISE EXCEPTION 'a tender recorded as % has gone in — it needs the date it went in on', p_status
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_customer_id IS NULL AND p_opportunity_id IS NULL
     AND coalesce(btrim(p_company), '') = '' THEN
    RAISE EXCEPTION 'a tender is from somebody — name the company, or the customer or enquiry it belongs to'
      USING ERRCODE = 'check_violation';
  END IF;
  IF coalesce(p_bid_decision, 'pending') = 'no-bid' AND p_status IN ('submitted', 'awarded') THEN
    RAISE EXCEPTION 'this tender is marked no-bid, so it cannot also be recorded as %', p_status
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO tender (title, opportunity_id, customer_id, status, due_on, submitted_on, value,
                        company, customer_ref, source, industry, description, requirements,
                        responsible, bid_decision, reminder_on)
    VALUES (btrim(p_title), p_opportunity_id, p_customer_id, coalesce(p_status, 'in-progress'),
            p_due_on, p_submitted_on, p_value, p_company, p_customer_ref, p_source, p_industry,
            p_description, p_requirements, p_responsible, coalesce(p_bid_decision, 'pending'),
            p_reminder_on)
    RETURNING id INTO saved;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    SELECT 'tender', t.id, 'raised', who, t.ref || ' ' || t.title FROM tender t WHERE t.id = saved;
  ELSE
    -- project_id is not settable here. The link from a tender to the work it became is written by
    -- whatever turns the one into the other, and a form that could type it in could point a tender at
    -- somebody else's project — which is the join the whole chain back is walked along.
    UPDATE tender SET
      title = btrim(p_title), opportunity_id = p_opportunity_id, customer_id = p_customer_id,
      status = coalesce(p_status, status), due_on = p_due_on, submitted_on = p_submitted_on,
      value = p_value, company = p_company, customer_ref = p_customer_ref, source = p_source,
      industry = p_industry, description = p_description, requirements = p_requirements,
      responsible = p_responsible, bid_decision = coalesce(p_bid_decision, bid_decision),
      reminder_on = p_reminder_on
     WHERE id = p_id
    RETURNING id INTO saved;
    IF saved IS NULL THEN
      RAISE EXCEPTION 'no such tender, or it is not yours to change'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    SELECT 'tender', t.id, t.status::text, who, t.ref FROM tender t WHERE t.id = saved;
  END IF;
  RETURN saved;
END;
$$;

-- Something found out about a prospect — a planning application, a new plant, a piece of news — and what
-- was done about it.
--
-- Recording one is append-only: `prospect_finding` has no status and that is deliberate. Acting on a
-- finding is acting on the lead, which is what the two functions below do; the finding itself is what was
-- found, and that does not change afterwards.
CREATE FUNCTION record_prospect_finding(p_lead_id bigint, p_finding text, p_source text DEFAULT NULL)
RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('recording what was found out about a prospect');
  said text := btrim(coalesce(p_finding, ''));
  made bigint;
BEGIN
  IF said = '' THEN
    RAISE EXCEPTION 'a finding has to say what was found' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM lead WHERE id = p_lead_id) THEN
    RAISE EXCEPTION 'no such lead' USING ERRCODE = 'foreign_key_violation';
  END IF;
  INSERT INTO prospect_finding (lead_id, finding, source, found_by)
  VALUES (p_lead_id, said, p_source, who)
  RETURNING id INTO made;
  RETURN made;
END;
$$;

-- Acted on, or set aside. Both move the lead rather than the finding: taking a finding forward means the
-- lead is worth speaking to, and setting it aside means it is not — and both are recorded against the
-- lead, where whoever picks it up next will look.
CREATE FUNCTION act_on_prospect_finding(p_finding_id bigint, p_take_it boolean, p_why text DEFAULT NULL)
RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('acting on what was found out about a prospect');
  found record;
  said text := nullif(btrim(coalesce(p_why, '')), '');
BEGIN
  SELECT f.id, f.finding, f.lead_id, l.ref, l.company, l.do_not_contact, l.status
    INTO found
    FROM prospect_finding f JOIN lead l ON l.id = f.lead_id
   WHERE f.id = p_finding_id;
  IF found.id IS NULL THEN
    RAISE EXCEPTION 'no such finding' USING ERRCODE = 'foreign_key_violation';
  END IF;

  IF coalesce(p_take_it, false) THEN
    IF found.do_not_contact THEN
      RAISE EXCEPTION '% has asked not to be contacted — a finding about them is not a reason to ring',
        found.company USING ERRCODE = 'check_violation';
    END IF;
    -- A finding worth acting on makes the lead worth speaking to. A converted lead is left where it is:
    -- they are a customer now, and moving them back to 'contacted' would lose that.
    UPDATE lead SET status = CASE WHEN status IN ('new', 'disqualified') THEN 'contacted'::lead_status
                                 ELSE status END
     WHERE id = found.lead_id;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    VALUES ('lead', found.lead_id, 'finding taken forward', who,
            found.finding || coalesce(' — ' || said, ''));
    RETURN 'taken forward';
  END IF;

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('lead', found.lead_id, 'finding set aside', who,
          found.finding || coalesce(' — ' || said, ''));
  RETURN 'set aside';
END;
$$;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Suppliers
--
-- The merchants a workshop buys from. Thin on purpose: what a supplier costs this workshop is on the
-- orders and the price list, not here — and the one figure here that is a commercial term, the payment
-- terms, is withheld from the floor the same way a customer's price list is.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE FUNCTION save_supplier(
  p_id bigint,
  p_name text,
  p_category text DEFAULT NULL,
  p_status text DEFAULT 'active',
  p_org_no text DEFAULT NULL,
  p_vat_no text DEFAULT NULL,
  p_email text DEFAULT NULL,
  p_phone text DEFAULT NULL,
  p_website text DEFAULT NULL,
  p_address text DEFAULT NULL,
  p_city text DEFAULT NULL,
  p_country text DEFAULT NULL,
  p_supplier_type text DEFAULT NULL,
  p_established text DEFAULT NULL,
  p_delivery_terms text DEFAULT NULL,
  p_minimum_order text DEFAULT NULL,
  p_currency text DEFAULT 'SEK',
  p_rating numeric DEFAULT NULL,
  p_payment_terms_days int DEFAULT NULL,
  p_notes text DEFAULT NULL
) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('saving a supplier');
  saved bigint;
  existing text;
BEGIN
  IF coalesce(btrim(p_name), '') = '' THEN
    RAISE EXCEPTION 'a supplier needs a name — it is what every order and certificate points back to';
  END IF;

  -- Two rows under one name is two merchants to the system and one to whoever is ringing them, which is
  -- how half a supplier's orders end up invisible on the register that is supposed to show them. Asked
  -- case-insensitively because 'Stål & Metall AB' and 'STÅL & METALL AB' are one company.
  SELECT ref INTO existing FROM supplier
   WHERE upper(btrim(name)) = upper(btrim(p_name)) AND (p_id IS NULL OR id <> p_id) LIMIT 1;
  IF existing IS NOT NULL THEN
    RAISE EXCEPTION 'there is already a supplier called % — it is %', btrim(p_name), existing;
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO supplier (name, category, status, org_no, vat_no, email, phone, website, address,
                          city, country, supplier_type, established, delivery_terms, minimum_order,
                          currency, rating, payment_terms_days, notes)
    VALUES (btrim(p_name), p_category, coalesce(p_status, 'active'), p_org_no, p_vat_no, p_email,
            p_phone, p_website, p_address, p_city, p_country, p_supplier_type, p_established,
            p_delivery_terms, p_minimum_order, upper(coalesce(nullif(btrim(coalesce(p_currency,'')), ''), 'SEK')),
            p_rating, p_payment_terms_days, p_notes)
    RETURNING id INTO saved;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    SELECT 'supplier', s.id, 'added', who, s.ref || ' ' || s.name FROM supplier s WHERE s.id = saved;
  ELSE
    UPDATE supplier SET
      name = btrim(p_name), category = p_category, status = coalesce(p_status, status),
      org_no = p_org_no, vat_no = p_vat_no, email = p_email, phone = p_phone, website = p_website,
      address = p_address, city = p_city, country = p_country, supplier_type = p_supplier_type,
      established = p_established, delivery_terms = p_delivery_terms,
      minimum_order = p_minimum_order,
      currency = upper(coalesce(nullif(btrim(coalesce(p_currency,'')), ''), currency)),
      -- The rating goes where it is put, NULL included. Nobody having rated a merchant is a real state
      -- and it has to be settable back: a coalesce here would mean a rating could be given and never
      -- taken away, which for a judgement about somebody's company is the wrong direction.
      rating = p_rating, payment_terms_days = p_payment_terms_days, notes = p_notes
     WHERE id = p_id
    RETURNING id INTO saved;
    IF saved IS NULL THEN
      RAISE EXCEPTION 'no such supplier, or it is not yours to change'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    SELECT 'supplier', s.id, 'updated', who, s.ref FROM supplier s WHERE s.id = saved;
  END IF;
  RETURN saved;
END;
$$;

-- The people at the merchant, replaced wholesale — the same shape as set_customer_contacts and for the
-- same reason: the screen holds a list and a patch-by-row API turns one edit into three calls, any of
-- which can be the one that does not arrive.
CREATE FUNCTION set_supplier_contacts(p_supplier_id bigint, p_contacts jsonb) RETURNS int
LANGUAGE plpgsql AS $$
DECLARE
  row_in jsonb;
  mains int := 0;
  kept int := 0;
  merchant text;
BEGIN
  PERFORM require_session('saving supplier contacts');
  SELECT name INTO merchant FROM supplier WHERE id = p_supplier_id;
  IF merchant IS NULL THEN
    RAISE EXCEPTION 'no such supplier, or it is not yours to change'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  p_contacts := coalesce(p_contacts, '[]'::jsonb);
  IF jsonb_typeof(p_contacts) <> 'array' THEN
    RAISE EXCEPTION 'the contacts have to arrive as a list';
  END IF;

  -- Checked before anything is written, so the refusal is a sentence rather than the name of a unique
  -- index. The index is what makes the rule true; this is what makes it readable.
  FOR row_in IN SELECT * FROM jsonb_array_elements(p_contacts) LOOP
    IF coalesce(btrim(row_in->>'name'), '') = '' THEN
      RAISE EXCEPTION 'a contact needs a name';
    END IF;
    IF coalesce(btrim(row_in->>'email'), '') = '' AND coalesce(btrim(row_in->>'phone'), '') = '' THEN
      RAISE EXCEPTION 'give % an email or a telephone number — a contact nobody can reach is not one',
        btrim(row_in->>'name');
    END IF;
    IF coalesce((row_in->>'primary')::boolean, false) THEN
      mains := mains + 1;
    END IF;
  END LOOP;
  IF mains > 1 THEN
    RAISE EXCEPTION '% has one main contact, and this list has %', merchant, mains;
  END IF;

  DELETE FROM supplier_contact WHERE supplier_id = p_supplier_id;
  FOR row_in IN SELECT * FROM jsonb_array_elements(p_contacts) LOOP
    INSERT INTO supplier_contact (supplier_id, name, role, email, phone, is_primary)
    VALUES (p_supplier_id, btrim(row_in->>'name'), nullif(btrim(coalesce(row_in->>'role', '')), ''),
            nullif(btrim(coalesce(row_in->>'email', '')), ''),
            nullif(btrim(coalesce(row_in->>'phone', '')), ''),
            coalesce((row_in->>'primary')::boolean, false));
    kept := kept + 1;
  END LOOP;

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('supplier', p_supplier_id, 'contacts changed', current_app_name(),
          kept::text || ' contact' || CASE WHEN kept = 1 THEN '' ELSE 's' END);
  RETURN kept;
END;
$$;

-- A note against a merchant, into the audit trail rather than a notes column, for the reason a quality
-- note goes there: a note somebody can quietly edit afterwards is worth less than no note at all, and
-- that table is append-only by trigger. The `notes` column on supplier is a different thing — it is the
-- standing description of the merchant, not a dated entry.
CREATE FUNCTION add_supplier_note(p_supplier_id bigint, p_text text) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('adding a supplier note');
  said text := btrim(coalesce(p_text, ''));
  made bigint;
BEGIN
  IF said = '' THEN
    RAISE EXCEPTION 'an empty note is not a note' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM supplier WHERE id = p_supplier_id) THEN
    RAISE EXCEPTION 'no such supplier' USING ERRCODE = 'foreign_key_violation';
  END IF;
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('supplier', p_supplier_id, 'note', who, said)
  RETURNING id INTO made;
  RETURN made;
END;
$$;

-- What a merchant sells, and at what price. One row per item per supplier, which is what makes "who do
-- we buy this from and what did they quote" answerable for a plate two merchants both stock.
--
-- The price is here rather than on the item for exactly that reason, and it is why this function is the
-- office's: a price list is a price.
CREATE FUNCTION save_supplier_item(
  p_supplier_id bigint,
  p_stock_item_id bigint,
  p_price numeric,
  p_article_no text DEFAULT NULL,
  p_currency text DEFAULT 'SEK',
  p_pack_size numeric DEFAULT 1,
  p_lead_time_days int DEFAULT NULL,
  -- NULL means "leave it as it is", which is not the same as false.
  --
  -- It used to default to false, and a mutation found what that meant: correcting a merchant's price —
  -- `save_supplier_item(them, item, 14.10, 'ST-10-S355')`, with no flag because the price is what
  -- changed — silently stopped them being the merchant this workshop buys that item from. Nothing said
  -- so. The next person to ask "who do we buy this from" got no answer at all.
  p_is_preferred boolean DEFAULT NULL
) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('saving a supplier price');
  saved bigint;
BEGIN
  IF p_price IS NULL OR p_price < 0 THEN
    RAISE EXCEPTION 'a price list line needs a price' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM supplier WHERE id = p_supplier_id) THEN
    RAISE EXCEPTION 'no such supplier' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM stock_item WHERE id = p_stock_item_id) THEN
    RAISE EXCEPTION 'no such item' USING ERRCODE = 'foreign_key_violation';
  END IF;

  -- Preferred is one merchant per item, and the partial unique index refuses the second. Cleared here
  -- rather than left to fail, because "we buy this from them now" is the whole point of the flag and a
  -- refusal would make changing your mind impossible.
  IF coalesce(p_is_preferred, false) THEN
    UPDATE supplier_item SET is_preferred = false
     WHERE stock_item_id = p_stock_item_id AND supplier_id <> p_supplier_id AND is_preferred;
  END IF;

  INSERT INTO supplier_item (supplier_id, stock_item_id, article_no, price, currency, pack_size,
                             lead_time_days, is_preferred, updated_at)
  VALUES (p_supplier_id, p_stock_item_id, p_article_no, p_price,
          upper(coalesce(nullif(btrim(coalesce(p_currency,'')), ''), 'SEK')),
          coalesce(p_pack_size, 1), p_lead_time_days, coalesce(p_is_preferred, false), now())
  ON CONFLICT (supplier_id, stock_item_id) DO UPDATE SET
    article_no = excluded.article_no, price = excluded.price, currency = excluded.currency,
    pack_size = excluded.pack_size, lead_time_days = excluded.lead_time_days,
    -- Read off the parameter rather than `excluded`, because excluded already holds the coalesced value
    -- and cannot tell "not preferred" from "nobody said". Who this workshop buys an item from is a
    -- decision, and a price correction is not one.
    is_preferred = CASE WHEN p_is_preferred IS NULL THEN supplier_item.is_preferred
                        ELSE p_is_preferred END,
    updated_at = now()
  RETURNING id INTO saved;

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  SELECT 'supplier', p_supplier_id, 'price list', who,
         (SELECT code FROM stock_item WHERE id = p_stock_item_id) || ' at ' || p_price::text
    FROM supplier WHERE id = p_supplier_id;
  RETURN saved;
END;
$$;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- Quality
--
-- A hold is the only thing in this system that physically stops work leaving the building, so the
-- rules about putting one on and taking one off are in here rather than in the page that happens to
-- be showing the button.
-- ─────────────────────────────────────────────────────────────────────────────────────────────

-- Put a hold on.
--
-- Which of project or jobcard it names is worked out from what it is given rather than taken as a
-- scope word, because the two have to agree — `hold_names_one_thing` refuses a hold whose scope says
-- project and whose only reference is a jobcard, and a caller that can get that wrong will.
--
-- A hold naming nothing is refused outright. The application's own hold code had a third scope,
-- 'other', for exactly that case; a hold scoped to 'other' cannot appear in any gate, so it stops
-- nothing while looking on the screen exactly like one that does. The honest answer is to say so at
-- the point somebody tries to place it.
--
-- An identical active hold is reused rather than duplicated: same thing held, same reason. Automatic
-- holds fire from a failed inspection and again from the NCR raised about it, and two rows saying one
-- thing means releasing the hold leaves the work still held by its twin. A hold on the same jobcard
-- for a genuinely different reason is a different hold and still gets its own row.
CREATE FUNCTION place_hold(
  p_project_id bigint,
  p_jobcard_id bigint,
  p_reason text,
  p_severity severity DEFAULT 'major',
  p_required_action text DEFAULT NULL,
  p_related_ref text DEFAULT NULL
) RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('placing a quality hold');
  -- Named `why` rather than `reason`: inside the SELECT below, a variable called `reason` and the
  -- column called `reason` are the same word, and Postgres refuses the statement as ambiguous.
  why text := btrim(coalesce(p_reason, ''));
  on_project bigint := p_project_id;
  on_jobcard bigint := p_jobcard_id;
  existing text;
  made text;
BEGIN
  IF why = '' THEN
    RAISE EXCEPTION 'a hold has to say what it is for — it is the only thing the person it stops can read'
      USING ERRCODE = 'check_violation';
  END IF;
  -- A jobcard is the narrower thing, so a hold given both holds the jobcard.
  IF on_jobcard IS NOT NULL THEN
    on_project := NULL;
  ELSIF on_project IS NULL THEN
    RAISE EXCEPTION 'a hold has to name a project or a jobcard — one that names nothing stops nothing'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT ref INTO existing FROM quality_hold
   WHERE status = 'active' AND btrim(reason) = why
     AND jobcard_id IS NOT DISTINCT FROM on_jobcard
     AND project_id IS NOT DISTINCT FROM on_project
   LIMIT 1;
  IF existing IS NOT NULL THEN
    RETURN existing;
  END IF;

  INSERT INTO quality_hold (scope, project_id, jobcard_id, reason, severity, applied_by,
                            required_action, related_ref)
  VALUES (CASE WHEN on_jobcard IS NOT NULL THEN 'jobcard' ELSE 'project' END::hold_scope,
          on_project, on_jobcard, why, p_severity, who, p_required_action, p_related_ref)
  RETURNING ref INTO made;

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  SELECT 'quality_hold', h.id, 'applied', who, made || ' — ' || why
    FROM quality_hold h WHERE h.ref = made;
  RETURN made;
END;
$$;

-- Take a hold off. The one decision in this system that lets work leave the building.
--
-- Requires a named authority and written evidence, and the database requires them too
-- (`release_needs_evidence`) — this raises the readable version of that refusal first. It releases
-- exactly the one hold it is given and touches nothing else: not the jobcard, not the project, not
-- another hold on the same work. After a release somebody retries the move that was blocked, and if
-- a second hold is still on it, it is still blocked, which is the point.
CREATE FUNCTION release_hold(p_hold_id bigint, p_authority text, p_reason text) RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('releasing a quality hold');
  authority text := btrim(coalesce(p_authority, ''));
  -- `why` rather than `reason`, for the reason place_hold gives: a variable sharing a name with a
  -- column of the table being written is ambiguous and the statement is refused.
  why text := btrim(coalesce(p_reason, ''));
  held record;
BEGIN
  SELECT id, ref, status INTO held FROM quality_hold WHERE id = p_hold_id;
  IF held.id IS NULL THEN
    RAISE EXCEPTION 'no such hold' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF authority = '' OR why = '' THEN
    RAISE EXCEPTION 'releasing a hold takes an authorised approval and written evidence of what was resolved'
      USING ERRCODE = 'check_violation';
  END IF;
  -- Releasing an already-released hold is not harmless. It would restamp the authority and the date,
  -- so the record would say the second person released it and the first release would be gone.
  IF held.status = 'released' THEN
    RAISE EXCEPTION 'hold % has already been released', held.ref USING ERRCODE = 'check_violation';
  END IF;

  UPDATE quality_hold SET status = 'released', release_authority = authority,
         release_reason = why, released_at = now()
   WHERE id = held.id;

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('quality_hold', held.id, 'released', who, held.ref || ' — ' || authority || ': ' || why);
  RETURN held.ref;
END;
$$;

-- An inspection is asked for: what is to be checked, against which drawing, to what criteria, by when.
--
-- The result is not here, and that is the whole shape of the thing. An inspection request that could
-- arrive already passed is a form for passing work without looking at it.
CREATE FUNCTION save_inspection(
  p_id bigint,
  p_project_id bigint,
  p_jobcard_id bigint,
  p_kind text,
  p_operation text DEFAULT NULL,
  p_component text DEFAULT NULL,
  p_drawing_no text DEFAULT NULL,
  p_drawing_rev text DEFAULT NULL,
  p_method text DEFAULT NULL,
  p_acceptance_criteria text DEFAULT NULL,
  p_customer_witness boolean DEFAULT false,
  p_material_traceability_ok boolean DEFAULT false,
  p_planned_date date DEFAULT NULL,
  p_inspector text DEFAULT NULL,
  p_status text DEFAULT 'requested',
  p_notes text DEFAULT NULL
) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('raising an inspection');
  saved bigint;
  locked text;
BEGIN
  IF coalesce(btrim(p_kind), '') = '' THEN
    RAISE EXCEPTION 'an inspection has to say what kind of check it is';
  END IF;
  IF p_project_id IS NULL AND p_jobcard_id IS NULL THEN
    RAISE EXCEPTION 'an inspection has to be of something — a project or a jobcard'
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_planned_date IS NULL THEN
    RAISE EXCEPTION 'an inspection needs a date it is planned for, or it is a note rather than a plan'
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO inspection (project_id, jobcard_id, kind, operation, component, drawing_no,
                            drawing_rev, method, acceptance_criteria, customer_witness,
                            material_traceability_ok, planned_date, inspector, status, notes)
    VALUES (p_project_id, p_jobcard_id, btrim(p_kind), p_operation, p_component, p_drawing_no,
            p_drawing_rev, p_method, p_acceptance_criteria, coalesce(p_customer_witness, false),
            coalesce(p_material_traceability_ok, false), p_planned_date, p_inspector,
            coalesce(p_status, 'requested'), p_notes)
    RETURNING id INTO saved;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    SELECT 'inspection', i.id, 'raised', who, i.ref || ' — ' || i.kind
      FROM inspection i WHERE i.id = saved;
  ELSE
    -- What was found is not editable through the form that asks for the check. Re-opening a decided
    -- inspection to change its drawing number would leave the result standing against a different
    -- drawing, which is the one way a passed inspection can become evidence of nothing.
    SELECT ref INTO locked FROM inspection WHERE id = p_id AND result <> 'pending';
    IF locked IS NOT NULL THEN
      RAISE EXCEPTION 'inspection % already has a result — raise a re-inspection rather than editing it',
        locked USING ERRCODE = 'check_violation';
    END IF;
    UPDATE inspection SET
      project_id = p_project_id, jobcard_id = p_jobcard_id, kind = btrim(p_kind),
      operation = p_operation, component = p_component, drawing_no = p_drawing_no,
      drawing_rev = p_drawing_rev, method = p_method, acceptance_criteria = p_acceptance_criteria,
      customer_witness = coalesce(p_customer_witness, false),
      material_traceability_ok = coalesce(p_material_traceability_ok, false),
      planned_date = p_planned_date, inspector = p_inspector,
      status = coalesce(p_status, status), notes = p_notes
     WHERE id = p_id
    RETURNING id INTO saved;
    IF saved IS NULL THEN
      RAISE EXCEPTION 'no such inspection, or it is not yours to change'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    SELECT 'inspection', i.id, 'updated', who, i.ref FROM inspection i WHERE i.id = saved;
  END IF;
  RETURN saved;
END;
$$;

-- The checklist, replaced wholesale. Shared by completing an inspection and by raising the
-- re-inspection that repeats it.
--
-- An empty string for the verdict arrives as NULL, because '' and "nobody has answered this line" are
-- the same fact and two spellings of it is how a blank line gets counted as a pass.
CREATE FUNCTION replace_inspection_checks(p_inspection_id bigint, p_lines jsonb) RETURNS int
LANGUAGE plpgsql AS $$
DECLARE
  written int := 0;
BEGIN
  DELETE FROM inspection_check WHERE inspection_id = p_inspection_id;
  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' THEN
    RETURN 0;
  END IF;
  INSERT INTO inspection_check (inspection_id, line_no, item, result, nominal, tol_lower, tol_upper,
                                actual, note)
  SELECT p_inspection_id, ordinality,
         btrim(line->>'item'),
         nullif(btrim(coalesce(line->>'result', '')), ''),
         (line->>'nominal')::numeric, (line->>'lower')::numeric, (line->>'upper')::numeric,
         (line->>'actual')::numeric, line->>'note'
    FROM jsonb_array_elements(p_lines) WITH ORDINALITY AS t(line, ordinality)
   WHERE btrim(coalesce(line->>'item', '')) <> '';
  GET DIAGNOSTICS written = ROW_COUNT;
  RETURN written;
END;
$$;

-- What the inspector found, and what follows from it.
--
-- Three things happen here and they belong together in one transaction: the result and its evidence
-- are written, and a critical failure puts a hold on the work. Leaving the hold to the caller is how
-- a failed inspection gets recorded and the work ships anyway, because the second call was the one
-- that did not arrive.
--
-- `inspector` is taken from the session and overwrites whoever the request was planned for. On a
-- completed inspection that column is the person answerable for the result, and that can only be
-- whoever was signed in when it was recorded — the same rule a service record already follows. Until
-- it is completed the column holds who it is planned for, which is a different question.
CREATE FUNCTION complete_inspection(
  p_id bigint,
  p_result inspection_result,
  p_findings text DEFAULT NULL,
  p_critical boolean DEFAULT false,
  p_checks jsonb DEFAULT NULL,
  p_actual_date date DEFAULT NULL,
  p_event_id text DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('recording an inspection result');
  seen text := already_done(p_event_id, 'complete_inspection');
  found record;
  on_day date := coalesce(p_actual_date, current_date);
  held text := NULL;
  answer jsonb;
BEGIN
  IF seen IS NOT NULL THEN
    RETURN seen::jsonb;
  END IF;

  SELECT id, ref, result, project_id, jobcard_id INTO found FROM inspection WHERE id = p_id;
  IF found.id IS NULL THEN
    RAISE EXCEPTION 'no such inspection' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF p_result = 'pending' THEN
    RAISE EXCEPTION 'completing an inspection takes a result — pending is what it already says'
      USING ERRCODE = 'check_violation';
  END IF;
  IF found.result <> 'pending' THEN
    RAISE EXCEPTION 'inspection % was already decided as %; a second look is a re-inspection',
      found.ref, found.result USING ERRCODE = 'check_violation';
  END IF;
  IF p_result = 'passed-observations' AND coalesce(btrim(p_findings), '') = '' THEN
    RAISE EXCEPTION 'passed with observations is the result that says there is something to say'
      USING ERRCODE = 'check_violation';
  END IF;
  IF on_day > current_date THEN
    RAISE EXCEPTION 'an inspection cannot have happened on a date that has not arrived'
      USING ERRCODE = 'check_violation';
  END IF;

  -- The evidence goes in before the verdict, and the order is load-bearing rather than tidy: the
  -- floor's policy on the checklist lets a line be written only while its inspection is still
  -- undecided. Written the other way round, a welder's own checklist would be refused by the row
  -- security a statement earlier in the same transaction had just made apply to it.
  PERFORM replace_inspection_checks(found.id, p_checks);

  UPDATE inspection SET
    result = p_result, findings = p_findings, critical = coalesce(p_critical, false),
    actual_date = CASE WHEN p_result = 'not-applicable' THEN NULL ELSE on_day END,
    inspector = who,
    status = CASE WHEN p_result = 'not-applicable' THEN 'cancelled' ELSE 'completed' END
   WHERE id = found.id;

  -- Read back off the row rather than from the parameters, so the hold quotes what was actually
  -- recorded. Returns NULL for anything that is not a critical failure, including the ordinary case.
  held := hold_after_failed_inspection(found.id);

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('inspection', found.id, p_result::text, who,
          found.ref || coalesce(' — ' || nullif(btrim(coalesce(p_findings, '')), ''), '') ||
          coalesce(' — held under ' || held, ''));

  answer := jsonb_build_object('inspection', found.ref, 'hold', held);
  PERFORM record_result(p_event_id, answer::text);
  RETURN answer;
END;
$$;

-- The weld was ground out and re-run. This is the second look.
--
-- A copy of the original with the result cleared and a link back to it, so the history of a rejected
-- weld reads as one story rather than two unrelated checks. The checklist comes across with every
-- verdict blanked: a re-inspection that arrives pre-passed on the first inspection's answers is the
-- exact failure this whole record exists to prevent.
CREATE FUNCTION create_reinspection(p_id bigint) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('raising a re-inspection');
  original record;
  made bigint;
BEGIN
  SELECT * INTO original FROM inspection WHERE id = p_id;
  IF original.id IS NULL THEN
    RAISE EXCEPTION 'no such inspection' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF original.result = 'pending' THEN
    RAISE EXCEPTION 'inspection % has not been decided yet — there is nothing to repeat', original.ref
      USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO inspection (project_id, jobcard_id, kind, operation, component, drawing_no, drawing_rev,
                          method, acceptance_criteria, customer_witness, material_traceability_ok,
                          planned_date, inspector, status, reinspection_of, notes)
  VALUES (original.project_id, original.jobcard_id, original.kind, original.operation,
          original.component, original.drawing_no, original.drawing_rev, original.method,
          original.acceptance_criteria, original.customer_witness, original.material_traceability_ok,
          current_date, original.inspector, 'planned', original.id, original.notes)
  RETURNING id INTO made;

  INSERT INTO inspection_check (inspection_id, line_no, item, nominal, tol_lower, tol_upper)
  SELECT made, line_no, item, nominal, tol_lower, tol_upper
    FROM inspection_check WHERE inspection_id = original.id ORDER BY line_no;

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  SELECT 'inspection', made, 'raised as a re-inspection', who, i.ref || ' repeats ' || original.ref
    FROM inspection i WHERE i.id = made;
  RETURN made;
END;
$$;

-- The hold that follows a critical failed inspection, and the only route by which the floor ever
-- places one.
--
-- Split out and run as varmak_engine for the same reason equipment_state_after_event is: a welder
-- recording what they found must not be able to put an arbitrary hold on arbitrary work — releasing a
-- hold is the office's decision and placing one is most of the way there — but the hold that follows
-- automatically from a critical failure they have just recorded is the system's decision, not theirs.
--
-- Without this split the welder's transaction fails at the hold: no INSERT grant on quality_hold for
-- the floor, and `only_the_office_holds` behind it. The whole transaction rolls back, so the failed
-- inspection is not recorded either — the shop ends up with neither the hold nor the finding, which is
-- worse than either one alone. That is the "a GRANT with no policy behind it fails closed, which is
-- safe and still the wrong answer" shape, met a second time.
--
-- It reads the inspection rather than taking a reason, so there is nothing to pass: it can only place
-- a hold that quotes an inspection which is, right now, failed and marked critical. Called with
-- anything else it does nothing and says so by returning NULL.
CREATE FUNCTION hold_after_failed_inspection(p_inspection_id bigint) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  found record;
  existing text;
  why text;
  held bigint;
  made text;
BEGIN
  SELECT id, ref, result, critical, project_id, jobcard_id, findings, inspector
    INTO found FROM inspection WHERE id = p_inspection_id;
  IF found.id IS NULL OR found.result <> 'failed' OR NOT found.critical THEN
    RETURN NULL;
  END IF;
  IF found.project_id IS NULL AND found.jobcard_id IS NULL THEN
    RETURN NULL;
  END IF;

  why := 'Critical failed inspection ' || found.ref || ' — ' ||
         coalesce(nullif(btrim(coalesce(found.findings, '')), ''), 'see the inspection record');

  SELECT ref INTO existing FROM quality_hold
   WHERE status = 'active' AND btrim(reason) = why
     AND jobcard_id IS NOT DISTINCT FROM CASE WHEN found.jobcard_id IS NOT NULL
                                              THEN found.jobcard_id END
     AND project_id IS NOT DISTINCT FROM CASE WHEN found.jobcard_id IS NULL
                                              THEN found.project_id END
   LIMIT 1;
  IF existing IS NOT NULL THEN
    RETURN existing;
  END IF;

  INSERT INTO quality_hold (scope, project_id, jobcard_id, reason, severity, applied_by,
                            required_action, related_ref)
  VALUES (CASE WHEN found.jobcard_id IS NOT NULL THEN 'jobcard' ELSE 'project' END::hold_scope,
          CASE WHEN found.jobcard_id IS NULL THEN found.project_id END,
          found.jobcard_id, why, 'critical', coalesce(found.inspector, 'system'),
          'Corrective action and re-inspection required.', found.ref)
  RETURNING id, ref INTO held, made;

  -- The hold's own history, the same entry place_hold writes. Without it the holds with the least
  -- explanation on the screen would be exactly the ones that matter most: an office hold shows who
  -- applied it and why, and an automatic one would show an empty panel.
  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('quality_hold', held, 'applied', coalesce(found.inspector, 'system'), made || ' — ' || why);
  RETURN made;
END;
$$;

-- A non-conformance, raised.
--
-- Who found it comes from the session, never from the form. The screen it is typed on had the name
-- written into the page — every NCR raised on that machine would have been found by the same person,
-- whoever was actually standing there.
--
-- A critical one puts a hold on by itself, in this transaction. Same reason completing a failed
-- inspection does: the hold that depends on a second call is the hold that is missing when the lorry
-- is loaded.
CREATE FUNCTION save_ncr(
  p_id bigint,
  p_title text,
  p_project_id bigint,
  p_jobcard_id bigint,
  p_category text,
  p_severity severity,
  p_description text,
  p_responsible text,
  p_due_on date DEFAULT NULL,
  p_operation text DEFAULT NULL,
  p_component text DEFAULT NULL,
  p_material text DEFAULT NULL,
  p_supplier_id bigint DEFAULT NULL,
  p_notes text DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('raising a non-conformance');
  saved bigint;
  raised text;
  held text := NULL;
BEGIN
  IF coalesce(btrim(p_title), '') = '' THEN
    RAISE EXCEPTION 'a non-conformance needs a title — it is what the register is read by';
  END IF;
  IF coalesce(btrim(p_description), '') = '' THEN
    RAISE EXCEPTION 'a non-conformance needs a description of what is wrong';
  END IF;
  IF coalesce(btrim(p_responsible), '') = '' THEN
    RAISE EXCEPTION 'a non-conformance needs somebody answerable for it';
  END IF;
  IF p_severity <> 'minor' AND p_due_on IS NULL THEN
    RAISE EXCEPTION 'a % non-conformance needs a date by which it is answered', p_severity
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO ncr (title, project_id, jobcard_id, category, severity, description, responsible,
                     detected_by, due_on, operation, component, material, supplier_id, notes)
    VALUES (btrim(p_title), p_project_id, p_jobcard_id, btrim(p_category), p_severity,
            btrim(p_description), btrim(p_responsible), who, p_due_on, p_operation, p_component,
            p_material, p_supplier_id, p_notes)
    RETURNING id, ref INTO saved, raised;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    VALUES ('ncr', saved, 'raised', who, raised || ' — ' || btrim(p_title));

    IF p_severity = 'critical' THEN
      held := place_hold(p_project_id, p_jobcard_id,
        'Critical NCR ' || raised || ' — ' || btrim(p_title), 'critical',
        'Resolve the NCR and verify the corrective action before release.', raised);
    END IF;
  ELSE
    UPDATE ncr SET title = btrim(p_title), project_id = p_project_id, jobcard_id = p_jobcard_id,
           category = btrim(p_category), severity = p_severity, description = btrim(p_description),
           responsible = btrim(p_responsible), due_on = p_due_on, operation = p_operation,
           component = p_component, material = p_material, supplier_id = p_supplier_id,
           notes = p_notes
     WHERE id = p_id AND status <> 'closed'
    RETURNING id, ref INTO saved, raised;
    IF saved IS NULL THEN
      -- Two different refusals, and the difference matters to whoever is looking at the screen.
      IF EXISTS (SELECT 1 FROM ncr WHERE id = p_id) THEN
        RAISE EXCEPTION 'that non-conformance is closed — reopen it before changing it'
          USING ERRCODE = 'check_violation';
      END IF;
      RAISE EXCEPTION 'no such non-conformance' USING ERRCODE = 'foreign_key_violation';
    END IF;
    INSERT INTO activity_log (entity, entity_id, action, actor, detail)
    VALUES ('ncr', saved, 'updated', who, raised);
  END IF;

  RETURN jsonb_build_object('ncr', raised, 'id', saved::text, 'hold', held);
END;
$$;

-- The life of a non-conformance after it is raised: contained, dispositioned, answered by a corrective
-- action, verified, closed — or reopened when it comes back.
--
-- One function rather than six, because it is one state machine. Six functions would be six places
-- deciding what 'corrective-action' follows, and they would disagree within a year.
CREATE FUNCTION record_ncr_step(
  p_id bigint,
  p_step text,
  p_text text DEFAULT NULL,
  p_ref text DEFAULT NULL
) RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('moving a non-conformance on');
  it record;
  said text := btrim(coalesce(p_text, ''));
  reference text := nullif(btrim(coalesce(p_ref, '')), '');
  moved_to ncr_status;
BEGIN
  SELECT id, ref, status, verification_result INTO it FROM ncr WHERE id = p_id;
  IF it.id IS NULL THEN
    RAISE EXCEPTION 'no such non-conformance' USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF it.status = 'closed' AND p_step <> 'reopen' THEN
    RAISE EXCEPTION 'non-conformance % is closed — reopen it first', it.ref
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_step = 'containment' THEN
    IF said = '' THEN
      RAISE EXCEPTION 'containment is what was done about it straight away — it cannot be blank'
        USING ERRCODE = 'check_violation';
    END IF;
    moved_to := CASE WHEN it.status IN ('draft', 'open', 'containment-required')
                     THEN 'under-investigation'::ncr_status ELSE it.status END;
    UPDATE ncr SET containment = said, status = moved_to WHERE id = it.id;

  ELSIF p_step = 'disposition' THEN
    IF said = '' THEN
      RAISE EXCEPTION 'a disposition says what happens to the parts' USING ERRCODE = 'check_violation';
    END IF;
    -- The database refuses this too. Raised here first because the constraint's name is not a
    -- sentence anybody standing at the screen can act on.
    IF said = 'use-as-is' AND reference IS NULL THEN
      RAISE EXCEPTION 'using a non-conforming part as it is has to be signed for — record the concession'
        USING ERRCODE = 'check_violation';
    END IF;
    moved_to := CASE WHEN it.status IN ('under-investigation', 'disposition-required')
                     THEN 'corrective-action'::ncr_status ELSE it.status END;
    UPDATE ncr SET disposition = said, disposition_approval_ref = reference, status = moved_to
     WHERE id = it.id;

  ELSIF p_step = 'corrective-action' THEN
    IF said = '' THEN
      RAISE EXCEPTION 'name the corrective action this is answered by' USING ERRCODE = 'check_violation';
    END IF;
    moved_to := 'corrective-action';
    UPDATE ncr SET corrective_action_ref = said, status = moved_to WHERE id = it.id;

  ELSIF p_step = 'verify' THEN
    IF said = '' THEN
      RAISE EXCEPTION 'verification records what was checked and how it came out'
        USING ERRCODE = 'check_violation';
    END IF;
    moved_to := 'waiting-verification';
    UPDATE ncr SET verification_result = said, verified_by = coalesce(reference, who),
           status = moved_to WHERE id = it.id;

  ELSIF p_step = 'close' THEN
    IF said = '' THEN
      RAISE EXCEPTION 'closing a non-conformance takes a closure approval reference'
        USING ERRCODE = 'check_violation';
    END IF;
    IF coalesce(btrim(it.verification_result), '') = '' THEN
      RAISE EXCEPTION 'non-conformance % has nothing verified — closing it would record that the fix worked without anybody checking',
        it.ref USING ERRCODE = 'check_violation';
    END IF;
    moved_to := 'closed';
    UPDATE ncr SET closure_approval = said, closed_on = current_date, status = moved_to
     WHERE id = it.id;

  ELSIF p_step = 'reopen' THEN
    IF said = '' THEN
      RAISE EXCEPTION 'reopening a non-conformance takes a reason — it is the record of why it came back'
        USING ERRCODE = 'check_violation';
    END IF;
    moved_to := 'reopened';
    -- The closure comes off with it. A reopened NCR still carrying its closure approval reads as
    -- approved and open at once, and the next close would leave the first approval standing behind
    -- the second one's evidence.
    UPDATE ncr SET status = moved_to, closure_approval = NULL, closed_on = NULL WHERE id = it.id;

  ELSE
    RAISE EXCEPTION 'there is no such step as %', p_step USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES ('ncr', it.id, p_step, who, it.ref || ' — ' || said || coalesce(' (' || reference || ')', ''));
  RETURN moved_to::text;
END;
$$;

-- A note against a quality record. Written into the audit trail rather than a notes column, because a
-- quality note somebody can quietly edit afterwards is worth less than no note at all — and the
-- activity log is append-only by trigger.
CREATE FUNCTION add_quality_note(p_entity text, p_entity_id bigint, p_text text) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE
  who text := require_session('adding a quality note');
  said text := btrim(coalesce(p_text, ''));
  exists_here boolean;
  made bigint;
BEGIN
  IF said = '' THEN
    RAISE EXCEPTION 'an empty note is not a note' USING ERRCODE = 'check_violation';
  END IF;
  -- The entity/id pair is not a foreign key and cannot be one, so the three tables it may name are
  -- listed and the row is checked to exist. A note against a record that is not there is a note
  -- nothing will ever show.
  IF p_entity = 'inspection' THEN
    SELECT true INTO exists_here FROM inspection WHERE id = p_entity_id;
  ELSIF p_entity = 'ncr' THEN
    SELECT true INTO exists_here FROM ncr WHERE id = p_entity_id;
  ELSIF p_entity = 'quality_hold' THEN
    SELECT true INTO exists_here FROM quality_hold WHERE id = p_entity_id;
  ELSE
    RAISE EXCEPTION 'a quality note goes on an inspection, an NCR or a hold, not on %', p_entity
      USING ERRCODE = 'check_violation';
  END IF;
  IF exists_here IS NOT TRUE THEN
    RAISE EXCEPTION 'no such %', p_entity USING ERRCODE = 'foreign_key_violation';
  END IF;

  INSERT INTO activity_log (entity, entity_id, action, actor, detail)
  VALUES (p_entity, p_entity_id, 'note', who, said)
  RETURNING id INTO made;
  RETURN made;
END;
$$;

